INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('00d1c243-0301-4212-a7dd-27a82bdc3fa0'::uuid, 'card_description', 'Into the lake of Llyn Fawr, in a glacial cirque, went two bronze cauldrons and axeheads, part of a hoard of weapons and tools that appears to have been placed as votive offerings.', 'A reservoir where a hoard of Bronze and Iron Age weapons was found during construction work. The mix of bronze and iron pieces dates it to the exact transition between the two ages.', 'teaser-card-s017-rollback:00d1c243-0301-4212-a7dd-27a82bdc3fa0:card_description', 'rollback of teaser-card-s017: card_description ''A reservoir where a hoard of Bronze and Iron Age weapons was found during construction work. The mix of bronze and iron pieces dates it to the exact transition between the two ages.'' restored on Llyn Fawr', '1757d94d9c4ecfb90fb000c71e097c3c04c7cd8c1a71e5b4a64fceafede731bf|1c4824b7835c762e3a42b35925c0983212f86fb896a07afdd55d044d8484c2ba|1c4824b7835c762e3a42b35925c0983212f86fb896a07afdd55d044d8484c2ba', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Into the lake of Llyn Fawr, in a glacial cirque, went two bronze cauldrons and axeheads, part of a hoard of weapons and tools that appears to have been placed as votive offerings."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the objects went into the lake of Llyn Fawr [S7]; Llyn Fawr lies in a glacial cirque [S1]; two bronze cauldrons and axeheads were among the items [S6]; they were part of a hoard of weapons and tools [S2]; the items appear to have been placed in the lake as votive offerings (hedged) [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Llyn Fawr is a lake (now a reservoir) in Wales (South Wales), the find-place of a hoard (central claim: a lake site in South Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Fawr]; Llyn Fawr lies in a glacial cirque [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Fawr]; The site is known for a hoard of weapons and tools [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Fawr]; Two bronze cauldrons were part of the hoard [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Fawr]; Bronze axeheads were part of the hoard [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Fawr]; The items went into the lake (were placed in the lake) [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Fawr]; The hoard appears to have been placed as votive offerings (hedged, not certain) [SUPPORTED: https://en.wikipedia.org/wiki/Llyn_Fawr]"}]'::jsonb),
    ('019573c7-aff6-4aab-848e-99063cc00b09'::uuid, 'card_description', 'On a hillside promontory above a tributary of the River Yeo, near Bratton Fleming in Devon, Smythapark holds an Iron Age hill fort, in a landscape rich in small enclosures.', 'Iron Age hill fort near Bratton Fleming, on a hillside promontory about 200 metres above sea level. The surrounding area is rich in small enclosures', 'teaser-card-s017-rollback:019573c7-aff6-4aab-848e-99063cc00b09:card_description', 'rollback of teaser-card-s017: card_description ''Iron Age hill fort near Bratton Fleming, on a hillside promontory about 200 metres above sea level. The surrounding area is rich in small enclosures'' restored on Smythapark', 'b535bf1bbb68c1a7bb6ea3a0fca2a0d9c302751ad55aae657c217fe4027c7581|e7e206e20fc5daa7b8ccc29c8ede5518f068811ba668e8ab7ee3ed5ae68db108|e7e206e20fc5daa7b8ccc29c8ede5518f068811ba668e8ab7ee3ed5ae68db108', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a hillside promontory above a tributary of the River Yeo, near Bratton Fleming in Devon, Smythapark holds an Iron Age hill fort, in a landscape rich in small enclosures."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "on a hillside promontory above a tributary of the River Yeo [S2]; near Bratton Fleming in Devon [S1]; Smythapark holds an Iron Age hill fort [S1]; the landscape is rich in small enclosures [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Smythapark holds an Iron Age hill fort (central claim: a hill fort) [SUPPORTED: https://en.wikipedia.org/wiki/Smythapark]; It lies near Bratton Fleming in Devon [SUPPORTED: https://en.wikipedia.org/wiki/Smythapark]; The site is on a hillside promontory [SUPPORTED: https://en.wikipedia.org/wiki/Smythapark]; The promontory lies above a tributary of the River Yeo [SUPPORTED: https://en.wikipedia.org/wiki/Smythapark]; The surrounding landscape is rich in small enclosures [SUPPORTED: https://en.wikipedia.org/wiki/Smythapark]"}]'::jsonb),
    ('0294d74b-0e97-4509-913a-475e3c21e1a7'::uuid, 'card_description', 'In a private garden in Żurrieq stands a 5.6 m-high tower of limestone blocks laid without mortar, crowned by an Egyptian-inspired cornice. The Punic Building''s age and purpose are not known.', 'The building''s existence was first recorded by Bishop Miguel Jerónimo de Molina in 1680.', 'teaser-card-s017-rollback:0294d74b-0e97-4509-913a-475e3c21e1a7:card_description', 'rollback of teaser-card-s017: card_description "The building''s existence was first recorded by Bishop Miguel Jerónimo de Molina in 1680." restored on Punic Building, Żurrieq', '118ef582abe08dab8bd60de4e8ecefb158e84969e860ba84ce415bb8eefaa71c|599d5d0869843db58433ef688c6cd2a7b79970fd329504fe219409133ba7e4c1|599d5d0869843db58433ef688c6cd2a7b79970fd329504fe219409133ba7e4c1', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In a private garden in Żurrieq stands a 5.6 m-high tower of limestone blocks laid without mortar, crowned by an Egyptian-inspired cornice. The Punic Building''s age and purpose are not known."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "stands in a private garden in Zurrieq [S2]; a 5.6 m-high tower [S3]; of limestone blocks laid without mortar [S4]; crowned by a cornice inspired by ancient Egyptian architecture [S3]; the building''s age and purpose are not known [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Punic Building in Żurrieq, Malta, is a surviving Punic-period building whose best-preserved part is a tower (central claim: a Punic tower-building in Żurrieq) [SUPPORTED: https://en.wikipedia.org/wiki/Punic_building,_%C5%BBurrieq]; The tower stands in a private garden in Żurrieq [SUPPORTED: https://en.wikipedia.org/wiki/Punic_building,_%C5%BBurrieq]; The tower is 5.6 m high and topped by a cornice showing inspiration from ancient Egyptian architecture (cavetto cornice) [SUPPORTED: https://en.wikipedia.org/wiki/Punic_building,_%C5%BBurrieq]; The height of the tower is 5.6 m [SUPPORTED: https://en.wikipedia.org/wiki/Punic_building,_%C5%BBurrieq]; The tower is built of limestone blocks laid without mortar [SUPPORTED: https://en.wikipedia.org/wiki/Punic_building,_%C5%BBurrieq]; The building''s age and purpose are not known [SUPPORTED: https://en.wikipedia.org/wiki/Punic_building,_%C5%BBurrieq]"}]'::jsonb),
    ('0312b756-2f79-4b8e-bcef-d00885080bca'::uuid, 'card_description', 'Begun on 23 August 237 BC on the west bank of the Nile, the Temple of Horus at Edfu still keeps a naos of Nectanebo II in its inner sanctuary, a relic from an earlier building.', 'Built 237–57 BC during the Ptolemaic period, this temple at Edfu stands in near-complete condition. Its inscribed walls are a primary source for Hellenistic-era myth, religious language, and ritual.', 'teaser-card-s017-rollback:0312b756-2f79-4b8e-bcef-d00885080bca:card_description', 'rollback of teaser-card-s017: card_description ''Built 237–57 BC during the Ptolemaic period, this temple at Edfu stands in near-complete condition. Its inscribed walls are a primary source for Hellenistic-era myth, religious language, and ritual.'' restored on The Temple of Horus at Edfu', '848bb686e0b2dc89d33d1e5a7baad8caa69e71dbf6c568d61d1d08e2dcd90650|cd4364b24af95e8bde8421436715b38ffb73a4db0f0b018eb6a5c93b4bb4b91d|cd4364b24af95e8bde8421436715b38ffb73a4db0f0b018eb6a5c93b4bb4b91d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Begun on 23 August 237 BC on the west bank of the Nile, the Temple of Horus at Edfu still keeps a naos of Nectanebo II in its inner sanctuary, a relic from an earlier building."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "begun on 23 August 237 BC [S4]; on the west bank of the Nile [S1]; a naos of Nectanebo II is preserved in the inner sanctuary [S6]; the naos is a relic from an earlier building [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Temple of Horus at Edfu is an Egyptian temple on the west bank of the Nile (central claim: a temple, at Edfu, Upper Egypt) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Edfu]; The temple is dedicated to Horus [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Edfu]; The present temple was begun on 23 August 237 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Edfu]; A naos of Nectanebo II is preserved in the inner sanctuary of the temple [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Edfu]; The naos is a relic from an earlier building [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Edfu]"}]'::jsonb),
    ('035aa343-1776-4667-8162-4f295287f6cc'::uuid, 'card_description', 'Tradition says an Indian monk founded Lingyin Temple, the Temple of the Soul''s Retreat near Hangzhou, in 328 AD. At its peak it boasted 72 halls and more than 3000 monks.', 'Founded in 328 AD in Hangzhou, this Chan Buddhist temple''s surrounding cliffs hold hundreds of carved Buddha images. It ranks among the wealthiest Buddhist institutions in the country.', 'teaser-card-s017-rollback:035aa343-1776-4667-8162-4f295287f6cc:card_description', 'rollback of teaser-card-s017: card_description "Founded in 328 AD in Hangzhou, this Chan Buddhist temple''s surrounding cliffs hold hundreds of carved Buddha images. It ranks among the wealthiest Buddhist institutions in the country." restored on Lingyin Temple', '8da266509b6e1b27163f260dcb585915f34461368966813575fee0ef6d0d704a|6bb0e5067b69f18debfbed074017c41d18cea31542313595df5f186245d8ed3c|6bb0e5067b69f18debfbed074017c41d18cea31542313595df5f186245d8ed3c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tradition says an Indian monk founded Lingyin Temple, the Temple of the Soul''s Retreat near Hangzhou, in 328 AD. At its peak it boasted 72 halls and more than 3000 monks."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "by tradition an Indian monk founded the temple [S4]; founded in 328 AD [S4]; Lingyin Temple is the Temple of the Soul''s Retreat [S2]; near Hangzhou [S1]; at its peak it had 72 halls [S6]; at its peak more than 3000 monks [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Lingyin Temple is a Buddhist (Chan) temple near Hangzhou, China (central claim: a temple near Hangzhou) [SUPPORTED: https://en.wikipedia.org/wiki/Lingyin_Temple]; Lingyin Temple is commonly translated as the Temple of the Soul''s Retreat [SUPPORTED: https://en.wikipedia.org/wiki/Lingyin_Temple]; According to tradition the temple was founded in 328 AD [SUPPORTED: https://en.wikipedia.org/wiki/Lingyin_Temple]; The traditional founder was an Indian monk [SUPPORTED: https://en.wikipedia.org/wiki/Lingyin_Temple]; At its peak the temple had 72 halls [SUPPORTED: https://en.wikipedia.org/wiki/Lingyin_Temple]; At its peak the temple housed more than 3000 monks [SUPPORTED: https://en.wikipedia.org/wiki/Lingyin_Temple]"}]'::jsonb),
    ('0371ed0a-82f5-4578-b7bf-10dc40faf580'::uuid, 'card_description', 'Baalbek''s colossal Imperial Roman structures became a World Heritage Site in 1984. At the Temple of Jupiter, a deep trench pushed Tell Baalbek''s settlement back to the PPNB Neolithic.', 'The Tell Baalbek temple complex, fortified as the town''s citadel during the Middle Ages, was constructed from local stone, mostly white granite and a rough white marble.', 'teaser-card-s017-rollback:0371ed0a-82f5-4578-b7bf-10dc40faf580:card_description', 'rollback of teaser-card-s017: card_description "The Tell Baalbek temple complex, fortified as the town''s citadel during the Middle Ages, was constructed from local stone, mostly white granite and a rough white marble." restored on Baalbek', '2857604c619e76e00f164269d6e41c9fc0b6ae4b1e6a06ba8961d77af5b6cf38|3983a1a09800e7fef224c60dbc5aca421a84cf493497bc889026734d19ccc2f4|3983a1a09800e7fef224c60dbc5aca421a84cf493497bc889026734d19ccc2f4', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Baalbek''s colossal Imperial Roman structures became a World Heritage Site in 1984. At the Temple of Jupiter, a deep trench pushed Tell Baalbek''s settlement back to the PPNB Neolithic."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Baalbek has colossal structures [S3]; the structures are Imperial Roman [S3]; Baalbek became a World Heritage Site [S3]; it became a World Heritage Site in 1984 [S3]; a deep trench was found at the Temple of Jupiter [S4]; study of the trench pushed back the date of Tell Baalbek''s settlement to the PPNB Neolithic [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Baalbek is a site of Roman temple ruins (Temple of Bacchus, Temple of Jupiter) in Lebanon [SUPPORTED: https://en.wikipedia.org/wiki/Baalbek]; Baalbek is located in Lebanon (Beqaa Valley) [SUPPORTED: https://en.wikipedia.org/wiki/Baalbek]; Baalbek''s structures are colossal and Imperial Roman [SUPPORTED: https://en.wikipedia.org/wiki/Baalbek]; Baalbek became a World Heritage Site in 1984 [SUPPORTED: https://en.wikipedia.org/wiki/Baalbek]; A deep trench at the edge of the Temple of Jupiter was studied [SUPPORTED: https://en.wikipedia.org/wiki/Baalbek]; The trench pushed the settlement of Tell Baalbek back to the PPNB Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Baalbek]"}]'::jsonb),
    ('05d60350-c231-4179-851b-380505d30a87'::uuid, 'card_description', 'On the summit of a steep hill in east Penzance, a single rampart encloses 3 acres: Lescudjack Hill Fort, an Iron Age settlement traditionally called a castle, which named the road beside it.', 'Lescudjack Hill fort is the name given to the unexcavated Iron Age settlement located in Penzance, Cornwall.', 'teaser-card-s017-rollback:05d60350-c231-4179-851b-380505d30a87:card_description', 'rollback of teaser-card-s017: card_description ''Lescudjack Hill fort is the name given to the unexcavated Iron Age settlement located in Penzance, Cornwall.'' restored on Lescudjack Hill Fort', '0ef18498b2dc22910424c867c0fb1321e656cb174c997517a5834c362302e5b0|d0b0cf170bdfd69c97ba94b00f7f6b7214a0e64ef15ca4f14ed28530d9ec5a15|d0b0cf170bdfd69c97ba94b00f7f6b7214a0e64ef15ca4f14ed28530d9ec5a15', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the summit of a steep hill in east Penzance, a single rampart encloses 3 acres: Lescudjack Hill Fort, an Iron Age settlement traditionally called a castle, which named the road beside it."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is on the summit of a steep hill [S2]; the hill is in the east of Penzance [S2]; a single rampart encloses the site [S2]; the rampart encloses 3 acres [S2]; Lescudjack Hill Fort is an Iron Age settlement [S1]; the site was traditionally called a castle [S3]; the road beside the site (Castle Road) was named after the castle name [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Lescudjack Hill Fort is a hill fort, an Iron Age settlement [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]; Lescudjack Hill Fort is in Penzance, Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]; It stands on the summit of a hill [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]; The hill is steep [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]; The fort lies in the east of Penzance [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]; The fort has a single rampart [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]; The rampart encloses 3 acres [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]; The site is traditionally called a castle [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]; A road beside the site (Castle Road) runs alongside it [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]; That road was named after the castle [SUPPORTED: https://en.wikipedia.org/wiki/Lescudjack_Hill_Fort]"}]'::jsonb),
    ('06a73089-340c-40ac-9979-4a5c08f93da5'::uuid, 'card_description', 'Within the Iron Age earthworks of Cissbury Ring lies a Neolithic flint mine: around 270 shafts, up to 12 metres deep, dug with antler picks over around 300 years of use.', 'The earthworks that form the fortifications were built around the beginning of the Middle Iron-Age possibly around 250 BC but abandoned in the period 50 BC - 50 AD.', 'teaser-card-s017-rollback:06a73089-340c-40ac-9979-4a5c08f93da5:card_description', 'rollback of teaser-card-s017: card_description ''The earthworks that form the fortifications were built around the beginning of the Middle Iron-Age possibly around 250 BC but abandoned in the period 50 BC - 50 AD.'' restored on Cissbury Ring', 'b3c033ebd69fb21dc4e49972eaf981bc7e718a7e39baabcf54d1cc67d723706b|18ad5b78bcde162b508abbe718a64f4f2afc1d9364622a7f2222696af5b9fd06|18ad5b78bcde162b508abbe718a64f4f2afc1d9364622a7f2222696af5b9fd06', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Within the Iron Age earthworks of Cissbury Ring lies a Neolithic flint mine: around 270 shafts, up to 12 metres deep, dug with antler picks over around 300 years of use."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Iron Age earthworks at Cissbury Ring [S2, S3]; a Neolithic flint mine lies within [S2, S4]; around 270 shafts [S5]; up to 12 metres deep [S6]; dug with antler picks [S8]; over around 300 years of use [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cissbury Ring is an Iron Age hillfort with earthworks, in West Sussex, England, and the site of a Neolithic flint mine. [SUPPORTED: https://en.wikipedia.org/wiki/Cissbury_Ring]; The Neolithic flint mine lies within the Iron Age earthworks (defences) of Cissbury Ring. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA205058]; The mine has around 270 shafts. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA205058]; The shafts are up to 12 metres deep. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA205058]; The shafts were dug with antler picks. [SUPPORTED: https://en.wikipedia.org/wiki/Cissbury_Ring]; The shafts were dug over around 300 years of use. [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('07ca1c0c-550e-41ab-ab5d-5563fce29d90'::uuid, 'card_description', 'Older than the pyramids of Egypt, the Ġgantija temples stand at the edge of the Xagħra plateau: two Neolithic temples, the southerly one dating to around 3600 BC, and an incomplete third.', 'Two megalithic temples built 3600–2500 BC, predating the pyramids of Egypt and Stonehenge. The earliest temple complex on these islands, built from coralline and globigerina limestone.', 'teaser-card-s017-rollback:07ca1c0c-550e-41ab-ab5d-5563fce29d90:card_description', 'rollback of teaser-card-s017: card_description ''Two megalithic temples built 3600–2500 BC, predating the pyramids of Egypt and Stonehenge. The earliest temple complex on these islands, built from coralline and globigerina limestone.'' restored on Ġgantija', '1c3b4383cc5f4af657049e5a49fc0c952e3ece1341c44796efdbc1556165675b|463beb171539c1fe343b7b93580fb4226688335559c63e78ac04ad49fc259195|463beb171539c1fe343b7b93580fb4226688335559c63e78ac04ad49fc259195', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Older than the pyramids of Egypt, the Ġgantija temples stand at the edge of the Xagħra plateau: two Neolithic temples, the southerly one dating to around 3600 BC, and an incomplete third."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Ġgantija temples are older than the pyramids of Egypt [S1]; the temples stand at the edge of the Xagħra plateau [S5]; there are two temples [S2, S6]; the two temples are Neolithic [S2]; the southerly temple dates to around 3600 BC [S7]; there is an incomplete third temple [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ġgantija is a megalithic temple complex of the Neolithic era [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A0gantija]; Ġgantija is in Malta (on the island of Gozo) [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A0gantija]; The Ġgantija temples are older than the pyramids of Egypt [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A0gantija]; The temples stand at the edge of the Xagħra plateau [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A0gantija]; There are two temples and an incomplete third [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A0gantija]; The two Ġgantija temples are Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A0gantija]; The southerly temple dates to around 3600 BC [SUPPORTED: https://en.wikipedia.org/wiki/%C4%A0gantija]"}]'::jsonb),
    ('08122cd2-522f-4ebc-b363-aabc7bd60de3'::uuid, 'card_description', 'The Ringlemere gold cup was found at Ringlemere Barrow near Sandwich, a mound now ploughed away that once stood as high as 5m, yet no burials of its own time have been found there.', 'Considerable evidence of much earlier Neolithic activity has now been found on the site including by far the largest assemblage of grooved ware in the county.', 'teaser-card-s017-rollback:08122cd2-522f-4ebc-b363-aabc7bd60de3:card_description', 'rollback of teaser-card-s017: card_description ''Considerable evidence of much earlier Neolithic activity has now been found on the site including by far the largest assemblage of grooved ware in the county.'' restored on Ringlemere Barrow', 'f1dda4e3e6b624012d3122930bad04d2355c37c0e8e73c7cb9a7698e502bcff0|07b3995ccf149776e16f3e722def3c5caaaca74d8362105216e455c2f9447c52|07b3995ccf149776e16f3e722def3c5caaaca74d8362105216e455c2f9447c52', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Ringlemere gold cup was found at Ringlemere Barrow near Sandwich, a mound now ploughed away that once stood as high as 5m, yet no burials of its own time have been found there."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Ringlemere gold cup was found at the barrow [S1]; near Sandwich [S1]; the mound is now ploughed away [S4]; it once stood as high as 5m [S4]; no contemporary burials have been found [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ringlemere Barrow is a barrow (burial mound) near Sandwich in Kent, England. [SUPPORTED: https://en.wikipedia.org/wiki/Ringlemere_barrow]; The Ringlemere gold cup was found at Ringlemere Barrow. [SUPPORTED: https://en.wikipedia.org/wiki/Ringlemere_Cup]; The mound has now been ploughed away. [SUPPORTED: https://www.kentarchaeology.org.uk/magazine/57/01-ringlemere-2003]; The mound once stood as high as 5 m. [SUPPORTED: https://en.wikipedia.org/wiki/Ringlemere_barrow]; No burials of the barrow''s own time (Early Bronze Age) have been found there. [SUPPORTED: https://www.kentarchaeology.org.uk/journal/143/ringlemere-investigation-prehistoric-ring-ditches-m2-m3]"}]'::jsonb),
    ('08508ff0-053d-4b8e-b2a3-6382818c6735'::uuid, 'card_description', 'Known anciently as Ake, and nearby as Usiij Witz, Vulture Hill, the Maya site of Bonampak in Chiapas rose in the Late Classic period as a dependency of the larger Yaxchilan.', 'Structure 1 at Bonampak, built at the end of the eighth century A.D. measures 16 meters long, four meters deep, and seven meters tall, and is constructed atop a T-shaped platform.', 'teaser-card-s017-rollback:08508ff0-053d-4b8e-b2a3-6382818c6735:card_description', 'rollback of teaser-card-s017: card_description ''Structure 1 at Bonampak, built at the end of the eighth century A.D. measures 16 meters long, four meters deep, and seven meters tall, and is constructed atop a T-shaped platform.'' restored on Bonampak', '5b65489f9d89c28218542a62fd9ce7e1ee02e2f2b0d0ab8f307dafb109e33713|7cf5571e668cf89dbbcb26dd44f5c5c9dcf06606f399f04707cf070416f34020|7cf5571e668cf89dbbcb26dd44f5c5c9dcf06606f399f04707cf070416f34020', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Known anciently as Ake, and nearby as Usiij Witz, Vulture Hill, the Maya site of Bonampak in Chiapas rose in the Late Classic period as a dependency of the larger Yaxchilan."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "known anciently as Ake [S1]; in its immediate area Usiij Witz, Vulture Hill [S1]; Maya site in Chiapas [S1]; rose in the Late Classic period [S3]; a dependency of the larger Yaxchilan [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Bonampak is an ancient Maya archaeological site in Chiapas, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Bonampak]; Bonampak was known anciently as Ake [SUPPORTED: https://en.wikipedia.org/wiki/Bonampak]; In its immediate area the site was known as Usiij Witz, ''Vulture Hill'' [SUPPORTED: https://en.wikipedia.org/wiki/Bonampak]; The site rose in the Late Classic period [SUPPORTED: https://en.wikipedia.org/wiki/Bonampak]; Bonampak was a dependency of the larger site of Yaxchilan [SUPPORTED: https://en.wikipedia.org/wiki/Bonampak]"}]'::jsonb),
    ('0989a7d5-9fa2-447d-a774-5f5b8351fd27'::uuid, 'card_description', 'Around 100 pairs of standing stones once lined Kennet Avenue for 2.5 km between Avebury and The Sanctuary. Today 27 upright stones remain, and concrete pillars mark where others stood.', 'A 2.5 km avenue of paired standing stones from 2200 BC, linking Avebury to The Sanctuary. Around 100 pairs originally lined this Neolithic processional route.', 'teaser-card-s017-rollback:0989a7d5-9fa2-447d-a774-5f5b8351fd27:card_description', 'rollback of teaser-card-s017: card_description ''A 2.5 km avenue of paired standing stones from 2200 BC, linking Avebury to The Sanctuary. Around 100 pairs originally lined this Neolithic processional route.'' restored on Kennet Avenue', 'ac416e6c3d386a9555d57eaae5ef6529792afbfc383efc934170b5ac47c0b5b9|bde85b18d2390f87d620e27cb0034dbda33a8e0e156301845424f657172d6f24|bde85b18d2390f87d620e27cb0034dbda33a8e0e156301845424f657172d6f24', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Around 100 pairs of standing stones once lined Kennet Avenue for 2.5 km between Avebury and The Sanctuary. Today 27 upright stones remain, and concrete pillars mark where others stood."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "around 100 pairs of standing stones once lined the avenue [S4]; for 2.5 km [S2]; between Avebury and The Sanctuary [S2]; 27 upright stones remain today [S3]; concrete pillars mark where others stood [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kennet Avenue is a prehistoric avenue of standing stones in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Kennet_Avenue]; It was an avenue of two parallel lines of stones 2.5 km long [SUPPORTED: https://en.wikipedia.org/wiki/Kennet_Avenue]; The avenue ran between Avebury and The Sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Kennet_Avenue]; Around 100 pairs of standing stones once lined the avenue [SUPPORTED: https://en.wikipedia.org/wiki/Kennet_Avenue]; Today 27 upright stones remain [SUPPORTED: https://en.wikipedia.org/wiki/Kennet_Avenue]; Concrete pillars mark where other stones stood [SUPPORTED: https://en.wikipedia.org/wiki/Kennet_Avenue]"}]'::jsonb),
    ('0a36e25e-4aaa-431f-bcde-843fc01353a1'::uuid, 'card_description', 'On the Vía de la Plata, the Roman Bridge of Salamanca crosses the Tormes River, its stretch toward the city still mostly original Roman work. Its exact date of construction is unknown.', 'A Roman bridge whose image appears on the city''s coat of arms. It crossed the Tormes starting from the 1st century BC and is still standing.', 'teaser-card-s017-rollback:0a36e25e-4aaa-431f-bcde-843fc01353a1:card_description', 'rollback of teaser-card-s017: card_description "A Roman bridge whose image appears on the city''s coat of arms. It crossed the Tormes starting from the 1st century BC and is still standing." restored on Roman Bridge of Salamanca', '284c3afd057c94fa45ce2d9312749be5000912fe998c198fcc0e385bf21b751e|acae92cf09c404745b815f50b943898267f339599e5919e3c3a4187967a5ebb2|acae92cf09c404745b815f50b943898267f339599e5919e3c3a4187967a5ebb2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the Vía de la Plata, the Roman Bridge of Salamanca crosses the Tormes River, its stretch toward the city still mostly original Roman work. Its exact date of construction is unknown."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "on the Via de la Plata [S2]; crosses the Tormes River [S1]; its stretch toward the city is still mostly original Roman work [S3]; the exact date of construction is unknown [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Roman Bridge of Salamanca is a Roman bridge crossing the Tormes River in the city of Salamanca, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Salamanca]; The bridge lies on the Vía de la Plata [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Salamanca]; The stretch toward the city (right bank) retains the majority of the original Roman construction [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Salamanca]; The exact date of construction of the bridge is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Roman_bridge_of_Salamanca]"}]'::jsonb),
    ('0ac27bb1-9767-4302-bcfc-0480349aaf1b'::uuid, 'card_description', 'In Phoenix Park near Dublin, a water-worn capstone thought to come from the River Liffey crowns Knockmaree Dolmen, a Neolithic cist found in 1838 when workmen removed its mound.', 'A Neolithic cist tomb from 3000-2500 BC with a capstone carried from a nearby river. The burial chamber sits on a small ridge in a city park.', 'teaser-card-s017-rollback:0ac27bb1-9767-4302-bcfc-0480349aaf1b:card_description', 'rollback of teaser-card-s017: card_description ''A Neolithic cist tomb from 3000-2500 BC with a capstone carried from a nearby river. The burial chamber sits on a small ridge in a city park.'' restored on Knockmaree Dolmen', 'df90aaac36f087c9c437972d03bf9f361a4dc2bc3f0c604856fdb6be930a50d9|999a1d73ad4014313edcdd1be59a7fcaaed9ad012249f2aaaf231af1f469dd79|999a1d73ad4014313edcdd1be59a7fcaaed9ad012249f2aaaf231af1f469dd79', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Phoenix Park near Dublin, a water-worn capstone thought to come from the River Liffey crowns Knockmaree Dolmen, a Neolithic cist found in 1838 when workmen removed its mound."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "in Phoenix Park near Dublin [S1]; a water-worn capstone [S4]; thought to come from the River Liffey [S4]; the capstone crowns the dolmen [S3]; a Neolithic cist [S1, S2]; found in 1838 when workmen removed its mound [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Knockmaree Dolmen is a prehistoric site of the Neolithic period [SUPPORTED: https://en.wikipedia.org/wiki/Knockmaree_Dolmen]; It lies in Phoenix Park [SUPPORTED: https://en.wikipedia.org/wiki/Knockmaree_Dolmen]; It is near Dublin, Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Knockmaree_Dolmen]; The tomb is a cist [SUPPORTED: https://en.wikipedia.org/wiki/Knockmaree_Dolmen]; The capstone that crowns the tomb, supported by smaller stones, is water-worn [SUPPORTED: https://en.wikipedia.org/wiki/Knockmaree_Dolmen]; The capstone is thought to come from the River Liffey [SUPPORTED: https://en.wikipedia.org/wiki/Knockmaree_Dolmen]; The cist was discovered in 1838 [SUPPORTED: https://en.wikipedia.org/wiki/Knockmaree_Dolmen]; It was found when workmen removed its mound [SUPPORTED: https://en.wikipedia.org/wiki/Knockmaree_Dolmen]"}]'::jsonb),
    ('0ae727b3-6355-47ad-9c47-2c5f01a3bc20'::uuid, 'card_description', 'Early in August 2006, an excavation in Praileaitz Cave, the Rock of the Monk cave, found paleolithic paintings of red dots, surmised to be from around 15,500 years ago.', 'A Paleolithic cave with paintings of red dot patterns dating to around 16,000 BC. It also yielded an unusual collection of portable art on pebbles with abstract motifs.', 'teaser-card-s017-rollback:0ae727b3-6355-47ad-9c47-2c5f01a3bc20:card_description', 'rollback of teaser-card-s017: card_description ''A Paleolithic cave with paintings of red dot patterns dating to around 16,000 BC. It also yielded an unusual collection of portable art on pebbles with abstract motifs.'' restored on Praileaitz Cave', '0b2555c36b52707530e5c3c8d23923497fa53f279a1c9a8f0db522f734bec0ef|3f2c58c85d556f4c6d82e27d2a5e638c8d6ffdbfbdcb578ae24c4fcbddf439ec|3f2c58c85d556f4c6d82e27d2a5e638c8d6ffdbfbdcb578ae24c4fcbddf439ec', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Early in August 2006, an excavation in Praileaitz Cave, the Rock of the Monk cave, found paleolithic paintings of red dots, surmised to be from around 15,500 years ago."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "early in August 2006 [S2]; found during an excavation [S2]; Praileaitz means Rock of the Monk [S1]; paleolithic paintings of red dots [S2]; surmised to be around 15,500 years old [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Praileaitz Cave is a cave in Deba (Gipuzkoa), Basque Country, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Praileaitz_Cave]; Praileaitz means Rock of the Monk cave in Basque [SUPPORTED: https://en.wikipedia.org/wiki/Praileaitz_Cave]; Early in August 2006 paleolithic paintings were found during an archaeological excavation [SUPPORTED: https://en.wikipedia.org/wiki/Praileaitz_Cave]; The paintings are groups of red dots [SUPPORTED: https://en.wikipedia.org/wiki/Praileaitz_Cave]; Researchers surmised the paintings date from around 15,500 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Praileaitz_Cave]"}]'::jsonb),
    ('0beaf7bd-7e6d-44f2-8f4f-7c3050b5d2b4'::uuid, 'card_description', 'Two colossi 18 meters high still guard the Mortuary Temple of Amenhotep III, once the largest funerary complex in Thebes, largely ruined by an earthquake around 1200 BC.', 'Once the largest funerary complex in Thebes, now almost entirely destroyed by floods and stone quarrying. Only the Colossi of Memnon — two 18-metre seated statues — remain standing.', 'teaser-card-s017-rollback:0beaf7bd-7e6d-44f2-8f4f-7c3050b5d2b4:card_description', 'rollback of teaser-card-s017: card_description ''Once the largest funerary complex in Thebes, now almost entirely destroyed by floods and stone quarrying. Only the Colossi of Memnon — two 18-metre seated statues — remain standing.'' restored on Mortuary Temple of Amenhotep III', 'e1f248350b1adddbb9e2dc0f75653267d717e28ee82b201e258c931ed2367ff7|4b284e1efaad3f33c3de2f0c9710fd4be1a6159440bee33ad8ba0daee51d53b5|4b284e1efaad3f33c3de2f0c9710fd4be1a6159440bee33ad8ba0daee51d53b5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Two colossi 18 meters high still guard the Mortuary Temple of Amenhotep III, once the largest funerary complex in Thebes, largely ruined by an earthquake around 1200 BC."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "two colossi stand at the temple, guarding it [S4]; the colossi are 18 meters high [S4]; the colossi still remain and guard the entrance of the Mortuary Temple of Amenhotep III [S4]; the temple was once the largest funerary complex in Thebes [S3]; the temple was largely ruined by an earthquake [S5]; the earthquake occurred around 1200 BC [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Mortuary Temple of Amenhotep III is a mortuary (funerary) temple at Thebes, on the west bank of the Nile opposite Luxor, Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Mortuary_Temple_of_Amenhotep_III]; Two colossi still guard (stand at the entrance of) the temple [SUPPORTED: https://en.wikipedia.org/wiki/Mortuary_Temple_of_Amenhotep_III]; The two colossi are 18 meters high [SUPPORTED: https://en.wikipedia.org/wiki/Mortuary_Temple_of_Amenhotep_III]; It was once the largest funerary complex in Thebes [SUPPORTED: https://en.wikipedia.org/wiki/Mortuary_Temple_of_Amenhotep_III]; The temple was largely ruined by an earthquake [SUPPORTED: https://en.wikipedia.org/wiki/Mortuary_Temple_of_Amenhotep_III]; The earthquake occurred around 1200 BC [SUPPORTED: https://en.wikipedia.org/wiki/Mortuary_Temple_of_Amenhotep_III]"}]'::jsonb),
    ('0c879c8d-da82-4297-be35-796650ca0765'::uuid, 'card_description', 'Across the plateau of Mynydd Illtud the Roman road Sarn Helen can still be traced, while on the grassy mound of Twyn y Gaer an Iron Age hillfort overlooks the valley of the River Usk.', 'Roman practice camp earthworks and a hillfort share this plateau above Libanus in the Brecon Beacons. Rectangular outlines left by Roman military drills remain legible in the ground today.', 'teaser-card-s017-rollback:0c879c8d-da82-4297-be35-796650ca0765:card_description', 'rollback of teaser-card-s017: card_description ''Roman practice camp earthworks and a hillfort share this plateau above Libanus in the Brecon Beacons. Rectangular outlines left by Roman military drills remain legible in the ground today.'' restored on Mynydd Illtud', '33e668e9d05209697e634187e84751a19a56fcc6956c21f86b3e108861e69511|725ac1f10f5ea50e7f574a54516196abf994c48017428bdf69389f45142c174e|725ac1f10f5ea50e7f574a54516196abf994c48017428bdf69389f45142c174e', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Across the plateau of Mynydd Illtud the Roman road Sarn Helen can still be traced, while on the grassy mound of Twyn y Gaer an Iron Age hillfort overlooks the valley of the River Usk."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mynydd Illtud is an undulating plateau [S2]; the course of the Roman road Sarn Helen can be traced across the common [S7]; Twyn y Gaer is a grassy mound with an Iron Age hillfort on top [S4, S5]; Twyn y Gaer overlooks the valley of the River Usk [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mynydd Illtud is an area of upland common land in Wales (Brecon Beacons, Powys) [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Illtud]; Mynydd Illtud is a plateau [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Illtud]; The Roman road Sarn Helen can still be traced across the plateau [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Illtud]; Twyn y Gaer is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Illtud]; The hillfort sits on a grassy mound [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Illtud]; Twyn y Gaer overlooks the valley of the River Usk [SUPPORTED: https://en.wikipedia.org/wiki/Mynydd_Illtud]"}]'::jsonb),
    ('0e0531f8-6b94-43ab-b6db-81611a30e297'::uuid, 'card_description', 'Boulders set in a double arc, its ends pointing to the cardinal points: the Carisbrook Stone Arrangement in Victoria, an Aboriginal site some consider a male initiation ground.', 'One of only four Aboriginal stone arrangements in Victoria and the only one in a boomerang design. Sixty metres long, with a double arc of boulders, cairn, and small stone circles.', 'teaser-card-s017-rollback:0e0531f8-6b94-43ab-b6db-81611a30e297:card_description', 'rollback of teaser-card-s017: card_description ''One of only four Aboriginal stone arrangements in Victoria and the only one in a boomerang design. Sixty metres long, with a double arc of boulders, cairn, and small stone circles.'' restored on Carisbrook Stone Arrangement', '59c9c1dd32796de01e9c1356ab6fec846d2c54e99a097d5e093fb44af2557df2|d9182fbaf734f8cba19a4fad492ce15e9eecfcb3265a399171ffd1e8143d997b|d9182fbaf734f8cba19a4fad492ce15e9eecfcb3265a399171ffd1e8143d997b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Boulders set in a double arc, its ends pointing to the cardinal points: the Carisbrook Stone Arrangement in Victoria, an Aboriginal site some consider a male initiation ground."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site has boulders set in a double arc [S2]; the ends of the arc point to the cardinal points [S3]; the Carisbrook Stone Arrangement is in Victoria [S1]; it is an Aboriginal site [S1]; some consider it a male initiation ground [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Carisbrook Stone Arrangement is a stone arrangement (a site of set stones) in Victoria, Australia [SUPPORTED: https://en.wikipedia.org/wiki/Carisbrook_stone_arrangement]; It is an Aboriginal site [SUPPORTED: https://en.wikipedia.org/wiki/Carisbrook_stone_arrangement]; It is made of boulders [SUPPORTED: https://en.wikipedia.org/wiki/Carisbrook_stone_arrangement]; The boulders are set in a double arc [SUPPORTED: https://en.wikipedia.org/wiki/Carisbrook_stone_arrangement]; The ends of the arc point to the cardinal points [SUPPORTED: https://en.wikipedia.org/wiki/Carisbrook_stone_arrangement]; Some consider the site a male initiation ground [SUPPORTED: https://en.wikipedia.org/wiki/Carisbrook_stone_arrangement]"}]'::jsonb),
    ('0e368bbc-87e1-42e4-b521-62b036c9be03'::uuid, 'card_description', 'Atop Conwy Mountain, Castell Caer Seion hides a smaller, more heavily defended fort inside the main one, with no obvious way between the two. Around 50 roundhouses stood in the larger fort.', 'Conwy Mountain fort with a second, more heavily defended enclosure nested inside it. The inner fort has its own distinct defences and entrance, with no obvious connection to the outer ring.', 'teaser-card-s017-rollback:0e368bbc-87e1-42e4-b521-62b036c9be03:card_description', 'rollback of teaser-card-s017: card_description ''Conwy Mountain fort with a second, more heavily defended enclosure nested inside it. The inner fort has its own distinct defences and entrance, with no obvious connection to the outer ring.'' restored on Castell Caer Seion', 'f4f835caac020973a7500211c6c3e6ae815b4a797d4254e6410284bb7168feee|afb2b1531589874e3db575db9beda5e1f9c577a96703c1f276d1b0e028667e61|afb2b1531589874e3db575db9beda5e1f9c577a96703c1f276d1b0e028667e61', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Atop Conwy Mountain, Castell Caer Seion hides a smaller, more heavily defended fort inside the main one, with no obvious way between the two. Around 50 roundhouses stood in the larger fort."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castell Caer Seion is atop Conwy Mountain [S1]; a smaller fort lies inside the main fort [S2]; the smaller fort is more heavily defended [S2]; there is no obvious means of access between the two forts [S2]; around 50 roundhouses were in the larger fort [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castell Caer Seion is a fort (an Iron Age hillfort) [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Caer_Seion]; It stands atop Conwy Mountain [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Caer_Seion]; The main fort contains a smaller fort inside it [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Caer_Seion]; The smaller inner fort is more heavily defended than the main fort [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Caer_Seion]; There is no obvious means of access between the two forts [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Caer_Seion]; Around 50 roundhouses stood in the larger fort [SUPPORTED: https://en.wikipedia.org/wiki/Castell_Caer_Seion]"}]'::jsonb),
    ('0e4e4bfd-6702-4adc-b6be-c2e47764cfef'::uuid, 'card_description', 'In Cheddar Gorge, Gough''s Cave held human skulls carefully shaped with stone tools into skull cups, and Cheddar Man, Britain''s oldest complete human skeleton, found here in 1903.', 'In 1903 the remains of a human male, since named Cheddar Man, were found a short distance inside Gough''s Cave.', 'teaser-card-s017-rollback:0e4e4bfd-6702-4adc-b6be-c2e47764cfef:card_description', 'rollback of teaser-card-s017: card_description "In 1903 the remains of a human male, since named Cheddar Man, were found a short distance inside Gough''s Cave." restored on Gough''s Cave', '058571d843410565d86f4de5d2afafdff0de2262eb7c5c8cb186a53f8f4c5f08|d1e499bf1785ff49e2630c11e53905e882444548645c68c2bec9d4448fc4141b|d1e499bf1785ff49e2630c11e53905e882444548645c68c2bec9d4448fc4141b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Cheddar Gorge, Gough''s Cave held human skulls carefully shaped with stone tools into skull cups, and Cheddar Man, Britain''s oldest complete human skeleton, found here in 1903."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Gough''s Cave is in Cheddar Gorge [S1]; the cave held human skulls [S2, S3, S4]; the skulls were carefully shaped with stone tools into skull cups [S4]; Cheddar Man was found in the cave [S5]; Cheddar Man is Britain''s oldest complete human skeleton [S6]; Cheddar Man was found in 1903 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Gough''s Cave is a cave in Cheddar Gorge, Somerset, England [SUPPORTED: https://en.wikipedia.org/wiki/Gough%27s_Cave]; The cave held human skulls (skull remains of several people) [SUPPORTED: https://en.wikipedia.org/wiki/Gough%27s_Cave]; The human skulls were carefully shaped with stone tools [SUPPORTED: https://en.wikipedia.org/wiki/Gough%27s_Cave]; The skulls were made into skull cups [SUPPORTED: https://en.wikipedia.org/wiki/Gough%27s_Cave]; Cheddar Man was found in Gough''s Cave in 1903 [SUPPORTED: https://en.wikipedia.org/wiki/Gough%27s_Cave]; Cheddar Man is Britain''s oldest complete human skeleton [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Gough%27s_Cave]"}]'::jsonb),
    ('0ed79845-f651-4c52-85cd-7f96bab43d4e'::uuid, 'card_description', 'Four tall slabs, 1.8 to 3 meters high, run east and west: Eightercua Stone Row, thought to date from around 1700 BC and by tradition the burial place of Scéine, wife of Amergin mac Míled.', 'A four-stone alignment from 1700 BC stretching east to west. Tradition holds it marks the grave of Scéine, wife of the leader of the Milesian invasion.', 'teaser-card-s017-rollback:0ed79845-f651-4c52-85cd-7f96bab43d4e:card_description', 'rollback of teaser-card-s017: card_description ''A four-stone alignment from 1700 BC stretching east to west. Tradition holds it marks the grave of Scéine, wife of the leader of the Milesian invasion.'' restored on Eightercua Stone Row', 'f65056c94e83fa344ef0cfb1300b6fd99394a89c0bcc2bb5b16fdcf1de6836ad|b3f660787718a00f99a0c2683597fd71b287091eb31c2df4ad3abe08331d0eb4|b3f660787718a00f99a0c2683597fd71b287091eb31c2df4ad3abe08331d0eb4', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Four tall slabs, 1.8 to 3 meters high, run east and west: Eightercua Stone Row, thought to date from around 1700 BC and by tradition the burial place of Scéine, wife of Amergin mac Míled."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site features four tall slabs [S2]; the slabs are 1.8 to 3 meters high [S2]; the slabs run east and west [S2]; the site is thought to date from around 1700 BC [S1]; by tradition it is the burial place of Scéine [S1]; Scéine was the wife of Amergin mac Míled [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Eightercua Stone Row is a stone row (four-stone alignment) in Ireland, in County Kerry near Waterville [SUPPORTED: https://en.wikipedia.org/wiki/Eightercua]; The row has four tall slabs, 1.8 to 3 meters high [SUPPORTED: https://en.wikipedia.org/wiki/Eightercua]; The slabs run east and west [SUPPORTED: https://en.wikipedia.org/wiki/Eightercua]; The row is thought to date from around 1700 BC [SUPPORTED: https://en.wikipedia.org/wiki/Eightercua]; By tradition the row is the burial place of Scéine, wife of Amergin mac Míled [SUPPORTED: https://en.wikipedia.org/wiki/Eightercua]; Scéine was the wife of Amergin, the leader of the Milesians, and tradition says the four stones mark her grave [SUPPORTED, no proving quote: https://monumentalireland.ie/eightercua-stone-row-the-grave-of-sceine/]"}]'::jsonb),
    ('0ed9dd74-23c1-45e4-9d4e-8b80dfe46b0c'::uuid, 'card_description', 'In Lymington, the Iron Age hill fort of Buckland Rings has been excavated only once, in 1935: at its east entrance lay a long passage and the postholes of a pair of stout gateposts.', 'Lymington fort with timber-revetted ramparts of wall-and-fill construction. Excavation in 1935 found upright beams and walls built from cut and laid turves preserved beneath the earthwork.', 'teaser-card-s017-rollback:0ed9dd74-23c1-45e4-9d4e-8b80dfe46b0c:card_description', 'rollback of teaser-card-s017: card_description ''Lymington fort with timber-revetted ramparts of wall-and-fill construction. Excavation in 1935 found upright beams and walls built from cut and laid turves preserved beneath the earthwork.'' restored on Buckland Rings', 'eced854dbcbf77651780fdffa4297178f71cc446926ef57602fe2940b8ff64b2|2bc5f73fe89c2ba6daf06821dce602da45b3a4d314241e9d7770a26f6f8f4f78|2bc5f73fe89c2ba6daf06821dce602da45b3a4d314241e9d7770a26f6f8f4f78', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Lymington, the Iron Age hill fort of Buckland Rings has been excavated only once, in 1935: at its east entrance lay a long passage and the postholes of a pair of stout gateposts."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Buckland Rings is in Lymington [S1]; it is an Iron Age hill fort [S1]; it has been excavated only once [S4]; the excavation was in 1935 [S4]; the entrance lies on the east side [S2]; the entrance had a long passage [S2]; the entrance had the postholes of a pair of stout gateposts [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Buckland Rings is a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Buckland_Rings]; Buckland Rings is in Lymington [SUPPORTED: https://en.wikipedia.org/wiki/Buckland_Rings]; The hill fort is of the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Buckland_Rings]; The hill fort has been excavated only once [SUPPORTED: https://en.wikipedia.org/wiki/Buckland_Rings]; The single excavation took place in 1935 [SUPPORTED: https://en.wikipedia.org/wiki/Buckland_Rings]; The entrance of the fort lies on the east side [SUPPORTED: https://en.wikipedia.org/wiki/Buckland_Rings]; At the east entrance lay a long passage [SUPPORTED: https://en.wikipedia.org/wiki/Buckland_Rings]; At the east entrance were the postholes of a pair of stout gateposts [SUPPORTED: https://en.wikipedia.org/wiki/Buckland_Rings]"}]'::jsonb),
    ('10f42fef-61bd-46a1-b2e7-f35e0c84f9b4'::uuid, 'card_description', 'In the sanctuary of Apollo at Delphi, the Sicyonian Treasury stood on porous stone from Corinthia, and beneath it were buried the pieces of two older buildings, deliberately destroyed.', 'Replacing a tholos and a monopteros at Delphi''s sanctuary of Apollo, this treasury was built by Sicyon after Cleisthenes won the First Sacred War in the early 6th century BC.', 'teaser-card-s017-rollback:10f42fef-61bd-46a1-b2e7-f35e0c84f9b4:card_description', 'rollback of teaser-card-s017: card_description "Replacing a tholos and a monopteros at Delphi''s sanctuary of Apollo, this treasury was built by Sicyon after Cleisthenes won the First Sacred War in the early 6th century BC." restored on Sicyonian Treasury', '73d9fb8d43044faa4b31223095106698743c8a0c17a31a7f6e7e126a030b95ce|e57ecf1aae09ed562fa3b8ebfe1d3abef469d5c099b8699829827a5a27ed2083|e57ecf1aae09ed562fa3b8ebfe1d3abef469d5c099b8699829827a5a27ed2083', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the sanctuary of Apollo at Delphi, the Sicyonian Treasury stood on porous stone from Corinthia, and beneath it were buried the pieces of two older buildings, deliberately destroyed."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Sicyonian Treasury is in the sanctuary of Apollo at Delphi [S1]; it stood on a foundation of porous stone [S5]; the porous stone came from Corinthia [S5]; two older buildings preceded the treasury [S2]; the two older buildings were deliberately destroyed [S7]; the pieces of the two older buildings were buried beneath the treasury''s foundations [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Sicyonian Treasury is a treasury building [SUPPORTED: https://en.wikipedia.org/wiki/Sicyonian_Treasury]; The treasury is at Delphi, in the sanctuary of Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Sicyonian_Treasury]; The treasury stood on a foundation of porous stone [SUPPORTED: https://en.wikipedia.org/wiki/Sicyonian_Treasury]; The porous stone came from Corinthia [SUPPORTED: https://en.wikipedia.org/wiki/Sicyonian_Treasury]; Beneath the treasury were buried the pieces of older buildings [SUPPORTED: https://en.wikipedia.org/wiki/Sicyonian_Treasury]; There were two such older buildings (the tholos and the monopteros) [SUPPORTED: https://en.wikipedia.org/wiki/Sicyonian_Treasury]; The two older buildings were deliberately destroyed [SUPPORTED: https://delphi.culture.gr/treasure-sikionion/]; Architectural members of the two former buildings were embedded in the treasury''s foundations (independent confirmation) [SUPPORTED: https://delphi.culture.gr/treasure-sikionion/]"}]'::jsonb),
    ('111a0de2-2005-43a9-947f-c5d1bddda27d'::uuid, 'card_description', 'From a lignite mine came the Schöningen Spears: ten wooden weapons of spruce and pine, among the oldest hunting weapons yet found, lying among horse bones marked by butchery.', 'The Schöningen spears are a set of ten Palaeolithic wooden weapons that were excavated between 1994 and 1999 from the ''Spear Horizon'' in the open-cast lignite mine in Schöningen, Helmstedt district.', 'teaser-card-s017-rollback:111a0de2-2005-43a9-947f-c5d1bddda27d:card_description', 'rollback of teaser-card-s017: card_description "The Schöningen spears are a set of ten Palaeolithic wooden weapons that were excavated between 1994 and 1999 from the ''Spear Horizon'' in the open-cast lignite mine in Schöningen, Helmstedt district." restored on Schöningen Spears', 'e97c15cb7b25b6d8c99103d5c564709d142ab92e70ff64dd2e69d640608d394c|cfb0c9ecd6d685c0e01d60da15b7eb8dc28fb93c812b30e14f3f9c270fe13f75|cfb0c9ecd6d685c0e01d60da15b7eb8dc28fb93c812b30e14f3f9c270fe13f75', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "From a lignite mine came the Schöningen Spears: ten wooden weapons of spruce and pine, among the oldest hunting weapons yet found, lying among horse bones marked by butchery."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the spears came from a lignite mine [S1]; there are ten wooden weapons [S1]; the spears are of spruce and pine [S5]; they are among the oldest hunting weapons yet found [S2]; they were found among horse bones [S2, S6]; the horse bones are marked by butchery [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Schöningen Spears were excavated from a lignite mine (Schöningen, Germany) [SUPPORTED: https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears]; The Schöningen spears are a set of ten objects [SUPPORTED: https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears]; The objects are wooden weapons [SUPPORTED: https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears]; The weapons are made of spruce [SUPPORTED: https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears]; The weapons are made of pine [SUPPORTED: https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears]; The spears are among the oldest hunting weapons yet found [SUPPORTED: https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears]; The spears lay among horse bones [SUPPORTED: https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears]; The horse bones are marked by butchery [SUPPORTED: https://en.wikipedia.org/wiki/Sch%C3%B6ningen_spears]"}]'::jsonb),
    ('118c6bd0-cfa1-4376-8f42-34e75bec43d3'::uuid, 'card_description', 'On the slopes of Boat How lie the Burnmoor Stone Circles, approximately 4,000 years old. In the largest, Brat''s Hill, around 42 stones ring five funerary cairns and two further stones.', 'Five stone circles about 4,000 years old clustered on a hillside. The largest, Brat''s Hill, has 42 stones forming an irregular ring 30 metres in diameter.', 'teaser-card-s017-rollback:118c6bd0-cfa1-4376-8f42-34e75bec43d3:card_description', 'rollback of teaser-card-s017: card_description "Five stone circles about 4,000 years old clustered on a hillside. The largest, Brat''s Hill, has 42 stones forming an irregular ring 30 metres in diameter." restored on Burnmoor Stone Circles', '95678c86de811b7113f65be301749bb490fe137b5357be2cefb2950eefe8ccce|5f31c7c9151b74a8c8c75c28994ae7e592a53d1339d22ad5f4b85bda3bd6a7e3|5f31c7c9151b74a8c8c75c28994ae7e592a53d1339d22ad5f4b85bda3bd6a7e3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the slopes of Boat How lie the Burnmoor Stone Circles, approximately 4,000 years old. In the largest, Brat''s Hill, around 42 stones ring five funerary cairns and two further stones."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Burnmoor Stone Circles lie on the slopes of Boat How [S2]; the circles are approximately 4,000 years old [S1]; Brat''s Hill is the largest circle [S3, S4]; Brat''s Hill has around 42 stones [S4]; five funerary cairns lie within the circle [S5]; two further stones lie within the circle [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Burnmoor Stone Circles are a group of stone circles in Cumbria, England [SUPPORTED: https://en.wikipedia.org/wiki/Burnmoor_stone_circles]; The circles lie on the slopes of Boat How [SUPPORTED: https://en.wikipedia.org/wiki/Burnmoor_stone_circles]; The circles are approximately 4,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Burnmoor_stone_circles]; Brat''s Hill is the largest circle [SUPPORTED: https://en.wikipedia.org/wiki/Burnmoor_stone_circles]; Brat''s Hill has around 42 stones [SUPPORTED, no proving quote: https://www.megalithic.co.uk/article.php?sid=23]; Within Brat''s Hill are five funerary cairns and two further stones [SUPPORTED: https://en.wikipedia.org/wiki/Burnmoor_stone_circles]"}]'::jsonb),
    ('126756cf-1651-49dd-8075-11e19248b37f'::uuid, 'card_description', 'In the Shilikty Valley of eastern Kazakhstan, Early Saka kurgans held vast quantities of golden jewelry, and in 2003 the remains of a "golden man" were found with 4262 gold finds.', NULL, 'teaser-card-s017-rollback:126756cf-1651-49dd-8075-11e19248b37f:card_description', 'rollback of teaser-card-s017: card_description None restored on Shilikty', '223c167df62128884d6be85f4f518a55f35efd32f4677fc44b23de376381f9ca|de30285e3dedda519c5e975cf727e094d19c3b68e691513b4433f2705d2727e3|de30285e3dedda519c5e975cf727e094d19c3b68e691513b4433f2705d2727e3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Shilikty Valley of eastern Kazakhstan, Early Saka kurgans held vast quantities of golden jewelry, and in 2003 the remains of a \"golden man\" were found with 4262 gold finds."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is in the Shilikty Valley of eastern Kazakhstan [S1]; the kurgans are Early Saka [S2]; the kurgans held vast quantities of golden jewelry [S4]; the remains of a golden man were found in 2003 [S5]; the golden man was found with 4262 gold finds [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Shilikty is an archaeological site of kurgans (burial mounds) - the central claim: the place is a kurgan (tomb mound) site [SUPPORTED: https://en.wikipedia.org/wiki/Shilikty]; The kurgans of Shilikty are burial mounds (a kurgan is a burial mound built over a grave) [SUPPORTED: https://en.wikipedia.org/wiki/Kurgan]; The site lies in the Shilikty Valley [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Shilikty]; The site is in eastern Kazakhstan [SUPPORTED: https://en.wikipedia.org/wiki/Shilikty]; The kurgans are Early Saka kurgans [SUPPORTED: https://en.wikipedia.org/wiki/Shilikty]; The kurgans held vast quantities of golden jewelry [SUPPORTED: https://en.wikipedia.org/wiki/Shilikty]; The remains of a ''golden man'' were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Shilikty]; The golden man remains were found in 2003 [SUPPORTED: https://en.wikipedia.org/wiki/Shilikty]; The golden man was found with 4262 gold finds [SUPPORTED: https://en.wikipedia.org/wiki/Shilikty]"}]'::jsonb),
    ('12e0a51b-54c4-4d30-abcb-7ef995ccd49f'::uuid, 'card_description', 'About 3,600 metres up on the slope of the mountain Tawqaray, above the river Watanay, lie the archaeological remains of Wayna Tawqaray, about 5 km southeast of the center of Cusco.', 'Wayna Tawqaray is situated at a height of about 3,600 metres on the slope of the mountain Tawqaray.', 'teaser-card-s017-rollback:12e0a51b-54c4-4d30-abcb-7ef995ccd49f:card_description', 'rollback of teaser-card-s017: card_description ''Wayna Tawqaray is situated at a height of about 3,600 metres on the slope of the mountain Tawqaray.'' restored on Wayna Tawqaray', 'f92166bd8457f99e84032c0c5db58f81c0e2d14596ded0271fbc23ac02525505|228bb30dc5105ecafaf7d37a17a5b0652b0177965775e33cc3fbaf5a429595f2|228bb30dc5105ecafaf7d37a17a5b0652b0177965775e33cc3fbaf5a429595f2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "About 3,600 metres up on the slope of the mountain Tawqaray, above the river Watanay, lie the archaeological remains of Wayna Tawqaray, about 5 km southeast of the center of Cusco."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is about 3,600 metres up [S3]; it lies on the slope of the mountain Tawqaray [S3]; it lies above the river Watanay [S4]; it is an archaeological site with remains [S1, S4]; it is about 5 km southeast of the center of Cusco [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Wayna Tawqaray is an archaeological site (archaeological remains) in Peru - the central claim [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Tawqaray]; The remains lie about 3,600 metres up [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Tawqaray]; The remains lie on the slope of the mountain Tawqaray [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Tawqaray]; The remains lie above the river Watanay [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Tawqaray]; The site is about 5 km southeast of the center of Cusco [SUPPORTED: https://en.wikipedia.org/wiki/Wayna_Tawqaray]"}]'::jsonb),
    ('13120650-2e61-45af-976c-b2e0665c49af'::uuid, 'card_description', 'At 1,000 m, at the base of Monte Velino, stood Alba Fucens, an Italic town that sided with Marius, was punished by Sulla, and was completely destroyed by the Saracens in the 10th century.', 'An Italic city from 509 BC with streets laid out on a Greek-style grid plan. It served as Rome''s high-security political prison for captured foreign kings.', 'teaser-card-s017-rollback:13120650-2e61-45af-976c-b2e0665c49af:card_description', 'rollback of teaser-card-s017: card_description "An Italic city from 509 BC with streets laid out on a Greek-style grid plan. It served as Rome''s high-security political prison for captured foreign kings." restored on Alba Fucens', '37a694026ec9e50ccf15365f4764cd5bb56e763491667e3f501470448375c7d8|7c3b477e7f8788d8763f758b6edc9262e174c80f7586d03698e802405be7406b|7c3b477e7f8788d8763f758b6edc9262e174c80f7586d03698e802405be7406b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At 1,000 m, at the base of Monte Velino, stood Alba Fucens, an Italic town that sided with Marius, was punished by Sulla, and was completely destroyed by the Saracens in the 10th century."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Alba Fucens stood at 1,000 m [S1]; it stood at the base of Monte Velino [S1]; it was an Italic town [S1]; it sided with Marius [S2]; it was punished by Sulla [S2]; it was completely destroyed by the Saracens [S3]; the destruction was in the 10th century [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Alba Fucens was an ancient town (the central claim: a town, now in ruins) [SUPPORTED: https://en.wikipedia.org/wiki/Alba_Fucens]; Alba Fucens was an Italic town (Italic, not Roman or Greek) [SUPPORTED: https://en.wikipedia.org/wiki/Alba_Fucens]; Alba Fucens lay at 1,000 m elevation [SUPPORTED: https://en.wikipedia.org/wiki/Alba_Fucens]; Alba Fucens lay at the base of Monte Velino [SUPPORTED: https://en.wikipedia.org/wiki/Alba_Fucens]; In the struggle between Sulla and Marius, Alba Fucens sided with Marius [SUPPORTED: https://en.wikipedia.org/wiki/Alba_Fucens]; Sulla punished Alba Fucens (took part of its territory and gave it to veterans of Metellus Pius) [SUPPORTED: https://en.wikipedia.org/wiki/Alba_Fucens]; Alba Fucens was destroyed by the Saracens [SUPPORTED: https://en.wikipedia.org/wiki/Alba_Fucens]; The destruction by the Saracens was complete [SUPPORTED: https://en.wikipedia.org/wiki/Alba_Fucens]; The destruction by the Saracens happened in the 10th century [SUPPORTED: https://en.wikipedia.org/wiki/Alba_Fucens]"}]'::jsonb),
    ('1328e959-ddab-4dd5-bc24-071540a6ce0d'::uuid, 'card_description', 'Cropmarks gave away the Wicklewood Roman Temple in 1959: the walls of its inner chamber were painted in yellow and black on a red ground, and ornate brooches nearby suggest votive offerings.', 'A Romano-Celtic temple discovered from cropmarks in 1959. Its rectangular plan with an inner cella follows the standard design of temples across Roman Britain.', 'teaser-card-s017-rollback:1328e959-ddab-4dd5-bc24-071540a6ce0d:card_description', 'rollback of teaser-card-s017: card_description ''A Romano-Celtic temple discovered from cropmarks in 1959. Its rectangular plan with an inner cella follows the standard design of temples across Roman Britain.'' restored on Wicklewood Roman Temple', '7c49d044d6c863f008b1b69cb4cd9e99042dde7d95c5508a3008c06d6b633a00|18d47fbfdd08c41048e62b2448afd728153cbd968ac4dc1291ec08f4506d6d05|18d47fbfdd08c41048e62b2448afd728153cbd968ac4dc1291ec08f4506d6d05', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cropmarks gave away the Wicklewood Roman Temple in 1959: the walls of its inner chamber were painted in yellow and black on a red ground, and ornate brooches nearby suggest votive offerings."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site was discovered from cropmarks [S2]; the discovery was in 1959 [S2]; the walls of the inner chamber (cella) were painted [S5]; the painting was in yellow and black on a red ground [S5]; ornate brooches were found near the temple [S6, S7]; the ornate brooches suggest votive offerings [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Wicklewood Roman Temple is the site of a Roman (Romano-Celtic) temple at Wicklewood - the central claim: a temple [SUPPORTED: https://en.wikipedia.org/wiki/Wicklewood_Roman_Temple]; The site is in England (Norfolk) [SUPPORTED: https://en.wikipedia.org/wiki/Wicklewood_Roman_Temple]; Cropmarks gave the temple away (it was discovered from cropmarks) [SUPPORTED: https://en.wikipedia.org/wiki/Wicklewood_Roman_Temple]; The temple was discovered in 1959 (partial excavation on a cropmark in 1959) [SUPPORTED: https://www.heritage.norfolk.gov.uk/record?tnf467]; The temple had an inner chamber (cella) whose walls were painted [SUPPORTED: https://en.wikipedia.org/wiki/Wicklewood_Roman_Temple]; The walls of the inner chamber were painted in yellow and black on a red ground [SUPPORTED: https://en.wikipedia.org/wiki/Wicklewood_Roman_Temple]; Ornate brooches were found near the temple [SUPPORTED: https://en.wikipedia.org/wiki/Wicklewood_Roman_Temple]; The ornate brooches suggest votive offerings [SUPPORTED: https://en.wikipedia.org/wiki/Wicklewood_Roman_Temple]"}]'::jsonb),
    ('139ade22-bf52-47ca-8f98-632fa877adc3'::uuid, 'card_description', 'Near Sidon, a podium 22 metres high once bore the marble Temple of Eshmun, Phoenician god of healing. Canals fed its ritual basins from river and sacred spring, for healing and purification.', 'A sanctuary to Eshmun, the Phoenician healing god, expanded from the 7th century BC to the 8th century AD. Each era—Phoenician, Persian, Hellenistic—added a new layer.', 'teaser-card-s017-rollback:139ade22-bf52-47ca-8f98-632fa877adc3:card_description', 'rollback of teaser-card-s017: card_description ''A sanctuary to Eshmun, the Phoenician healing god, expanded from the 7th century BC to the 8th century AD. Each era—Phoenician, Persian, Hellenistic—added a new layer.'' restored on Temple of Eshmun', '42ed72e705078e6bd37a3cdaa19dba11e8348fe94752e0aa4a94c673d1b5ee50|18c6a1b6e1d449c5b3dac0f22472fa7c5d21b8626fa25f2bf697657532e1b705|18c6a1b6e1d449c5b3dac0f22472fa7c5d21b8626fa25f2bf697657532e1b705', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Sidon, a podium 22 metres high once bore the marble Temple of Eshmun, Phoenician god of healing. Canals fed its ritual basins from river and sacred spring, for healing and purification."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is near Sidon [S2]; a podium 22 metres high [S7]; the podium once bore a marble temple [S4]; the temple was of Eshmun [S1, S4]; Eshmun is the Phoenician god of healing [S1]; canals fed the ritual basins from a river and a sacred spring [S5]; the installations served healing and purification [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Temple of Eshmun is an ancient place of worship (a temple) dedicated to Eshmun, the Phoenician god of healing - the central claim [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; Eshmun is a Phoenician god of healing [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; The temple is near Sidon [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; The temple is in Lebanon [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; A podium 22 metres high is part of the site [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; The podium once bore a marble temple of Eshmun [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; The marble temple no longer stands (it once bore the temple) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; Canals fed the ritual basins from the river [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; Canals fed the ritual basins from a sacred spring [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; The basins and water installations served healing and purification [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]; The temple was associated with purification and healing [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Eshmun]"}]'::jsonb),
    ('13c39c81-106b-4f1d-9975-b729226ab99d'::uuid, 'card_description', 'Among the Dead Cities of northwestern Syria, Baqirha keeps a Roman temple of 161 AD to Zeus Bomos, and an Eastern Church whose west gable, completely preserved, is recognised from afar.', 'An ancient settlement with a Roman temple dedicated to Zeus Bomos, a local name for the god Baal. Two early Christian churches were later built among the ruins.', 'teaser-card-s017-rollback:13c39c81-106b-4f1d-9975-b729226ab99d:card_description', 'rollback of teaser-card-s017: card_description ''An ancient settlement with a Roman temple dedicated to Zeus Bomos, a local name for the god Baal. Two early Christian churches were later built among the ruins.'' restored on Baqirha', 'fec32add13edff07624953d8e634486246d144d3f6b88fe53ed0d868b5ee1b81|2d452feb5cbd3f0074970e85394e2e45fa443400b58d823a3c0a44841caa63a4|2d452feb5cbd3f0074970e85394e2e45fa443400b58d823a3c0a44841caa63a4', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Among the Dead Cities of northwestern Syria, Baqirha keeps a Roman temple of 161 AD to Zeus Bomos, and an Eastern Church whose west gable, completely preserved, is recognised from afar."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Baqirha lies among the Dead Cities of northwestern Syria [S1]; Baqirha preserves a temple from the Roman period [S2]; the temple dates from 161 AD [S4]; the temple was dedicated to Zeus Bomos [S4]; Baqirha has an Eastern Church [S6]; the Eastern Church''s west gable is completely preserved [S6]; the Eastern Church is recognised from afar by that gable [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Baqirha is an ancient settlement among the Dead Cities of northwestern Syria (the central claim: a settlement, with its place) [SUPPORTED: https://en.wikipedia.org/wiki/Baqirha]; Baqirha lies in Syria (Idlib Governorate), in the area of the Dead Cities [SUPPORTED: https://en.wikipedia.org/wiki/Baqirha]; Baqirha keeps a Roman temple [SUPPORTED: https://en.wikipedia.org/wiki/Baqirha]; The Roman temple dates to 161 AD [SUPPORTED: https://en.wikipedia.org/wiki/Baqirha]; The temple of 161 AD was dedicated to Zeus Bomos [SUPPORTED: https://en.wikipedia.org/wiki/Baqirha]; Baqirha has an Eastern Church [SUPPORTED: https://en.wikipedia.org/wiki/Baqirha]; The Eastern Church''s west gable is completely preserved [SUPPORTED: https://en.wikipedia.org/wiki/Baqirha]; The Eastern Church (its west gable) is recognised from afar [SUPPORTED: https://en.wikipedia.org/wiki/Baqirha]"}]'::jsonb),
    ('14c0c237-0ece-4124-ada8-8ec56b431b08'::uuid, 'card_description', 'Near Luxor stands the Karnak Temple Complex, main place of worship of the Theban Triad headed by Amun. In its Great Hypostyle Hall, 134 massive columns rise in 16 rows.', 'A vast temple complex built over 2,000 years, from 1971 BC to the Ptolemaic era. Its Hypostyle Hall has 134 columns across 5,000 square metres.', 'teaser-card-s017-rollback:14c0c237-0ece-4124-ada8-8ec56b431b08:card_description', 'rollback of teaser-card-s017: card_description ''A vast temple complex built over 2,000 years, from 1971 BC to the Ptolemaic era. Its Hypostyle Hall has 134 columns across 5,000 square metres.'' restored on Karnak Temple Complex', '8632238729248b33bd6c12c11b155d73e531f9be01ecd8e61d3f1b87572561b9|eae493d517977525f42bb0327fb0168cbc0ffefb2b0142b7c0c0d41ea799c927|eae493d517977525f42bb0327fb0168cbc0ffefb2b0142b7c0c0d41ea799c927', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Luxor stands the Karnak Temple Complex, main place of worship of the Theban Triad headed by Amun. In its Great Hypostyle Hall, 134 massive columns rise in 16 rows."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Karnak Temple Complex is near Luxor [S1]; Karnak was the main place of worship of the Theban Triad [S3]; the Theban Triad was headed by the god Amun [S3]; the complex has a Great Hypostyle Hall [S5]; the Great Hypostyle Hall has 134 massive columns [S5]; the columns are arranged in 16 rows [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Karnak Temple Complex is a complex of temples (the central claim: a temple complex) [SUPPORTED: https://en.wikipedia.org/wiki/Karnak]; The Karnak Temple Complex is near Luxor [SUPPORTED: https://en.wikipedia.org/wiki/Karnak]; Karnak is the main place of worship of the Theban Triad [SUPPORTED: https://en.wikipedia.org/wiki/Karnak]; The Theban Triad is headed by Amun [SUPPORTED: https://en.wikipedia.org/wiki/Karnak]; Karnak has a Great Hypostyle Hall [SUPPORTED: https://en.wikipedia.org/wiki/Karnak]; The Great Hypostyle Hall has 134 massive columns [SUPPORTED: https://en.wikipedia.org/wiki/Karnak]; The 134 columns of the Great Hypostyle Hall are arranged in 16 rows [SUPPORTED: https://en.wikipedia.org/wiki/Karnak]"}]'::jsonb),
    ('14fab6bd-8c5b-4233-816b-a90169bcefea'::uuid, 'card_description', 'In southern Saqqara, a covered causeway ran through the desert from the Nile to the Pyramid of Pepi II, tomb of King Pepi II and the final full pyramid complex built in Ancient Egypt.', 'Built for Pharaoh Pepi II in the 23rd century BC — 78.75 m base, 52.5 m tall. Last full pyramid complex in Egypt; its 400 m causeway and three queen''s pyramids still stand at South Saqqara.', 'teaser-card-s017-rollback:14fab6bd-8c5b-4233-816b-a90169bcefea:card_description', 'rollback of teaser-card-s017: card_description "Built for Pharaoh Pepi II in the 23rd century BC — 78.75 m base, 52.5 m tall. Last full pyramid complex in Egypt; its 400 m causeway and three queen''s pyramids still stand at South Saqqara." restored on Pyramid of Pepi II', 'fb3200308e15f94791d2d43de0b3bf7982cf454c96bb41fe8ca64984ab736766|86d3353f30dcb32fd738d66ee5a0b6c8a6b790593de1c463c89c2a8e5028d0fd|86d3353f30dcb32fd738d66ee5a0b6c8a6b790593de1c463c89c2a8e5028d0fd', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In southern Saqqara, a covered causeway ran through the desert from the Nile to the Pyramid of Pepi II, tomb of King Pepi II and the final full pyramid complex built in Ancient Egypt."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Pyramid of Pepi II is in southern Saqqara [S1]; a covered causeway ran to the pyramid [S5]; the causeway ran through the desert from the Nile [S5]; the pyramid was the tomb of King Pepi II [S1]; it was the final full pyramid complex built in Ancient Egypt [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Pyramid of Pepi II was the tomb of King Pepi II (the central claim: a pyramid tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Pepi_II]; The pyramid is in southern Saqqara [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Pepi_II]; It was the final full pyramid complex built in Ancient Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Pepi_II]; The pyramid complex had a covered causeway [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Pepi_II]; The causeway ran through the desert [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Pepi_II]; The causeway ran from the Nile to the pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Pepi_II]"}]'::jsonb),
    ('152323b2-51d4-4c65-b66c-8d9bd34e5ba8'::uuid, 'card_description', 'On a ridge ringed by deep ravines, Mixco Viejo spreads in fortified groups: over 120 major structures, temples, palaces and ballgame courts of a Postclassic Maya city, a Chajoma capital.', 'The ruins consist of 15 groups containing the remains of over 120 major structures, including temples, palaces, and courts for playing the Mesoamerican ballgame.', 'teaser-card-s017-rollback:152323b2-51d4-4c65-b66c-8d9bd34e5ba8:card_description', 'rollback of teaser-card-s017: card_description ''The ruins consist of 15 groups containing the remains of over 120 major structures, including temples, palaces, and courts for playing the Mesoamerican ballgame.'' restored on Mixco Viejo', '115db9fdae105728e157dd94c4bff7df6fd412fa6324bb5bdc178686e3c152bd|b021693fcd438a2a027185ae360ec254aecd1ccfbaf06f596cb306e1f76204ce|b021693fcd438a2a027185ae360ec254aecd1ccfbaf06f596cb306e1f76204ce', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a ridge ringed by deep ravines, Mixco Viejo spreads in fortified groups: over 120 major structures, temples, palaces and ballgame courts of a Postclassic Maya city, a Chajoma capital."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies on a ridge surrounded by deep ravines [S5]; its architecture is spread in fortified groups [S5]; the ruins hold over 120 major structures [S6]; the structures include temples, palaces and ballgame courts [S6]; it is a city of the Postclassic Maya civilization [S2]; it was the capital of the Chajoma kingdom [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Mixco Viejo is a ruined city of the Postclassic Maya civilization in Guatemala (the central claim: a Maya city, with its place) [SUPPORTED: https://en.wikipedia.org/wiki/Mixco_Viejo]; Mixco Viejo is in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Mixco_Viejo]; Mixco Viejo is the capital of the Chajoma [SUPPORTED: https://en.wikipedia.org/wiki/Mixco_Viejo]; The city''s architecture spreads in fortified groups along a ridge surrounded by deep ravines [SUPPORTED: https://en.wikipedia.org/wiki/Mixco_Viejo]; The site has over 120 major structures [SUPPORTED: https://en.wikipedia.org/wiki/Mixco_Viejo]; The structures include temples, palaces and ballgame courts [SUPPORTED: https://en.wikipedia.org/wiki/Mixco_Viejo]"}]'::jsonb),
    ('15cf53da-ecf4-4681-a2a7-63984886562f'::uuid, 'card_description', 'Near Sintra, the Roman Bridge of Catribana crosses the Bolelas stream in a single arch of local limestone. Close by lie traces of a Roman-era cemetery and a Neolithic settlement.', 'A 1st-century AD Roman bridge on the road from Lisbon to Mérida. It wasn''t identified as Roman until the 1980s despite being there for 2,000 years.', 'teaser-card-s017-rollback:15cf53da-ecf4-4681-a2a7-63984886562f:card_description', 'rollback of teaser-card-s017: card_description "A 1st-century AD Roman bridge on the road from Lisbon to Mérida. It wasn''t identified as Roman until the 1980s despite being there for 2,000 years." restored on Roman Bridge of Catribana', 'fe50e47cd731f6c75440157d08ae4c7b12b8440b17233843c6938445bd39d0da|78d0824315612aa400865f77e59b4ae4d159e793d23ef2db4534e616cf4147ee|78d0824315612aa400865f77e59b4ae4d159e793d23ef2db4534e616cf4147ee', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Sintra, the Roman Bridge of Catribana crosses the Bolelas stream in a single arch of local limestone. Close by lie traces of a Roman-era cemetery and a Neolithic settlement."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the bridge is near Sintra (in the municipality of Sintra) [S1]; the bridge crosses the Bolelas stream [S2]; it is made of local limestone [S2]; it has a single arch [S4]; close by are traces of a Roman-era cemetery [S6]; close by are traces of a Neolithic settlement [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Roman Bridge of Catribana is a Roman bridge near the village of Catribana in the municipality of Sintra, Portugal (the central claim: a bridge, with its place) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Catribana]; The bridge is a Roman bridge near the village of Catribana [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Catribana]; The bridge crosses the Bolelas stream [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Catribana]; The bridge is built of local limestone [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Catribana]; The bridge has a single arch [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Catribana]; Close to the bridge lie traces of a Roman-era cemetery [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Catribana]; Close to the bridge lie remains of a Neolithic settlement [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Bridge_of_Catribana]"}]'::jsonb),
    ('15d92d09-d2ec-415d-87ea-88535744e27f'::uuid, 'card_description', 'Oral tradition says the Wotanstein was dug up in the Seven Years'' War for rumoured treasure, but human bones were found instead. In 1407 documents called it the long stone at Madin.', 'A menhir from the 3rd century BC standing at a crossroads. Its earlier name, "Malstein," and its association with Wotan hint at pre-Christian ritual use.', 'teaser-card-s017-rollback:15d92d09-d2ec-415d-87ea-88535744e27f:card_description', 'rollback of teaser-card-s017: card_description ''A menhir from the 3rd century BC standing at a crossroads. Its earlier name, "Malstein," and its association with Wotan hint at pre-Christian ritual use.'' restored on Wotanstein, Hesse', 'd92984672f3bbae4212648793fb29a08766a54697d41b7cad4c3b135a4b5d616|365c68d1e140b712c0b7a23cd73e13f7161b990ab03cf3ca0d77f296a3e21e64|365c68d1e140b712c0b7a23cd73e13f7161b990ab03cf3ca0d77f296a3e21e64', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Oral tradition says the Wotanstein was dug up in the Seven Years'' War for rumoured treasure, but human bones were found instead. In 1407 documents called it the long stone at Madin."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "according to oral tradition the Wotanstein was dug up during the Seven Years'' War [S7]; it was dug up because treasure was rumoured to be buried under it [S7]; human bones were found instead (as oral tradition has it) [S7]; in 1407 documents mentioned the stone as the long stone at Madin [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Wotanstein is a megalith (menhir, standing stone) near the village of Maden in Hesse, Germany [SUPPORTED: https://en.wikipedia.org/wiki/Wotanstein_(Hesse)]; Oral tradition says the Wotanstein was dug up (excavated) during the Seven Years'' War [SUPPORTED: https://en.wikipedia.org/wiki/Wotanstein_(Hesse)]; It was dug up because of a rumour that treasure lay buried under it [SUPPORTED: https://en.wikipedia.org/wiki/Wotanstein_(Hesse)]; Human bones were found instead of treasure [SUPPORTED: https://en.wikipedia.org/wiki/Wotanstein_(Hesse)]; In 1407 documents called it the long stone at Madin [SUPPORTED: https://en.wikipedia.org/wiki/Wotanstein_(Hesse)]"}]'::jsonb),
    ('16d71206-b1bd-4575-85b9-14567a8c1c4e'::uuid, 'card_description', 'Early Iron Age, Scythian times: in the village of Khotiv, the Khotiv Hillfort had buildings only near the inner side of its rampart. An archaeological monument since 1965.', 'A Scythian-era hillfort from the 6th century BC covering 31 hectares. Rampart, scarp, berm, and moat ringed the entire plateau in formidable layers of defense.', 'teaser-card-s017-rollback:16d71206-b1bd-4575-85b9-14567a8c1c4e:card_description', 'rollback of teaser-card-s017: card_description ''A Scythian-era hillfort from the 6th century BC covering 31 hectares. Rampart, scarp, berm, and moat ringed the entire plateau in formidable layers of defense.'' restored on Khotiv Hillfort', 'df9e15172b7b0e6fa3de803057e3a666589d3c84e5b584edff1e81ba9f1e24d2|5c7fdbb2dcc728560d1ac773ecfeddccc14895dd7334e145151b8d08cdb8d243|5c7fdbb2dcc728560d1ac773ecfeddccc14895dd7334e145151b8d08cdb8d243', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Early Iron Age, Scythian times: in the village of Khotiv, the Khotiv Hillfort had buildings only near the inner side of its rampart. An archaeological monument since 1965."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the hillfort dates to the early Iron Age [S1]; it belongs to Scythian times [S1]; it lies in the village of Khotiv [S1]; it had buildings only near the inner side of its rampart [S3]; it has been an archaeological monument since 1965 [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Khotiv Hillfort is a hillfort (fortified settlement with a rampart) [SUPPORTED: https://en.wikipedia.org/wiki/Khotiv_hillfort]; It lies in the village of Khotiv, Ukraine [SUPPORTED: https://en.wikipedia.org/wiki/Khotiv_hillfort]; It dates to the Early Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Khotiv_hillfort]; It dates to Scythian times [SUPPORTED: https://en.wikipedia.org/wiki/Khotiv_hillfort]; The hillfort had buildings only near the inner side of its rampart [SUPPORTED: https://en.wikipedia.org/wiki/Khotiv_hillfort]; It has been an archaeological monument since 1965 [SUPPORTED: https://en.wikipedia.org/wiki/Khotiv_hillfort]"}]'::jsonb),
    ('17191c2e-9ebc-41e5-865f-1bb6be790eb5'::uuid, 'card_description', 'Above Eynhallow Sound, the Broch of Gurness gathers an Iron Age village around a stone tower that probably once reached around 10 metres, stone-floored galleries between its walls.', 'At the centre of the settlement is a stone tower or broch, which once probably reached a height of around 10 metres.', 'teaser-card-s017-rollback:17191c2e-9ebc-41e5-865f-1bb6be790eb5:card_description', 'rollback of teaser-card-s017: card_description ''At the centre of the settlement is a stone tower or broch, which once probably reached a height of around 10 metres.'' restored on Broch of Gurness', '4afacccef2a06b7e6e7a9f080076d9ff6654e0eb241bbd5f5302a752e0d18b90|f3762f4398cf62367ff1ac8e2ee47b60e7c155ded8a6573bd2cce759b6f33c3b|f3762f4398cf62367ff1ac8e2ee47b60e7c155ded8a6573bd2cce759b6f33c3b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Above Eynhallow Sound, the Broch of Gurness gathers an Iron Age village around a stone tower that probably once reached around 10 metres, stone-floored galleries between its walls."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Broch of Gurness overlooks Eynhallow Sound [S1]; it is an Iron Age village [S1]; the village is gathered around a stone tower (the broch) [S5]; the tower probably once reached around 10 metres [S5]; the tower has stone-floored galleries between its walls [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Broch of Gurness is an Iron Age broch village (a settlement of stone dwellings around a broch tower) [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Gurness]; It lies on the coast of Mainland Orkney, Scotland, overlooking Eynhallow Sound [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Gurness]; The village is gathered around a central stone tower (the broch) [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Gurness]; The tower probably once reached a height of around 10 metres [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Gurness]; The tower''s walls are double-skinned with galleries between them [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Gurness]; The galleries between the walls have stone floors [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Gurness]"}]'::jsonb),
    ('17c20887-877e-4427-8728-4c856cc8c0c3'::uuid, 'card_description', 'In Kvemo Kartli lies Sakdrisi, a prehistoric gold mine dated to the early 3rd millennium BC or the second half of the 4th millennium: it might be one of the world''s oldest known gold mines.', 'A prehistoric gold mine active from the 4th–3rd millennium BC — among the oldest known gold mines in the world. The tunnels still survive.', 'teaser-card-s017-rollback:17c20887-877e-4427-8728-4c856cc8c0c3:card_description', 'rollback of teaser-card-s017: card_description ''A prehistoric gold mine active from the 4th–3rd millennium BC — among the oldest known gold mines in the world. The tunnels still survive.'' restored on Sakdrisi', '2721b0156bccb5fe9908f3a8162f549eeb9e0e37d74226a53cdc0c97f693c2d2|bb88950c5e75abebde760dfc280ee2365b22bce6c1645021b8db126219694f8f|bb88950c5e75abebde760dfc280ee2365b22bce6c1645021b8db126219694f8f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Kvemo Kartli lies Sakdrisi, a prehistoric gold mine dated to the early 3rd millennium BC or the second half of the 4th millennium: it might be one of the world''s oldest known gold mines."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Sakdrisi lies in Kvemo Kartli [S1]; it is a prehistoric gold mine [S1]; it is dated to the early 3rd millennium BC or the second half of the 4th millennium [S2]; it might be one of the world''s oldest known gold mines [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Sakdrisi is a prehistoric gold mine (a gold mine and archaeological site containing a prehistoric mine) in Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Sakdrisi]; Sakdrisi lies in the Kvemo Kartli region [SUPPORTED: https://en.wikipedia.org/wiki/Sakdrisi]; The site is dated to the early 3rd millennium BC or the second half of the 4th millennium [SUPPORTED: https://en.wikipedia.org/wiki/Sakdrisi]; Sakdrisi might be one of the world''s oldest known gold mines [SUPPORTED: https://en.wikipedia.org/wiki/Sakdrisi]"}]'::jsonb),
    ('18462ce6-cfb7-43ba-83cd-d44c26395227'::uuid, 'card_description', 'On a moor in Cornwall, Zennor Quoit is a ruined dolmen whose chamber of seven upright stones was once covered by a cairn. Digs found flint, Neolithic style pottery and cremated bones.', 'A ruined megalithic burial chamber dating to 2500-1500 BC, with a 12.5-tonne roof that collapsed sometime between 1770 and 1865. Bodies were cremated and replaced over time.', 'teaser-card-s017-rollback:18462ce6-cfb7-43ba-83cd-d44c26395227:card_description', 'rollback of teaser-card-s017: card_description ''A ruined megalithic burial chamber dating to 2500-1500 BC, with a 12.5-tonne roof that collapsed sometime between 1770 and 1865. Bodies were cremated and replaced over time.'' restored on Zennor Quoit', 'ba957db69ee0abdaafed9afc8f9580efcb52f94094425e7de5a2af032b583564|221d5af52142d2ae86b07abda8bb44c6d44b856609cc617b77d6a8891073eeae|221d5af52142d2ae86b07abda8bb44c6d44b856609cc617b77d6a8891073eeae', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a moor in Cornwall, Zennor Quoit is a ruined dolmen whose chamber of seven upright stones was once covered by a cairn. Digs found flint, Neolithic style pottery and cremated bones."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Zennor Quoit is on a moor [S1]; it is in Cornwall [S1]; it is a ruined dolmen [S1]; the chamber consists of seven upright stones [S4]; the chamber was originally covered by a cairn [S4]; excavations found flint [S7]; excavations found Neolithic style pottery [S7]; excavations found cremated bones [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Zennor Quoit is a ruined monument [SUPPORTED: https://en.wikipedia.org/wiki/Zennor_Quoit]; Zennor Quoit is a dolmen (megalithic burial chamber) [SUPPORTED: https://en.wikipedia.org/wiki/Zennor_Quoit]; It stands on a moor [SUPPORTED: https://en.wikipedia.org/wiki/Zennor_Quoit]; It is in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Zennor_Quoit]; Its chamber consists of seven upright stones [SUPPORTED: https://en.wikipedia.org/wiki/Zennor_Quoit]; The chamber was once covered by a cairn [SUPPORTED: https://en.wikipedia.org/wiki/Zennor_Quoit]; Excavations found flint [SUPPORTED: https://en.wikipedia.org/wiki/Zennor_Quoit]; Excavations found Neolithic style pottery [SUPPORTED: https://en.wikipedia.org/wiki/Zennor_Quoit]; Excavations found cremated bones [SUPPORTED: https://en.wikipedia.org/wiki/Zennor_Quoit]"}]'::jsonb),
    ('19ec6c34-0d5d-4a55-9c8d-d0cdda84b9ad'::uuid, 'card_description', 'In the Conwy valley, Pen y Gaer, a Bronze Age and Iron Age hillfort, still shows the remains of its stone walls and a chevaux-de-frise, defences amended over a long history of occupation.', 'A hillfort with defenses spanning the Bronze and Iron Ages, including two cairns and extensive prehistoric field systems nearby. The visible remains are mostly Iron Age.', 'teaser-card-s017-rollback:19ec6c34-0d5d-4a55-9c8d-d0cdda84b9ad:card_description', 'rollback of teaser-card-s017: card_description ''A hillfort with defenses spanning the Bronze and Iron Ages, including two cairns and extensive prehistoric field systems nearby. The visible remains are mostly Iron Age.'' restored on Pen y Gaer', '4c1a12dda6609b08bd9868f82061c767bae79b628543acf3f83cc0a8a0c30f30|ccbef6d72e7c1516cbc27ca2b7832dd58b14b0f231e8d92f28521d2f56a538f4|ccbef6d72e7c1516cbc27ca2b7832dd58b14b0f231e8d92f28521d2f56a538f4', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Conwy valley, Pen y Gaer, a Bronze Age and Iron Age hillfort, still shows the remains of its stone walls and a chevaux-de-frise, defences amended over a long history of occupation."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pen y Gaer is in the Conwy valley [S1]; it is a Bronze Age and Iron Age hillfort [S1]; remains of its stone walls can still be seen [S5]; remains of a chevaux-de-frise can still be seen [S5]; its defences were amended over time [S2]; the site has a long history of occupation [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pen y Gaer is a hillfort (central claim: what kind of place it is) [SUPPORTED: https://en.wikipedia.org/wiki/Pen_y_Gaer]; Pen y Gaer lies in the Conwy valley, Wales [SUPPORTED: https://en.wikipedia.org/wiki/Pen_y_Gaer]; The hillfort is Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Pen_y_Gaer]; The hillfort is Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Pen_y_Gaer]; The remains of its stone walls can still be seen [SUPPORTED: https://en.wikipedia.org/wiki/Pen_y_Gaer]; A chevaux-de-frise can still be seen at the site [SUPPORTED: https://en.wikipedia.org/wiki/Pen_y_Gaer]; The site had a long history of occupation [SUPPORTED: https://en.wikipedia.org/wiki/Pen_y_Gaer]; The defences were amended over time [SUPPORTED: https://en.wikipedia.org/wiki/Pen_y_Gaer]"}]'::jsonb),
    ('19ed3a0f-09e5-4844-ae5d-9d50bea1371b'::uuid, 'card_description', 'In the Grottos of Juxtlahuaca, painted walls show a large bearded man in a black cloak and a red Feathered Serpent with green plumes. A dozen skeletons were found in the Hall of the Dead.', 'Cave murals from 1200–900 BC deep underground — the earliest sophisticated painted art in Mesoamerica. The only known example of non-Maya deep cave art on the continent.', 'teaser-card-s017-rollback:19ed3a0f-09e5-4844-ae5d-9d50bea1371b:card_description', 'rollback of teaser-card-s017: card_description ''Cave murals from 1200–900 BC deep underground — the earliest sophisticated painted art in Mesoamerica. The only known example of non-Maya deep cave art on the continent.'' restored on Grottos of Juxtlahuaca', 'e56a12403cbcaf4d2c3407332b55db305fd2adb8b6ee0ecfc5973131786e02e6|11c3c8091b1d53118a10fbc2245671fe45d4a91544111dd183cfe7ab091b277b|11c3c8091b1d53118a10fbc2245671fe45d4a91544111dd183cfe7ab091b277b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Grottos of Juxtlahuaca, painted walls show a large bearded man in a black cloak and a red Feathered Serpent with green plumes. A dozen skeletons were found in the Hall of the Dead."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the cave has painted walls [S1, S2]; the paintings show a large bearded man in a black cloak [S5]; the paintings show a red Feathered Serpent with green plumes [S6]; a dozen skeletons have been found [S7]; they were found in the Hall of the Dead [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Juxtlahuaca (the Grottos of Juxtlahuaca) is a cave system with painted walls in Guerrero, Mexico (central claim: a painted cave) [SUPPORTED: https://en.wikipedia.org/wiki/Juxtlahuaca]; The painted walls show a large man [SUPPORTED: https://en.wikipedia.org/wiki/Juxtlahuaca]; The large man is bearded [SUPPORTED: https://en.wikipedia.org/wiki/Juxtlahuaca]; The man wears a black cloak [SUPPORTED: https://en.wikipedia.org/wiki/Juxtlahuaca]; The painted walls show a red Feathered Serpent [SUPPORTED: https://en.wikipedia.org/wiki/Juxtlahuaca]; The Feathered Serpent has green plumes [SUPPORTED: https://en.wikipedia.org/wiki/Juxtlahuaca]; A dozen skeletons were found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Juxtlahuaca]; The skeletons were found in a place called the Hall of the Dead [SUPPORTED: https://en.wikipedia.org/wiki/Juxtlahuaca]"}]'::jsonb),
    ('1a85971c-56a9-411e-bfa9-eda3004219a5'::uuid, 'card_description', 'In the Nam River valley near Jinju, Daepyeong grew into a large central settlement: 144 pit-houses in Eoeun, 115 in Okbang, and many ditches and ditch-enclosures.', 'Pottery typologies and seriations and a host of AMS radiocarbon dates show that the site had a number of occupations over several millennia from circa 3500 BC - AD 500.', 'teaser-card-s017-rollback:1a85971c-56a9-411e-bfa9-eda3004219a5:card_description', 'rollback of teaser-card-s017: card_description ''Pottery typologies and seriations and a host of AMS radiocarbon dates show that the site had a number of occupations over several millennia from circa 3500 BC - AD 500.'' restored on Daepyeong', 'd5a4120d6d5568682ac74912a74f3bb3380867c7f38b0bcb4d122e4811735fb3|9625dbc01f87cb7376acf7c85e25da09eccfc5d666dc35cffe99416555bf458d|9625dbc01f87cb7376acf7c85e25da09eccfc5d666dc35cffe99416555bf458d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Nam River valley near Jinju, Daepyeong grew into a large central settlement: 144 pit-houses in Eoeun, 115 in Okbang, and many ditches and ditch-enclosures."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Daepyeong lies in the Nam River valley near Jinju [S1]; it grew into a large central settlement [S5]; it had 144 pit-houses in Eoeun [S6]; it had 115 pit-houses in Okbang [S7]; it had many ditches and ditch-enclosures [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Daepyeong is a prehistoric settlement site in the Nam River valley near Jinju, South Korea (central claim: a prehistoric settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Daepyeong]; Daepyeong grew into a large central settlement [SUPPORTED: https://en.wikipedia.org/wiki/Daepyeong]; There were 144 pit-houses in Eoeun [SUPPORTED: https://en.wikipedia.org/wiki/Daepyeong]; There were 115 pit-houses in Okbang [SUPPORTED: https://en.wikipedia.org/wiki/Daepyeong]; There were many ditches and ditch-enclosures [SUPPORTED: https://en.wikipedia.org/wiki/Daepyeong]"}]'::jsonb),
    ('1ab97e76-933a-4dc5-a734-42f53c8c7667'::uuid, 'card_description', 'Fir Clump Stone Circle in Burderop Wood was a double oval ring of sarsen megaliths, levelled around the 1860s. Some rediscovered in 1965 were removed in 1969 during construction of the M4.', 'A double stone circle now completely destroyed. Built between 3300 and 900 BC, it was part of the megalithic tradition that spread across Britain, Ireland, and Brittany.', 'teaser-card-s017-rollback:1ab97e76-933a-4dc5-a734-42f53c8c7667:card_description', 'rollback of teaser-card-s017: card_description ''A double stone circle now completely destroyed. Built between 3300 and 900 BC, it was part of the megalithic tradition that spread across Britain, Ireland, and Brittany.'' restored on Fir Clump Stone Circle', '255fecc1ae88b4510c0b7c218ce56f444481a0181972e2b9ae15d7c122ae4d6f|9caf89ba21e2aed8875568f0b7382f8d32de5548b61de9e348aab9e08cfafd0d|9caf89ba21e2aed8875568f0b7382f8d32de5548b61de9e348aab9e08cfafd0d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Fir Clump Stone Circle in Burderop Wood was a double oval ring of sarsen megaliths, levelled around the 1860s. Some rediscovered in 1965 were removed in 1969 during construction of the M4."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the circle lay in Burderop Wood [S1]; it was a double ring of megaliths [S3]; the ring was oval-shaped [S3]; the megaliths were sarsen [S3]; the megaliths were levelled around the 1860s [S6]; some of the fallen megaliths were rediscovered in 1965 [S7]; those stones were removed in 1969 [S8]; the removal happened during construction of the M4 [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Fir Clump Stone Circle was a stone circle (central claim: a stone circle) [SUPPORTED: https://en.wikipedia.org/wiki/Fir_Clump_Stone_Circle]; It stood in Burderop Wood, Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Fir_Clump_Stone_Circle]; It was a double ring [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Fir_Clump_Stone_Circle]; The double ring was oval [SUPPORTED: https://en.wikipedia.org/wiki/Fir_Clump_Stone_Circle]; It was built of sarsen megaliths [SUPPORTED: https://en.wikipedia.org/wiki/Fir_Clump_Stone_Circle]; The megaliths were levelled around the 1860s [SUPPORTED: https://en.wikipedia.org/wiki/Fir_Clump_Stone_Circle]; Some of the stones were rediscovered in 1965 [SUPPORTED: https://en.wikipedia.org/wiki/Fir_Clump_Stone_Circle]; The rediscovered stones were removed in 1969 [SUPPORTED: https://en.wikipedia.org/wiki/Fir_Clump_Stone_Circle]; The removal happened during construction of the M4 [SUPPORTED: https://en.wikipedia.org/wiki/Fir_Clump_Stone_Circle]"}]'::jsonb),
    ('1bc3b429-ca8e-4bae-93a2-daeefab5e297'::uuid, 'card_description', 'The Roman fort of Aquis Querquennis, built circa 69-79 AD, was flooded by a reservoir in 1949. When its level falls, digs reveal a headquarters, barracks, granaries and a hospital.', 'The fort was rediscovered in the 1920s and some excavations carried out by local archaeologist Florentino López Cuevillas.', 'teaser-card-s017-rollback:1bc3b429-ca8e-4bae-93a2-daeefab5e297:card_description', 'rollback of teaser-card-s017: card_description ''The fort was rediscovered in the 1920s and some excavations carried out by local archaeologist Florentino López Cuevillas.'' restored on Aquis Querquennis', '9eaa8de3f39ed99457a4756720eddccc02058b183febffaec314f85c18d9538a|50da1bea6086855ba6d6ae17c825ecb0c24b6a01e084bfd0c7062e95111dd118|50da1bea6086855ba6d6ae17c825ecb0c24b6a01e084bfd0c7062e95111dd118', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Roman fort of Aquis Querquennis, built circa 69-79 AD, was flooded by a reservoir in 1949. When its level falls, digs reveal a headquarters, barracks, granaries and a hospital."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Aquis Querquennis is a Roman fort [S1]; it was built circa 69-79 AD [S2]; a reservoir flooded it in 1949 [S4]; digs happen when the reservoir level falls [S5]; digs have revealed a headquarters [S6]; digs have revealed barracks [S6]; digs have revealed granaries [S6]; digs have revealed a hospital [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Aquis Querquennis is a Roman fort (central claim: a Roman fort), in Ourense Province, Galicia, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Aquis_Querquennis]; The fort was built circa 69-79 AD [SUPPORTED: https://en.wikipedia.org/wiki/Aquis_Querquennis]; The site was flooded by a reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Aquis_Querquennis]; The flooding happened in 1949 [SUPPORTED: https://en.wikipedia.org/wiki/Aquis_Querquennis]; Digs take place and reveal the site when the reservoir level falls [SUPPORTED: https://en.wikipedia.org/wiki/Aquis_Querquennis]; Excavations revealed a headquarters [SUPPORTED: https://en.wikipedia.org/wiki/Aquis_Querquennis]; Excavations revealed barracks [SUPPORTED: https://en.wikipedia.org/wiki/Aquis_Querquennis]; Excavations revealed granaries [SUPPORTED: https://en.wikipedia.org/wiki/Aquis_Querquennis]; Excavations revealed a hospital [SUPPORTED: https://en.wikipedia.org/wiki/Aquis_Querquennis]"}]'::jsonb),
    ('1bda8d7d-01e8-4063-b1c1-c2f46c6b9a64'::uuid, 'card_description', 'Once the largest Roman theatre north of the Alps, 116 metres across, the Roman Theatre in Mainz lost its stage foundations in 1884: found, recorded, then demolished for railway tracks.', 'The Roman Theatre in Mainz, Rhineland Palatinate was excavated in the late 1990s.', 'teaser-card-s017-rollback:1bda8d7d-01e8-4063-b1c1-c2f46c6b9a64:card_description', 'rollback of teaser-card-s017: card_description ''The Roman Theatre in Mainz, Rhineland Palatinate was excavated in the late 1990s.'' restored on Roman Theatre, Mainz', 'faaf207c8a5eddc03175337b695d3c06449ebd6075f64d645b9d5114144ad81d|124f0b217a3febf9797fe5217e2c277a8099a5799673627200c31733a211a3d9|124f0b217a3febf9797fe5217e2c277a8099a5799673627200c31733a211a3d9', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Once the largest Roman theatre north of the Alps, 116 metres across, the Roman Theatre in Mainz lost its stage foundations in 1884: found, recorded, then demolished for railway tracks."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Roman Theatre in Mainz was once the largest Roman theatre north of the Alps [S2]; the theatre had a diameter of 116 metres [S2]; foundations of the theatre''s stage building were found in 1884 during the construction of the railway [S4]; the stage foundations were recorded and then demolished [S4]; they were demolished to make way for railway tracks [S4]; the stage foundations were lost in 1884 (the year of the railway construction in which they were found and demolished) [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Roman Theatre is a Roman theatre (a theatre built in the Roman city of Mogontiacum) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Mainz)]; The theatre is in Mainz, Germany (ancient Mogontiacum, Rhineland Palatinate) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Mainz)]; It was once the largest Roman theatre north of the Alps [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Mainz)]; The theatre measured 116 metres across [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Mainz)]; Foundations of the theatre''s stage building were found in 1884 (during railway construction) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Mainz)]; The stage foundations were recorded before they were demolished [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Mainz)]; The stage foundations were demolished (lost) to make way for railway tracks [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Theatre_(Mainz)]"}]'::jsonb),
    ('1c1c8f74-707b-4ad2-a0db-d7518b9138b6'::uuid, 'card_description', 'Oppidum des Castels crowns a hilltop above the Vaunage, where four stages of construction can be detected. The Volques moved in about 300 BCE; Michel Py excavated it between 1958 and 1974.', 'One of six Iron Age hill forts in the Vaunage valley, occupied from 800 to 50 BC. Four distinct construction phases show a community that kept rebuilding itself.', 'teaser-card-s017-rollback:1c1c8f74-707b-4ad2-a0db-d7518b9138b6:card_description', 'rollback of teaser-card-s017: card_description ''One of six Iron Age hill forts in the Vaunage valley, occupied from 800 to 50 BC. Four distinct construction phases show a community that kept rebuilding itself.'' restored on Oppidum des Castels', '1d9335f2042825919ed8ce7ed9aca135e2320a55d6efb462483662c675a63590|8642f58360c2b209dd527c95546fd56022943c526d3a6823c2ce1c4e242afe38|8642f58360c2b209dd527c95546fd56022943c526d3a6823c2ce1c4e242afe38', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Oppidum des Castels crowns a hilltop above the Vaunage, where four stages of construction can be detected. The Volques moved in about 300 BCE; Michel Py excavated it between 1958 and 1974."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the oppidum is on a hilltop [S1]; the hilltop is above/overlooks the Vaunage [S1]; four stages of construction can be detected [S4]; the Volques moved into the oppidum about 300 BCE [S5]; Michel Py excavated the site [S3]; the excavation took place between 1958 and 1974 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Oppidum des Castels is an oppidum on a hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Nages]; The hilltop is above (overlooks) the Vaunage valley [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Nages]; Four stages of construction can be detected [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Nages]; The Volques moved into the oppidum [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Nages]; The Volques moved in about 300 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Nages]; Michel Py excavated the site [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Nages]; The excavation ran between 1958 and 1974 [SUPPORTED: https://en.wikipedia.org/wiki/Oppidum_de_Nages]"}]'::jsonb),
    ('1cef72f4-b9d4-4180-b93a-10b0cbe1a234'::uuid, 'card_description', 'A spring built the Prison of Solomon: lime settled slowly around its pond into a wall, and when the spring dried, a hollow hill remained, with a pit 80 meters deep at its heart.', 'An 80-metre-deep pit inside a hollow cone-shaped hill, 65 metres across at the top. Locals named it after Solomon, believing he imprisoned demons here. It hosted a Mannaean temple.', 'teaser-card-s017-rollback:1cef72f4-b9d4-4180-b93a-10b0cbe1a234:card_description', 'rollback of teaser-card-s017: card_description ''An 80-metre-deep pit inside a hollow cone-shaped hill, 65 metres across at the top. Locals named it after Solomon, believing he imprisoned demons here. It hosted a Mannaean temple.'' restored on Prison of Solomon', 'e607ec4b3e67f2fc7f74e3befa0e8b412ae54540ae0796f1ee78ae5515ed8609|10b39979949756f9ae83fef8ea3dc470e764aa72852d060029811d25491f638a|10b39979949756f9ae83fef8ea3dc470e764aa72852d060029811d25491f638a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A spring built the Prison of Solomon: lime settled slowly around its pond into a wall, and when the spring dried, a hollow hill remained, with a pit 80 meters deep at its heart."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "a spring created the Prison of Solomon hill (it began by creating a small pond) [S3]; lime settled slowly around the pond [S4]; the settled lime formed a wall [S4]; the spring dried [S5]; a hollow hill remained after the spring dried [S5]; there is a pit 80 meters deep in the hill [S2]; the pit is at the heart (middle) of the hill [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Prison of Solomon is a hollow hill (a hollow cone-shaped hill) [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]; The hill is in Iran (West Azerbaijan province) [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]; A spring built the hill: it is the result of a spring [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]; The spring first created a pond [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]; Lime settled around the pond into a wall [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]; The lime settled slowly (the wall grew slowly over ages) [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]; The spring dried up [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]; A hollow hill remained after the spring dried [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]; There is a pit 80 metres deep [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]; The pit is at the heart (in the middle) of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Prison_of_Solomon]"}]'::jsonb),
    ('1d4dd1f5-e841-4c8c-9761-2d4ad3eec155'::uuid, 'card_description', 'A farmer apparently took Kinniside Stone Circle apart for gate-posts in the 18th century. In 1925 its 11 granite stones were set in concrete, whether in their original holes is unclear.', NULL, 'teaser-card-s017-rollback:1d4dd1f5-e841-4c8c-9761-2d4ad3eec155:card_description', 'rollback of teaser-card-s017: card_description None restored on Kinniside Stone Circle', 'da4c03da589f68ab0aae76fe2b0bc384c3bc1d89a630af02742d3f3c77749ec7|4be255db8cc647ab7d20c10f3dc13ec5b327000e181b5c84766274a3b82ee28a|4be255db8cc647ab7d20c10f3dc13ec5b327000e181b5c84766274a3b82ee28a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A farmer apparently took Kinniside Stone Circle apart for gate-posts in the 18th century. In 1925 its 11 granite stones were set in concrete, whether in their original holes is unclear."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "a farmer took Kinniside Stone Circle apart (hedged: apparently) [S4]; the farmer used the stones for gate-posts [S4]; the dismantling was in the 18th century [S4]; in 1925 the stones were set in concrete [S5]; the circle has 11 stones [S3]; the stones are of granite [S3]; it is unclear whether the stones were set in their original holes [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kinniside Stone Circle is a (reconstructed) stone circle [SUPPORTED: https://en.wikipedia.org/wiki/Kinniside_Stone_Circle]; The site is in England (Cumbria) [SUPPORTED: https://en.wikipedia.org/wiki/Kinniside_Stone_Circle]; The circle was apparently dismantled in the 18th century [SUPPORTED: https://en.wikipedia.org/wiki/Kinniside_Stone_Circle]; It was a farmer who took the circle apart [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA117156]; The farmer used the stones for gate-posts [SUPPORTED: https://en.wikipedia.org/wiki/Kinniside_Stone_Circle]; The circle consists of 11 stones [SUPPORTED: https://en.wikipedia.org/wiki/Kinniside_Stone_Circle]; The stones are granite [SUPPORTED: https://en.wikipedia.org/wiki/Kinniside_Stone_Circle]; The circle was re-erected in 1925 [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA117156]; In the 1925 restoration the stones were set in concrete [SUPPORTED: https://en.wikipedia.org/wiki/Kinniside_Stone_Circle]; It is unclear whether the stones were re-erected in their original holes [SUPPORTED: https://en.wikipedia.org/wiki/Kinniside_Stone_Circle]"}]'::jsonb),
    ('1da76491-5256-486f-b67e-ff6f762c46b5'::uuid, 'card_description', 'On the English Channel coast, High Peak rises to about 157 metres above sea-level. Geological study suggests the site once extended several tens of metres into what is now eroded away.', 'An Iron Age cliff fort being eaten alive by coastal erosion. Pre-Roman, Roman, and Dark Age pottery all found at the same crumbling site.', 'teaser-card-s017-rollback:1da76491-5256-486f-b67e-ff6f762c46b5:card_description', 'rollback of teaser-card-s017: card_description ''An Iron Age cliff fort being eaten alive by coastal erosion. Pre-Roman, Roman, and Dark Age pottery all found at the same crumbling site.'' restored on High Peak, Devon', 'db97ed28c6d0f881c85bf37dde01f7a3024e0165cb7d60f2c06310f5c01471f1|e9ee2bf36c0768aa4ec84a94f04a2746d4e568ce7bd48d2f64e399935ef3b4fc|e9ee2bf36c0768aa4ec84a94f04a2746d4e568ce7bd48d2f64e399935ef3b4fc', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the English Channel coast, High Peak rises to about 157 metres above sea-level. Geological study suggests the site once extended several tens of metres into what is now eroded away."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "High Peak is on the English Channel coast [S1]; its highest point is about 157 metres above sea-level [S2]; geological study suggests (hedged) that the site once extended several tens of metres into what is now eroded away [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "High Peak (Devon) is a hill on the English Channel coast, southwest of Sidmouth, England [SUPPORTED: https://en.wikipedia.org/wiki/High_Peak,_Devon]; The place is an archaeological site: a partially eroded Iron Age hill fort (the text calls it ''the site'') [SUPPORTED: https://en.wikipedia.org/wiki/High_Peak,_Devon]; High Peak rises to about 157 metres above sea-level [SUPPORTED: https://en.wikipedia.org/wiki/High_Peak,_Devon]; Geological study suggests the site once extended several tens of metres into what is now eroded away [SUPPORTED: https://en.wikipedia.org/wiki/High_Peak,_Devon]"}]'::jsonb),
    ('1e3e3665-7232-4c54-bceb-9973db4af1e5'::uuid, 'card_description', 'West of Dunster, the oval Iron Age enclosure of Grabbist Hillfort runs 885.8 feet inside a ditch up to 32.8 feet wide. Ploughing has worn away features, a possible inner rampart among them.', 'Iron Age oval hillfort in Somerset, 270 metres long with a ditch up to 10 metres wide and 2.2 metres deep. A second defensive bank lines the northern and western perimeter.', 'teaser-card-s017-rollback:1e3e3665-7232-4c54-bceb-9973db4af1e5:card_description', 'rollback of teaser-card-s017: card_description ''Iron Age oval hillfort in Somerset, 270 metres long with a ditch up to 10 metres wide and 2.2 metres deep. A second defensive bank lines the northern and western perimeter.'' restored on Grabbist Hillfort', 'e4a4779c1c8630d0419d6e688249f92f70c3cf56bfa88a4690d368e1e21a87e9|29291ffc44a605fc664a581bd295aa2cfdb1cd47690b9e8a64bc6e74cb16faab|29291ffc44a605fc664a581bd295aa2cfdb1cd47690b9e8a64bc6e74cb16faab', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "West of Dunster, the oval Iron Age enclosure of Grabbist Hillfort runs 885.8 feet inside a ditch up to 32.8 feet wide. Ploughing has worn away features, a possible inner rampart among them."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Grabbist Hillfort lies west of Dunster [S1]; it is an oval Iron Age enclosure [S1]; the site is 885.8 feet long [S2]; it is surrounded by a ditch [S3]; the ditch is up to 32.8 feet wide [S3]; ploughing has damaged or erased (worn away) original features [S4]; a possible inner rampart is among the features lost to ploughing (hedge kept: possible) [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Grabbist Hillfort is a hillfort / defended enclosure (an enclosure site) west of Dunster [SUPPORTED: https://en.wikipedia.org/wiki/Grabbist_Hillfort]; The enclosure dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Grabbist_Hillfort]; The enclosure is oval [SUPPORTED: https://en.wikipedia.org/wiki/Grabbist_Hillfort]; The site is west of Dunster [SUPPORTED: https://en.wikipedia.org/wiki/Grabbist_Hillfort]; The enclosure is 885.8 feet long [SUPPORTED: https://en.wikipedia.org/wiki/Grabbist_Hillfort]; It is surrounded by a ditch (the enclosure lies inside a ditch) [SUPPORTED: https://en.wikipedia.org/wiki/Grabbist_Hillfort]; The ditch is up to 32.8 feet wide [SUPPORTED: https://en.wikipedia.org/wiki/Grabbist_Hillfort]; Ploughing has worn away (damaged or erased) some of the original features [SUPPORTED: https://en.wikipedia.org/wiki/Grabbist_Hillfort]; A possible inner rampart is among the features lost to ploughing [SUPPORTED: https://en.wikipedia.org/wiki/Grabbist_Hillfort]"}]'::jsonb),
    ('1f66729b-c7e8-476a-b9cc-84b23a36074f'::uuid, 'card_description', 'On St Mary''s in the Isles of Scilly, Porth Hellick Down holds at least six entrance graves. Unrecorded digs left the largest, The Great Tomb, empty but for pumice and a few potsherds.', 'Porth Hellick Down is a Neolithic and Bronze Age archeological site located on the island of St Mary''s.', 'teaser-card-s017-rollback:1f66729b-c7e8-476a-b9cc-84b23a36074f:card_description', 'rollback of teaser-card-s017: card_description "Porth Hellick Down is a Neolithic and Bronze Age archeological site located on the island of St Mary''s." restored on Porth Hellick Down', '589afdc1aaacbd2d84921187466cc3d03a6d736133bcf940b00d44205e9390a2|f8f50cc1ffd35f12e79d126f833f9cbcbe4f0ee0a0c42a8c99925d24362abc15|f8f50cc1ffd35f12e79d126f833f9cbcbe4f0ee0a0c42a8c99925d24362abc15', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On St Mary''s in the Isles of Scilly, Porth Hellick Down holds at least six entrance graves. Unrecorded digs left the largest, The Great Tomb, empty but for pumice and a few potsherds."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Porth Hellick Down is on St Mary''s in the Isles of Scilly [S1]; the site holds at least six entrance graves [S2]; the largest entrance grave is called The Great Tomb [S3, S6]; earlier excavations at the site were unrecorded [S7]; those earlier digs left the burial chamber (the Great Tomb) empty [S6, S7]; the only things left in it were a piece of pumice and a few pottery fragments [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Porth Hellick Down is an archaeological site / burial monument (cairn cemetery with entrance graves) on St Mary''s in the Isles of Scilly [SUPPORTED: https://en.wikipedia.org/wiki/Porth_Hellick_Down]; The site is on St Mary''s in the Isles of Scilly [SUPPORTED: https://en.wikipedia.org/wiki/Porth_Hellick_Down]; The site holds at least six entrance graves [SUPPORTED: https://en.wikipedia.org/wiki/Porth_Hellick_Down]; The largest of the entrance graves is called The Great Tomb [SUPPORTED: https://en.wikipedia.org/wiki/Porth_Hellick_Down]; The Great Tomb is the name given to that entrance grave [SUPPORTED: https://en.wikipedia.org/wiki/Porth_Hellick_Down]; Earlier unrecorded excavations (digs) at the tomb took place before the recorded 1899 dig [SUPPORTED: https://en.wikipedia.org/wiki/Porth_Hellick_Down]; The Great Tomb''s chamber was left empty except for pumice [SUPPORTED: https://en.wikipedia.org/wiki/Porth_Hellick_Down]; Only a few potsherds (pottery fragments) remained in the chamber [SUPPORTED: https://en.wikipedia.org/wiki/Porth_Hellick_Down]"}]'::jsonb),
    ('2069e069-c994-46e2-b8b8-f8f8dd01abd0'::uuid, 'card_description', 'In the mountains of Zamora, Peñas de la Cerca controls the middle of the Tera valley: an Iron Age hillfort of about the 7th century BC, several enclosures spread across its north slope.', 'A 7th-century BC Iron Age hillfort controlling the middle of the Tera valley. It sits on the boundary between mountain highlands and the plateau below.', 'teaser-card-s017-rollback:2069e069-c994-46e2-b8b8-f8f8dd01abd0:card_description', 'rollback of teaser-card-s017: card_description ''A 7th-century BC Iron Age hillfort controlling the middle of the Tera valley. It sits on the boundary between mountain highlands and the plateau below.'' restored on Peñas de la Cerca', '1f9d53722fbbd91ffce77148737795be3f42e52101e7aae1a30a39c45aef389e|901bba800b7954181f7a26905ffc458d9ad87cc804e461aa72022b2616535daf|901bba800b7954181f7a26905ffc458d9ad87cc804e461aa72022b2616535daf', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the mountains of Zamora, Peñas de la Cerca controls the middle of the Tera valley: an Iron Age hillfort of about the 7th century BC, several enclosures spread across its north slope."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Peñas de la Cerca is in the mountains [S2]; it is in the province of Zamora [S1]; it controls the middle of the Tera valley [S2]; it is an Iron Age hillfort [S1]; it dates to about the 7th century BC [S4]; several enclosures cover its north slope [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Peñas de la Cerca is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C3%B1as_de_la_Cerca]; The hillfort is Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C3%B1as_de_la_Cerca]; The site is in Zamora (province of Zamora, Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C3%B1as_de_la_Cerca]; The site lies in the mountains (a mountainous region) [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C3%B1as_de_la_Cerca]; The site controls the middle of the Tera valley [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C3%B1as_de_la_Cerca]; The hillfort dates to about the 7th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C3%B1as_de_la_Cerca]; The hillfort has several enclosures [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C3%B1as_de_la_Cerca]; The enclosures are spread across (cover) the hill''s north slope [SUPPORTED: https://en.wikipedia.org/wiki/Pe%C3%B1as_de_la_Cerca]"}]'::jsonb),
    ('21ba0be2-3da7-40f7-8f99-aece38b3ea17'::uuid, 'card_description', 'On White Sheet Hill in Wiltshire, a Neolithic causeway camp and barrows share the ground with an Iron Age hill fort, and a Roman road along it was once the main route through Selwood Forest.', 'The hill is also the site of a Neolithic causeway camp and barrows; and an Iron Age hill fort.', 'teaser-card-s017-rollback:21ba0be2-3da7-40f7-8f99-aece38b3ea17:card_description', 'rollback of teaser-card-s017: card_description ''The hill is also the site of a Neolithic causeway camp and barrows; and an Iron Age hill fort.'' restored on White Sheet Hill', '517f73cf93ddded0c0a947d580af7a34c709ac6cc9c01d5a36da2dbbb16c8d77|37f4cc475e5903da6e59585f36b0588369bb85eade3654839e0d80b777855039|37f4cc475e5903da6e59585f36b0588369bb85eade3654839e0d80b777855039', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On White Sheet Hill in Wiltshire, a Neolithic causeway camp and barrows share the ground with an Iron Age hill fort, and a Roman road along it was once the main route through Selwood Forest."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "White Sheet Hill is in Wiltshire [S1]; the hill is the site of a Neolithic causeway camp [S2]; the hill is the site of barrows [S2]; the hill is also the site of an Iron Age hill fort [S2]; a Roman road runs along the hill [S3]; the Roman road was at one time the main route through Selwood Forest [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "White Sheet Hill is a hill in Wiltshire that is the site of ancient earthworks (central claim: a hill with a Neolithic causeway camp, barrows and an Iron Age hill fort, in Wiltshire) [SUPPORTED: https://en.wikipedia.org/wiki/White_Sheet_Hill]; The hill is the site of a Neolithic causeway camp [SUPPORTED: https://en.wikipedia.org/wiki/White_Sheet_Hill]; The hill has barrows (burial mounds) [SUPPORTED: https://en.wikipedia.org/wiki/White_Sheet_Hill]; The hill has an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/White_Sheet_Hill]; A Roman road runs along the hill [SUPPORTED: https://en.wikipedia.org/wiki/White_Sheet_Hill]; The Roman road was once the main route through Selwood Forest [SUPPORTED: https://en.wikipedia.org/wiki/White_Sheet_Hill]"}]'::jsonb),
    ('21d1b1fc-7be0-456a-9be2-528bf2e7095a'::uuid, 'card_description', 'Above the left bank of the Willkanuta River in the Cusco Region, Machu Q''inti keeps company with the sites of Wayna Q''inti, Willkaraqay and Patallaqta, which is also named Q''inti Marka.', '1438–1530 AD. An Inca site above the Willkanuta River near Patallaqta — also known as Q''inti Marka, Quechua for ''hummingbird village'', in the sacred Machu Picchu district.', 'teaser-card-s017-rollback:21d1b1fc-7be0-456a-9be2-528bf2e7095a:card_description', 'rollback of teaser-card-s017: card_description "1438–1530 AD. An Inca site above the Willkanuta River near Patallaqta — also known as Q''inti Marka, Quechua for ''hummingbird village'', in the sacred Machu Picchu district." restored on Machu Q''inti', 'cd77b176a8b1197a314eaba6b920be0470bfc88ad160db683879f66531058431|75063b70e5d2b3c4c79373a0042ceed0a8471358f15aa321ce81673dce1ea81d|75063b70e5d2b3c4c79373a0042ceed0a8471358f15aa321ce81673dce1ea81d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Above the left bank of the Willkanuta River in the Cusco Region, Machu Q''inti keeps company with the sites of Wayna Q''inti, Willkaraqay and Patallaqta, which is also named Q''inti Marka."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Machu Q''inti lies above the left bank of the Willkanuta River [S3]; it is in the Cusco Region [S2]; it is near the archaeological sites of Wayna Q''inti, Willkaraqay and Patallaqta [S3]; Patallaqta is also named Q''inti Marka [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Machu Q''inti is an archaeological site in Peru (in the Cusco Region) [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Q%27inti]; Machu Q''inti is above the left bank of the Willkanuta River [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Q%27inti]; Machu Q''inti is near (keeps company with) the site of Wayna Q''inti [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Q%27inti]; Machu Q''inti is near the sites of Willkaraqay and Patallaqta [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Q%27inti]; Patallaqta is also named Q''inti Marka [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Q%27inti]"}]'::jsonb),
    ('21db0c59-87b1-4d2f-839c-c42543bd56c0'::uuid, 'card_description', 'The Chané, here from about 300 CE, began shaping the great rock of El Fuerte de Samaipata, now almost completely covered in Inca and pre-Inca carvings, among them the spine of the serpent.', 'A sandstone hilltop carved with channels, basins, and figures by three successive cultures: Chané, Inca, and Spanish. The largest carved rock in the Americas.', 'teaser-card-s017-rollback:21db0c59-87b1-4d2f-839c-c42543bd56c0:card_description', 'rollback of teaser-card-s017: card_description ''A sandstone hilltop carved with channels, basins, and figures by three successive cultures: Chané, Inca, and Spanish. The largest carved rock in the Americas.'' restored on El Fuerte de Samaipata', 'f22eb66e8347b3999932831e44696f892ea28bfae708ca8d1f79422d06a44c13|0d26e8aa75a8f10ccb74cb73acea06160ca67bcb128b20bfc861f7651914d7a8|0d26e8aa75a8f10ccb74cb73acea06160ca67bcb128b20bfc861f7651914d7a8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Chané, here from about 300 CE, began shaping the great rock of El Fuerte de Samaipata, now almost completely covered in Inca and pre-Inca carvings, among them the spine of the serpent."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Chané occupied the site from about 300 CE [S3]; the Chané began shaping the great rock of El Fuerte de Samaipata [S4]; the rock is now almost completely covered in carvings [S7]; the carvings are of both Inca and pre-Inca origin [S7]; among the carvings is the spine of the serpent [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "El Fuerte de Samaipata is a pre-Columbian archaeological site, centred on a great carved rock, in Bolivia (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/El_Fuerte_de_Samaipata]; The Chané were at Samaipata from about 300 CE [SUPPORTED: https://en.wikipedia.org/wiki/El_Fuerte_de_Samaipata]; The Chané began shaping the great rock of El Fuerte de Samaipata [SUPPORTED: https://en.wikipedia.org/wiki/El_Fuerte_de_Samaipata]; The rock is now almost completely covered in Inca and pre-Inca carvings [SUPPORTED: https://en.wikipedia.org/wiki/El_Fuerte_de_Samaipata]; Among the carvings is the spine of the serpent [SUPPORTED: https://en.wikipedia.org/wiki/El_Fuerte_de_Samaipata]"}]'::jsonb),
    ('2207dced-e1db-4547-bac5-2d90984550a3'::uuid, 'card_description', 'The core of Regensburg''s Old City was once Castra Regina, a Roman fort built in 179 for Legio III Italica under Emperor Marcus Aurelius, at the most northerly point of the Danube.', 'A Roman garrison at the Danube''s northernmost point, founded in the 1st century AD. Its medieval old town preserves the most intact medieval centre in the region.', 'teaser-card-s017-rollback:2207dced-e1db-4547-bac5-2d90984550a3:card_description', 'rollback of teaser-card-s017: card_description "A Roman garrison at the Danube''s northernmost point, founded in the 1st century AD. Its medieval old town preserves the most intact medieval centre in the region." restored on Regensburg', '1afae256fb071257d6f2c1f735bc60e4fc3045a5c488106f28ad2c3c503d04e0|1e6edf8129db2dfbb886cf63e57c84e6a1f166dc1ff95bc08873d7ccd1d3958b|1e6edf8129db2dfbb886cf63e57c84e6a1f166dc1ff95bc08873d7ccd1d3958b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The core of Regensburg''s Old City was once Castra Regina, a Roman fort built in 179 for Legio III Italica under Emperor Marcus Aurelius, at the most northerly point of the Danube."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the core of Regensburg''s Old City corresponds to the former Castra Regina [S3, S4]; Castra Regina was a Roman fort [S3]; it was built in 179 [S3]; it was built for Legio III Italica [S3]; it was built during the reign of Emperor Marcus Aurelius [S3]; it stood at the most northerly point of the Danube [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The core of Regensburg''s Old City was once Castra Regina, a Roman fort (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Regensburg]; Castra Regina was a Roman fort [SUPPORTED: https://en.wikipedia.org/wiki/Regensburg]; Castra Regina was built in 179 [SUPPORTED: https://en.wikipedia.org/wiki/Regensburg]; Castra Regina was built for Legio III Italica [SUPPORTED: https://en.wikipedia.org/wiki/Regensburg]; The fort was built under Emperor Marcus Aurelius [SUPPORTED: https://en.wikipedia.org/wiki/Regensburg]; The fort lay at the most northerly point of the Danube [SUPPORTED: https://en.wikipedia.org/wiki/Regensburg]"}]'::jsonb),
    ('2297e801-c762-4bb9-9e88-102c65e301a1'::uuid, 'card_description', 'Karatepe-Aslantaş Open-Air Museum holds the ruined walls of Azatiwadaya, an 8th century BC fortress founded by Azatiwada, a local ruler in Cilicia, to defend against invaders from the north.', 'An open-air museum in the ruins of an ancient fortification. The site preserves monumental architecture from the frontier of several ancient civilizations.', 'teaser-card-s017-rollback:2297e801-c762-4bb9-9e88-102c65e301a1:card_description', 'rollback of teaser-card-s017: card_description ''An open-air museum in the ruins of an ancient fortification. The site preserves monumental architecture from the frontier of several ancient civilizations.'' restored on Karatepe-Aslantaş Open-Air Museum', '80193fd0f0278e686f61cb868c30a1fa21a30711639bc039da3cd60c840e50e1|b60284558a5c8ad023e932d608f4877a1011c75ab76a7db05350abb77b8a9030|b60284558a5c8ad023e932d608f4877a1011c75ab76a7db05350abb77b8a9030', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Karatepe-Aslantaş Open-Air Museum holds the ruined walls of Azatiwadaya, an 8th century BC fortress founded by Azatiwada, a local ruler in Cilicia, to defend against invaders from the north."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the museum holds the ruined walls of a fortress [S3, S6]; the fortress was originally named Azatiwadaya [S4]; the fortress dates to the 8th century BC [S3]; it was founded by Azatiwada [S4]; Azatiwada was a local ruler in Cilicia [W1]; it was built to defend against invaders from the north [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Karatepe-Aslantaş Open-Air Museum is an open-air museum in Osmaniye Province, Türkiye, on the site of an ancient fortress [SUPPORTED: https://en.wikipedia.org/wiki/Karatepe-Aslanta%C5%9F_Open-Air_Museum]; The museum holds the ruined walls of the fortress [SUPPORTED: https://en.wikipedia.org/wiki/Karatepe-Aslanta%C5%9F_Open-Air_Museum]; The fortress is an 8th century BC fortress [SUPPORTED: https://en.wikipedia.org/wiki/Karatepe-Aslanta%C5%9F_Open-Air_Museum]; The fortress is called Azatiwadaya [SUPPORTED: https://en.wikipedia.org/wiki/Karatepe-Aslanta%C5%9F_Open-Air_Museum]; It was founded by Azatiwada [SUPPORTED: https://en.wikipedia.org/wiki/Karatepe-Aslanta%C5%9F_Open-Air_Museum]; Azatiwada was a local ruler in Cilicia [SUPPORTED: https://en.wikipedia.org/wiki/Karatepe_bilingual]; The fortress was built to defend against invaders from the north [SUPPORTED: https://en.wikipedia.org/wiki/Karatepe-Aslanta%C5%9F_Open-Air_Museum]"}, {"source": "web fact W1", "url": "https://en.wikipedia.org/wiki/Karatepe_bilingual", "quote": "Azatiwada was a local ruler in Cilicia."}]'::jsonb),
    ('234bd55f-9444-44e9-8fde-7e66c049561d'::uuid, 'card_description', 'In the Ate District of Lima, Puruchuco was an Inca administrative center, set in Huaquerones, a land of pyramids with ramps that holds one of the largest cemeteries of the Inca culture.', 'Puruchuco is located in the sector Huaquerones, a land of pyramids with ramps that contains one of the largest cemeteries in the Inca culture.', 'teaser-card-s017-rollback:234bd55f-9444-44e9-8fde-7e66c049561d:card_description', 'rollback of teaser-card-s017: card_description ''Puruchuco is located in the sector Huaquerones, a land of pyramids with ramps that contains one of the largest cemeteries in the Inca culture.'' restored on Puruchuco', 'a807b823a7e71370300036e2e388f90bd9f9d07847a6e429f1dd66e6f8f65a14|ea0111a56df0ee192f85890c42aa2ff8ec8614e21e4123ea7719dfa42ee5dd85|ea0111a56df0ee192f85890c42aa2ff8ec8614e21e4123ea7719dfa42ee5dd85', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Ate District of Lima, Puruchuco was an Inca administrative center, set in Huaquerones, a land of pyramids with ramps that holds one of the largest cemeteries of the Inca culture."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Puruchuco is in the Ate District of Lima [S1]; it was an Inca administrative center [S1, S2]; it is set in the sector Huaquerones [S3]; Huaquerones is a land of pyramids with ramps [S3]; Huaquerones holds one of the largest cemeteries of the Inca culture [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Puruchuco is an archaeological site that was an Inca administrative center (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Puruchuco]; Puruchuco is in the Ate District of Lima [SUPPORTED: https://en.wikipedia.org/wiki/Puruchuco]; Puruchuco lies in the sector Huaquerones [SUPPORTED: https://en.wikipedia.org/wiki/Puruchuco]; Huaquerones is a land of pyramids with ramps [SUPPORTED: https://en.wikipedia.org/wiki/Puruchuco]; Huaquerones holds one of the largest cemeteries of the Inca culture [SUPPORTED: https://en.wikipedia.org/wiki/Puruchuco]"}]'::jsonb),
    ('2448ad8b-9e65-4eb8-ac3a-ede7cfcfd8e0'::uuid, 'card_description', 'Inside the fortress Saksaywaman above Cuzco, Muyuq Marka is the base of a round Incan tower: three concentric stone walls, and at the center a web-like pattern of 34 intersecting lines.', 'The circular stone base of an Inca tower within the fortress of Sacsayhuaman. Three concentric walls once supported a tower used as a Temple of the Sun before the Spanish dismantled it.', 'teaser-card-s017-rollback:2448ad8b-9e65-4eb8-ac3a-ede7cfcfd8e0:card_description', 'rollback of teaser-card-s017: card_description ''The circular stone base of an Inca tower within the fortress of Sacsayhuaman. Three concentric walls once supported a tower used as a Temple of the Sun before the Spanish dismantled it.'' restored on Muyuq Marka', '7fe5bc8f56481635db357cdbef03acc835d6dca4d3c4533fd535c146dd60b76e|66a24cd72800d2e769728679b441884a858970bd3f72eec16467a49f1ced6b06|66a24cd72800d2e769728679b441884a858970bd3f72eec16467a49f1ced6b06', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Inside the fortress Saksaywaman above Cuzco, Muyuq Marka is the base of a round Incan tower: three concentric stone walls, and at the center a web-like pattern of 34 intersecting lines."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Muyuq Marka is within the fortress Saksaywaman [S2]; the fortress is above Cuzco [S2]; Muyuq Marka is the base of a round Incan tower [S2]; it has three concentric stone walls [S3]; a web-like pattern of 34 intersecting lines lies at the center [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Muyuq Marka is the base of a round Incan tower (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Muyuq_Marka]; Muyuq Marka lies inside the fortress Saksaywaman [SUPPORTED: https://en.wikipedia.org/wiki/Muyuq_Marka]; Saksaywaman lies above Cuzco [SUPPORTED: https://en.wikipedia.org/wiki/Muyuq_Marka]; Muyuq Marka has three concentric stone walls [SUPPORTED: https://en.wikipedia.org/wiki/Muyuq_Marka]; At the center of Muyuq Marka there is a web-like pattern [SUPPORTED: https://en.wikipedia.org/wiki/Muyuq_Marka]; The web-like pattern consists of 34 lines [SUPPORTED: https://en.wikipedia.org/wiki/Muyuq_Marka]; The 34 lines intersect [SUPPORTED: https://en.wikipedia.org/wiki/Muyuq_Marka]"}]'::jsonb),
    ('24553e33-f5bd-409d-bf2f-04c193eb63cf'::uuid, 'card_description', 'Between Jhatpat and Dera Murad Jamali lie the remains of Judeir-jo-daro, a Harappan-period city in Balochistan once home to around 20,240 people, spread across 62 acres.', 'Harappan site active 2600-1900 BC in Balochistan''s Nasirabad District. A federally protected area between Jhat Pat and Dera Murad Jamali, occupied through the height of Indus civilisation.', 'teaser-card-s017-rollback:24553e33-f5bd-409d-bf2f-04c193eb63cf:card_description', 'rollback of teaser-card-s017: card_description "Harappan site active 2600-1900 BC in Balochistan''s Nasirabad District. A federally protected area between Jhat Pat and Dera Murad Jamali, occupied through the height of Indus civilisation." restored on Judeir-jo-daro', '0597629e69b39b5a1a3956ff9258e2d9d00ca4c8fca9d44b526f2be4824bf863|b5fa6db2915b5a00a7f8e6038562c2e2e48a67ca956412363cfc9259417fcd59|b5fa6db2915b5a00a7f8e6038562c2e2e48a67ca956412363cfc9259417fcd59', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Between Jhatpat and Dera Murad Jamali lie the remains of Judeir-jo-daro, a Harappan-period city in Balochistan once home to around 20,240 people, spread across 62 acres."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the remains lie between Jhatpat and Dera Murad Jamali [S3]; Judeir-jo-daro is a Harappan-period site [S1]; it was a city [S2]; it is in Balochistan [S1, S3]; it was home to around 20,240 people [S2]; it spread across 62 acres [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Judeir-jo-daro is an archaeological site, a settlement/city [SUPPORTED: https://en.wikipedia.org/wiki/Judeir-jo-daro]; The site dates to the Harappan period [SUPPORTED: https://en.wikipedia.org/wiki/Judeir-jo-daro]; The site is in Balochistan (Pakistan) [SUPPORTED: https://en.wikipedia.org/wiki/Judeir-jo-daro]; The site lies between Jhatpat and Dera Murad Jamali [SUPPORTED: https://en.wikipedia.org/wiki/Judeir-jo-daro]; The city once had a population of around 20,240 [SUPPORTED: https://en.wikipedia.org/wiki/Judeir-jo-daro]; The city covered 62 acres [SUPPORTED: https://en.wikipedia.org/wiki/Judeir-jo-daro]"}]'::jsonb),
    ('24951d4a-ac38-4098-8f55-6e10e5a59c35'::uuid, 'card_description', 'Legend says a local king or chief lies in Kuninkaanhauta, a Bronze Age mound never opened. It was built on the shore of a bay; since then the coastline has moved nearly 20 kilometers west.', 'The largest Bronze Age burial cairn in its country, 36 metres wide and 4 metres high. Legend says a king lies within, but the grave has never been opened.', 'teaser-card-s017-rollback:24951d4a-ac38-4098-8f55-6e10e5a59c35:card_description', 'rollback of teaser-card-s017: card_description ''The largest Bronze Age burial cairn in its country, 36 metres wide and 4 metres high. Legend says a king lies within, but the grave has never been opened.'' restored on Kuninkaanhauta', '31ed1a0afaaf621bbcd594004fba703d5c2fce87c68da9bc182e210884217f15|7eccca8af58e2aa7fbb170275e4a16648d10117312be1d4f0019f3b6719f7928|7eccca8af58e2aa7fbb170275e4a16648d10117312be1d4f0019f3b6719f7928', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Legend says a local king or chief lies in Kuninkaanhauta, a Bronze Age mound never opened. It was built on the shore of a bay; since then the coastline has moved nearly 20 kilometers west."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "legend says a local king or chief is buried at Kuninkaanhauta [S2]; Kuninkaanhauta is a Bronze Age mound [S1]; the grave has never been opened [S2]; it was built on the shore of a bay [S3]; since the Bronze Age the coastline has moved nearly 20 kilometers west [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kuninkaanhauta is a Bronze Age mound (tumulus/burial cairn) in Finland [SUPPORTED: https://en.wikipedia.org/wiki/Kuninkaanhauta]; Legend says a local king or chief lies buried in it [SUPPORTED: https://en.wikipedia.org/wiki/Kuninkaanhauta]; The mound has never been opened [SUPPORTED: https://en.wikipedia.org/wiki/Kuninkaanhauta]; It was built on the shore of a bay [SUPPORTED: https://en.wikipedia.org/wiki/Kuninkaanhauta]; Since then the coastline has moved nearly 20 kilometers west [SUPPORTED: https://en.wikipedia.org/wiki/Kuninkaanhauta]"}]'::jsonb),
    ('257fe33f-735b-46d0-9cb6-83ca0e03937f'::uuid, 'card_description', 'Threestoneburn Stone Circle sets 16 stones of local pink granite in a woodland clearing, four upright. A flint tool was found, and charcoal spreads that may be traces of fire-rituals.', 'The circle, of the late Neolithic or early Bronze Age, is situated in a large clearing in the modern afforestation of Threestoneburn Wood, formerly overlooking a spacious valley to the east.', 'teaser-card-s017-rollback:257fe33f-735b-46d0-9cb6-83ca0e03937f:card_description', 'rollback of teaser-card-s017: card_description ''The circle, of the late Neolithic or early Bronze Age, is situated in a large clearing in the modern afforestation of Threestoneburn Wood, formerly overlooking a spacious valley to the east.'' restored on Threestoneburn Stone Circle', '335fc7c46e7eaa178418215f827e4b6ebddc3ad6b5d3c0aa4a13f61c8c428019|34927bea628bc649e766902b0dfd43fce21f0543fce73e42ad51e4e75709c278|34927bea628bc649e766902b0dfd43fce21f0543fce73e42ad51e4e75709c278', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Threestoneburn Stone Circle sets 16 stones of local pink granite in a woodland clearing, four upright. A flint tool was found, and charcoal spreads that may be traces of fire-rituals."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the circle has 16 stones [S5]; the stones are of local pink granite [S5]; the circle lies in a woodland clearing [S2]; four of the stones are upright [S6]; a flint tool was found [S8]; spreads of charcoal were found [S8]; the charcoal spreads may be traces of fire-rituals (hedged) [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Threestoneburn Stone Circle is a stone circle (archaeological site) in Northumberland, England [SUPPORTED: https://en.wikipedia.org/wiki/Threestoneburn_Stone_Circle]; It lies in a woodland clearing [SUPPORTED: https://en.wikipedia.org/wiki/Threestoneburn_Stone_Circle]; The circle consists of 16 stones [SUPPORTED: https://en.wikipedia.org/wiki/Threestoneburn_Stone_Circle]; The stones are of local pink granite [SUPPORTED: https://en.wikipedia.org/wiki/Threestoneburn_Stone_Circle]; Four of the stones are upright [SUPPORTED: https://en.wikipedia.org/wiki/Threestoneburn_Stone_Circle]; A flint tool was found at the circle [SUPPORTED: https://en.wikipedia.org/wiki/Threestoneburn_Stone_Circle]; Spreads of charcoal were found that may be traces of fire-rituals (an uncertain interpretation) [SUPPORTED: https://en.wikipedia.org/wiki/Threestoneburn_Stone_Circle]"}]'::jsonb),
    ('261ab0dd-0674-4864-9162-87b179787403'::uuid, 'card_description', 'On the western side of the Cordillera Negra, at about 4,200 metres, lies Hatun Machay: a rock forest with archaeological remains, its name possibly from the Quechua words for big and cave.', 'A rock forest at 4,200 metres altitude with archaeological remains including rock paintings. Towering natural stone formations create a surreal landscape of corridors and chambers.', 'teaser-card-s017-rollback:261ab0dd-0674-4864-9162-87b179787403:card_description', 'rollback of teaser-card-s017: card_description ''A rock forest at 4,200 metres altitude with archaeological remains including rock paintings. Towering natural stone formations create a surreal landscape of corridors and chambers.'' restored on Hatun Machay', '211029de677efa3ad32c414908e676d3d55aaa2be9f2f6d54da099bf148f8c97|f0582607fb936becc191c0a8f34deabbebfeaa450724cb4205bd263fb8e0f9e2|f0582607fb936becc191c0a8f34deabbebfeaa450724cb4205bd263fb8e0f9e2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the western side of the Cordillera Negra, at about 4,200 metres, lies Hatun Machay: a rock forest with archaeological remains, its name possibly from the Quechua words for big and cave."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "it lies on the western side of the Cordillera Negra [S3]; it lies at about 4,200 metres [S3]; Hatun Machay is a rock forest [S1]; it has archaeological remains [S1]; its name possibly comes from the Quechua words for big and cave [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Hatun Machay is a rock forest in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Hatun_Machay]; Hatun Machay has archaeological remains [SUPPORTED: https://en.wikipedia.org/wiki/Hatun_Machay]; It lies on the western side of the Cordillera Negra [SUPPORTED: https://en.wikipedia.org/wiki/Hatun_Machay]; It lies at about 4,200 metres altitude [SUPPORTED: https://www.gob.pe/institucion/munipampaschico/campa%C3%B1as/76765-visita-hatun-machay]; The name possibly comes from Quechua hatun, meaning big [SUPPORTED: https://en.wikipedia.org/wiki/Hatun_Machay]; The name possibly comes from Quechua mach''ay, meaning cave [SUPPORTED: https://en.wikipedia.org/wiki/Hatun_Machay]"}]'::jsonb),
    ('270204ad-72e5-451b-829b-9c04ece99766'::uuid, 'card_description', 'Above Goblin Combe lies Cleeve Toot, a roughly oval Iron Age hillfort ringed by a single stone rampart and a broad, shallow outer ditch. Pits found here point to round houses.', 'Built around 800 BC above Goblin Combe in Somerset, this oval univallate fort is 125 by 90 meters. A smaller settlement 150 meters to the north was its satellite community.', 'teaser-card-s017-rollback:270204ad-72e5-451b-829b-9c04ece99766:card_description', 'rollback of teaser-card-s017: card_description ''Built around 800 BC above Goblin Combe in Somerset, this oval univallate fort is 125 by 90 meters. A smaller settlement 150 meters to the north was its satellite community.'' restored on Cleeve Toot', '71cfe03278d32fc0abe3f238dbb728d233cb71ad2aa297ff945a8f9bb375a5d3|8f21864e3cdbc9e11373dbb0bf23655ce8a18fae71c26083f0ae17f064dc6ec2|8f21864e3cdbc9e11373dbb0bf23655ce8a18fae71c26083f0ae17f064dc6ec2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Above Goblin Combe lies Cleeve Toot, a roughly oval Iron Age hillfort ringed by a single stone rampart and a broad, shallow outer ditch. Pits found here point to round houses."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cleeve Toot lies above Goblin Combe [S1]; it is an Iron Age hillfort [S1]; it is roughly oval [S3]; it has a single stone rampart [S6]; it has a broad, shallow outer ditch [S6]; pits were found at the site [S5]; the pits point to round houses [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cleeve Toot is a hillfort above Goblin Combe [SUPPORTED: https://en.wikipedia.org/wiki/Cleeve_Toot]; The hillfort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Cleeve_Toot]; The enclosure is roughly oval [SUPPORTED: https://en.wikipedia.org/wiki/Cleeve_Toot]; It has a single rampart (univallate) [SUPPORTED: https://en.wikipedia.org/wiki/Cleeve_Toot]; The rampart is of stone [SUPPORTED: https://en.wikipedia.org/wiki/Cleeve_Toot]; It has a broad, shallow outer ditch [SUPPORTED: https://en.wikipedia.org/wiki/Cleeve_Toot]; Pits have been found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Cleeve_Toot]; The pits indicate the presence of round houses [SUPPORTED: https://en.wikipedia.org/wiki/Cleeve_Toot]"}]'::jsonb),
    ('2715f436-40ec-4225-b5b6-8cc9523b2048'::uuid, 'card_description', 'At Dahshur, the Bent Pyramid of Pharaoh Sneferu rises from the desert at 54 degrees, then above 47 metres turns to a shallower 43 degrees. Two entrances lead to two separate chamber systems.', 'A pyramid that changes angle partway up -- 54 degrees at the base, 43 at the top. Engineers likely shifted the angle mid-build to prevent collapse, creating its bent shape.', 'teaser-card-s017-rollback:2715f436-40ec-4225-b5b6-8cc9523b2048:card_description', 'rollback of teaser-card-s017: card_description ''A pyramid that changes angle partway up -- 54 degrees at the base, 43 at the top. Engineers likely shifted the angle mid-build to prevent collapse, creating its bent shape.'' restored on Bent Pyramid', 'e61173d1c67ca466f6beffa25961741078e2f7b81090a37cbbfd5342bf2f113a|34497c429f839953442826d293faaf1d2bccaaf2890bb7f168578820f2c7b581|34497c429f839953442826d293faaf1d2bccaaf2890bb7f168578820f2c7b581', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Dahshur, the Bent Pyramid of Pharaoh Sneferu rises from the desert at 54 degrees, then above 47 metres turns to a shallower 43 degrees. Two entrances lead to two separate chamber systems."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Bent Pyramid is at Dahshur [S1]; it belongs to Pharaoh Sneferu (built under him) [S1]; it rises from the desert at 54 degrees [S2]; above 47 metres it turns to a shallower 43 degrees [S2]; it has two entrances [S4]; the two entrances connect to two separate chamber systems [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Bent Pyramid is an ancient Egyptian pyramid (royal tomb monument) at the royal necropolis of Dahshur, Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Bent_Pyramid]; The Bent Pyramid was built for Pharaoh Sneferu [SUPPORTED: https://en.wikipedia.org/wiki/Bent_Pyramid]; The pyramid rises from the desert at a 54 degree inclination [SUPPORTED: https://en.wikipedia.org/wiki/Bent_Pyramid]; Above 47 metres the upper section turns to a shallower 43 degrees [SUPPORTED: https://en.wikipedia.org/wiki/Bent_Pyramid]; The pyramid has two entrances [SUPPORTED: https://en.wikipedia.org/wiki/Bent_Pyramid]; The two entrances lead to two separate chamber systems [SUPPORTED: https://en.wikipedia.org/wiki/Bent_Pyramid]"}]'::jsonb),
    ('27226cef-1c90-46cc-ac31-6b568c7f6c8a'::uuid, 'card_description', 'Duropolis in Dorset is believed to be Britain''s first planned town. Remains of 16 Iron Age roundhouses were dug up, and animal skeletons may hint at a belief in hybrid-animal monster myths.', 'A 32,000-square-metre Iron Age settlement dating to 100 BC — 70 years older than Roman Silchester. It may be the first planned town in Britain.', 'teaser-card-s017-rollback:27226cef-1c90-46cc-ac31-6b568c7f6c8a:card_description', 'rollback of teaser-card-s017: card_description ''A 32,000-square-metre Iron Age settlement dating to 100 BC — 70 years older than Roman Silchester. It may be the first planned town in Britain.'' restored on Duropolis', '8a0bdd2fa6060aff8e6004b433cb940b125af6a2cf19426b6c76ddfd3ac2ad32|b7a5e742d022868231d8f86692c7a66cbf5d3d24a6329a66643e03377da0d6f3|b7a5e742d022868231d8f86692c7a66cbf5d3d24a6329a66643e03377da0d6f3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Duropolis in Dorset is believed to be Britain''s first planned town. Remains of 16 Iron Age roundhouses were dug up, and animal skeletons may hint at a belief in hybrid-animal monster myths."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Duropolis is in Dorset [S1]; it is believed to be Britain''s first planned town [S1]; remains of 16 Iron Age roundhouses were excavated [S5]; animal skeletons were found at the site [S6]; the skeletons may hint at a belief in hybrid-animal monster myths (hedged) [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Duropolis is an archaeological site, an Iron Age settlement, in Dorset, England [SUPPORTED: https://en.wikipedia.org/wiki/Duropolis]; Duropolis is believed to be Britain''s first planned town [SUPPORTED: https://en.wikipedia.org/wiki/Duropolis]; Remains of 16 roundhouses were dug up (excavated) at Duropolis [SUPPORTED: https://en.wikipedia.org/wiki/Duropolis]; The roundhouses date to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Duropolis]; Animal skeletons were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Duropolis]; The animal skeletons may hint at a belief in hybrid-animal monster myths [SUPPORTED: https://en.wikipedia.org/wiki/Duropolis]"}]'::jsonb),
    ('277970ce-65f8-403a-8e20-dbcadac0f214'::uuid, 'card_description', 'Eston Nab, a sandstone cliff at 242 metres, bears Bronze Age burial mounds and the boulder walls of an Iron Age hill fort built around 700 BC. Parts of a cremation urn were unearthed.', 'Frank Elgee, curator of the Dorman Museum, Middlesbrough, in 1927, uncovered parts of an earthenware cremation urn, together with burnt bone and flint.', 'teaser-card-s017-rollback:277970ce-65f8-403a-8e20-dbcadac0f214:card_description', 'rollback of teaser-card-s017: card_description ''Frank Elgee, curator of the Dorman Museum, Middlesbrough, in 1927, uncovered parts of an earthenware cremation urn, together with burnt bone and flint.'' restored on Eston Nab', '1f7792797189ca7d6d8933a4ab8f0c767c21853eca9aec46235f1819bbefe02a|55cc86f8b21941ecee2ccac0b849e9198dc1cf9893537fbcd2c1cd8f5e17758d|55cc86f8b21941ecee2ccac0b849e9198dc1cf9893537fbcd2c1cd8f5e17758d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Eston Nab, a sandstone cliff at 242 metres, bears Bronze Age burial mounds and the boulder walls of an Iron Age hill fort built around 700 BC. Parts of a cremation urn were unearthed."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Eston Nab is a sandstone cliff [S1]; it stands at 242 metres [S1]; it bears Bronze Age burial mounds [S3]; it has the boulder walls of an Iron Age hill fort [S3, S6, S7]; the walls were built around 700 BC [S7]; parts of a cremation urn were unearthed [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Eston Nab is a hilltop site with Bronze Age burial mounds and an Iron Age hill fort, in England [SUPPORTED: https://en.wikipedia.org/wiki/Eston_Nab]; Eston Nab is a sandstone cliff [SUPPORTED: https://en.wikipedia.org/wiki/Eston_Nab]; Eston Nab stands at 242 metres [SUPPORTED: https://en.wikipedia.org/wiki/Eston_Nab]; Eston Nab bears Bronze Age burial mounds [SUPPORTED: https://en.wikipedia.org/wiki/Eston_Nab]; Eston Nab bears an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Eston_Nab]; The hill fort has boulder walls, built around 700 BC [SUPPORTED: https://en.wikipedia.org/wiki/Eston_Nab]; Parts of a cremation urn were unearthed at Eston Nab [SUPPORTED: https://en.wikipedia.org/wiki/Eston_Nab]"}]'::jsonb),
    ('27f27e7e-4224-4378-b0d2-ef22f88bd725'::uuid, 'card_description', 'Atop Monte Adranone, 900 metres up, lie the imposing ruins of a city, possibly Adranon, that dominated the road from Selinunte to Akragas until it was destroyed in the 3rd century BC.', 'An ancient city at 900 metres elevation with both Greek and Punic cultural layers. Its hilltop position made it a contested prize during the wars between Greeks and Carthaginians in Sicily.', 'teaser-card-s017-rollback:27f27e7e-4224-4378-b0d2-ef22f88bd725:card_description', 'rollback of teaser-card-s017: card_description ''An ancient city at 900 metres elevation with both Greek and Punic cultural layers. Its hilltop position made it a contested prize during the wars between Greeks and Carthaginians in Sicily.'' restored on Monte Adranone', '4674f2b0335f98e194446f87be62c2fa35808de39103b5842e1ec6f47c71439d|b5f290fb8525a5ef3c3c833bc11b8607f2fcd4f6aafffe459f121ce4cb653ae3|b5f290fb8525a5ef3c3c833bc11b8607f2fcd4f6aafffe459f121ce4cb653ae3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Atop Monte Adranone, 900 metres up, lie the imposing ruins of a city, possibly Adranon, that dominated the road from Selinunte to Akragas until it was destroyed in the 3rd century BC."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the ruins lie atop Monte Adranone [S2]; the mountain is 900 metres above sea level [S1]; the ruins are imposing [S4]; they are the ruins of an ancient city [S2]; the city was possibly Adranon [S2]; the site dominated the road from Selinunte to Akragas [S4]; it was destroyed in the 3rd century BC [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Monte Adranone is an ancient city site (ruins of an ancient city, Magna Graecia) [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Adranone]; Monte Adranone lies in Sicily, Italy (province of Agrigento) [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Adranone]; The ruins lie atop the mountain, at its summit [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Adranone]; The mountain rises 900 metres [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Adranone]; The city is possibly Adranon [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Adranone]; The ruins are imposing [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Adranone]; The city dominated the road from Selinunte to Akragas [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Adranone]; The city was destroyed in the 3rd century BC [SUPPORTED: https://en.wikipedia.org/wiki/Monte_Adranone]"}]'::jsonb),
    ('28579aa8-dab5-444d-9ee0-61c95cd1c073'::uuid, 'card_description', 'Viracochapampa, its name possibly from the Andean divinity Wiracocha, holds a pre-Inca building complex at 3,070 metres: a Wari administrative center, occupied in the 7th and 8th centuries.', 'Viracochapampa is located about 3.5 km north of Huamachuco in the region of La Libertad at an elevation of 3,070 metres.', 'teaser-card-s017-rollback:28579aa8-dab5-444d-9ee0-61c95cd1c073:card_description', 'rollback of teaser-card-s017: card_description ''Viracochapampa is located about 3.5 km north of Huamachuco in the region of La Libertad at an elevation of 3,070 metres.'' restored on Viracochapampa', 'c79094e8380a24741b396989623b874952969efd1078eccf2e17727b970e4752|62b0ea21b2816fb7607c17e152b6c5277f7df3564776bdccb3306fcfbcbcb3ed|62b0ea21b2816fb7607c17e152b6c5277f7df3564776bdccb3306fcfbcbcb3ed', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Viracochapampa, its name possibly from the Andean divinity Wiracocha, holds a pre-Inca building complex at 3,070 metres: a Wari administrative center, occupied in the 7th and 8th centuries."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the name possibly comes from the Andean divinity Wiracocha [S1]; the site holds a pre-Inca building complex [S1]; it lies at 3,070 metres [S3]; it was an administrative center of the Wari culture [S2]; it was occupied in the 7th and 8th centuries [S4, S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Viracochapampa is an archaeological site in Peru with the remains of a pre-Inca building complex [SUPPORTED: https://en.wikipedia.org/wiki/Viracochapampa]; The name possibly derives from the Andean divinity Wiracocha [SUPPORTED: https://en.wikipedia.org/wiki/Viracochapampa]; The site lies at 3,070 metres elevation [SUPPORTED: https://en.wikipedia.org/wiki/Viracochapampa]; The building complex was a Wari administrative center [SUPPORTED: https://en.wikipedia.org/wiki/Viracochapampa]; The site was occupied in the 7th and 8th centuries [SUPPORTED: https://en.wikipedia.org/wiki/Viracochapampa]"}]'::jsonb),
    ('2882893b-da7b-4afa-bd4a-e8d4ffb76dcd'::uuid, 'card_description', 'Water kept the land around the Roman Villa of Freiria inhabited for ages: a Palaeolithic site lies 300 metres to the north, traces of a Chalcolithic settlement 200 metres northeast.', 'Near Cascais, this villa shows gradual Romanisation — imported Iron Age goods giving way to local production, then full Roman villa construction from the 1st century AD onward.', 'teaser-card-s017-rollback:2882893b-da7b-4afa-bd4a-e8d4ffb76dcd:card_description', 'rollback of teaser-card-s017: card_description ''Near Cascais, this villa shows gradual Romanisation — imported Iron Age goods giving way to local production, then full Roman villa construction from the 1st century AD onward.'' restored on Roman Villa of Freiria', '5ba43c039f56bcbf3480d4001a9caf5d81e83346440c25118f5c89c58d04168a|dd3a4ce1333ad79f4e49253b2efe6a49acbd047ac59c4d4288d04ddb834f07f2|dd3a4ce1333ad79f4e49253b2efe6a49acbd047ac59c4d4288d04ddb834f07f2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Water kept the land around the Roman Villa of Freiria inhabited for ages: a Palaeolithic site lies 300 metres to the north, traces of a Chalcolithic settlement 200 metres northeast."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the land around the villa has long been inhabited [S2]; access to water is why it was inhabited [S2]; a Palaeolithic site lies 300 metres to the north [S3]; traces of a Chalcolithic settlement lie 200 metres to the northeast [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Roman Villa of Freiria is a Roman villa (in Portugal, municipality of Cascais) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Freiria]; The land around the villa has long been inhabited because of access to water [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Freiria]; A Palaeolithic site lies 300 metres to the north of the villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Freiria]; Traces of a Chalcolithic settlement lie 200 metres to the northeast of the villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Freiria]"}]'::jsonb),
    ('28b7b9c1-3901-4762-a71f-353d6ba8b513'::uuid, 'card_description', 'North of Doncaster, the bridleway of Roman Ridge was part of Ermine Street, a Roman road. It runs past Scawsby and Highfields to the Great North Road, then joins the A1 as far as Barnsdale.', '1st-century AD Roman road, part of Ermine Street north of Doncaster. The bridleway still runs at an angle between modern roads — its Roman alignment cutting through suburban parkland.', 'teaser-card-s017-rollback:28b7b9c1-3901-4762-a71f-353d6ba8b513:card_description', 'rollback of teaser-card-s017: card_description ''1st-century AD Roman road, part of Ermine Street north of Doncaster. The bridleway still runs at an angle between modern roads — its Roman alignment cutting through suburban parkland.'' restored on Roman Ridge', 'c6e631859ef836b32b3a3e5a2157bc090c0243a81a00721945b9bcb43f7d8154|b8f9c0e5fc4d06eb2d21ae5033ed23fa9991b1d716b700fdd24b5602460a485a|b8f9c0e5fc4d06eb2d21ae5033ed23fa9991b1d716b700fdd24b5602460a485a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "North of Doncaster, the bridleway of Roman Ridge was part of Ermine Street, a Roman road. It runs past Scawsby and Highfields to the Great North Road, then joins the A1 as far as Barnsdale."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Roman Ridge lies north of Doncaster [S1]; it is a bridleway [S1]; it was part of Ermine Street [S1]; Ermine Street is a Roman road [S1]; it runs past Scawsby [S1, S4]; it runs past Highfields [S5]; it runs to the Great North Road [S5]; it then joins the A1 as far as Barnsdale [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Roman Ridge is a bridleway [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Ridge]; Roman Ridge lies north of Doncaster (England) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Ridge]; Roman Ridge was part of Ermine Street [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Ridge]; Ermine Street is a Roman road [SUPPORTED: https://en.wikipedia.org/wiki/Ermine_Street]; It runs past Scawsby [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Ridge]; It runs past Highfields [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Ridge]; It runs to the Great North Road [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Ridge]; From the Great North Road it joins the A1 [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Ridge]; It follows the A1 as far as Barnsdale [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Ridge]"}]'::jsonb),
    ('29245d49-3e8c-4c31-baf4-a3cdd54a8964'::uuid, 'card_description', 'Patara, for a period the capital of Lycia, was said to be founded by Patarus, a son of Apollo. Its temple and oracle of Apollo were second only in importance to that of Delphi.', 'Ruins of the capital of Lycia, with a 6,000-seat theatre, Ionic colonnades, Hadrian''s granary, and a lighthouse. Its harbor is now a swamp choked with sand.', 'teaser-card-s017-rollback:29245d49-3e8c-4c31-baf4-a3cdd54a8964:card_description', 'rollback of teaser-card-s017: card_description "Ruins of the capital of Lycia, with a 6,000-seat theatre, Ionic colonnades, Hadrian''s granary, and a lighthouse. Its harbor is now a swamp choked with sand." restored on Patara', '4d582d96eef878f2d2b5cfd68747478167a151c1c3fadf771f80c519c14b85c4|963f6912764b857cec599ae5a22b7fbff4d3c9b7f779fefe063aa2d600386191|963f6912764b857cec599ae5a22b7fbff4d3c9b7f779fefe063aa2d600386191', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Patara, for a period the capital of Lycia, was said to be founded by Patarus, a son of Apollo. Its temple and oracle of Apollo were second only in importance to that of Delphi."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Patara was for a period the capital of Lycia [S1]; it was said to have been founded by Patarus [S3]; Patarus was a son of Apollo [S3]; it had a temple and oracle of Apollo [S4]; the temple and oracle were second only in importance to that of Delphi [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Patara was an ancient city (maritime and commercial city, on the Turkish coast in Antalya Province) [SUPPORTED: https://en.wikipedia.org/wiki/Patara_(Lycia)]; Patara was for a period the capital of Lycia [SUPPORTED: https://en.wikipedia.org/wiki/Patara_(Lycia)]; Patara was said to have been founded by Patarus [SUPPORTED: https://en.wikipedia.org/wiki/Patara_(Lycia)]; Patarus was a son of Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Patara_(Lycia)]; Patara had a temple of Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Patara_(Lycia)]; Patara had an oracle of Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Patara_(Lycia)]; The temple and oracle of Apollo at Patara were second only in importance to that of Delphi [SUPPORTED: https://en.wikipedia.org/wiki/Patara_(Lycia)]"}]'::jsonb),
    ('29efc463-cdf8-4dd6-849b-ff378c87a2de'::uuid, 'card_description', 'North of Lake Paucarcocha lies Pirca Pirca, a site whose name possibly comes from the Aymara and Quechua word for wall. In 2013 it was declared a National Cultural Heritage of Peru.', '1000-1500 AD Andean site north of Lake Paucarcocha in Yauyos Province. Pirca Pirca preserves traces of the pre-Inca communities that occupied remote high-altitude lake-basin landscapes.', 'teaser-card-s017-rollback:29efc463-cdf8-4dd6-849b-ff378c87a2de:card_description', 'rollback of teaser-card-s017: card_description ''1000-1500 AD Andean site north of Lake Paucarcocha in Yauyos Province. Pirca Pirca preserves traces of the pre-Inca communities that occupied remote high-altitude lake-basin landscapes.'' restored on Pirca Pirca, Lima', '4a8be7243f1373b7fa34f3e9f7f3539dd05000ef03b01698cd6239ef25fff9c5|0f55cbc2dacd245e1a2666f2f9c2479e8b776bf08c4f90cc1d1791cc14dd2791|0f55cbc2dacd245e1a2666f2f9c2479e8b776bf08c4f90cc1d1791cc14dd2791', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "North of Lake Paucarcocha lies Pirca Pirca, a site whose name possibly comes from the Aymara and Quechua word for wall. In 2013 it was declared a National Cultural Heritage of Peru."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pirca Pirca lies north of Lake Paucarcocha [S4]; its name possibly comes from the Aymara and Quechua word for wall [S1]; it was declared a National Cultural Heritage of Peru [S3]; the declaration was in 2013 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pirca Pirca is an archaeological site (in Peru, Lima Region, Yauyos Province, Tanta District) [SUPPORTED: https://en.wikipedia.org/wiki/Pirca_Pirca,_Lima]; Pirca Pirca lies north of Lake Paucarcocha [SUPPORTED: https://en.wikipedia.org/wiki/Lake_Paucarcocha]; The name Pirca Pirca possibly comes from the Aymara and Quechua word for wall [SUPPORTED: https://en.wikipedia.org/wiki/Pirca_Pirca,_Lima]; In 2013 Pirca Pirca was declared a National Cultural Heritage of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Pirca_Pirca,_Lima]; Context of the 2013 declaration: Pirca Pirca had already been declared Patrimonio Cultural de la Nacion by RDN 143/INC on 27 January 2006; the 2013 resolution re-included it in RDN 2055/INC after a 2006 rectification had omitted it [SUPPORTED: https://www.elperulegal.com/2013/02/resolucion-viceministerial-n-011-2013.html?m=0]"}]'::jsonb),
    ('2a37333e-17ba-4a27-8084-3759d0b8501f'::uuid, 'card_description', 'In Tham Lod Rockshelter, a 30 metre deep cave by the Nam Lang stream, lay hearths, a tool workshop with at least 1722 stone artifacts, and four human burials, two laid one above the other.', 'Archaeological remains of hearths, a workshop for the production of stone tools, and a set of burials have been found.', 'teaser-card-s017-rollback:2a37333e-17ba-4a27-8084-3759d0b8501f:card_description', 'rollback of teaser-card-s017: card_description ''Archaeological remains of hearths, a workshop for the production of stone tools, and a set of burials have been found.'' restored on Tham Lod Rockshelter', 'd2fe5e4280df005779683a76708c8203e3484a4241f1e9a19eb3285d1bce94ab|16f679f1dfe9c427c38d3ffddf70fd8b9589038845b08832cf4b411d2463ea70|16f679f1dfe9c427c38d3ffddf70fd8b9589038845b08832cf4b411d2463ea70', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Tham Lod Rockshelter, a 30 metre deep cave by the Nam Lang stream, lay hearths, a tool workshop with at least 1722 stone artifacts, and four human burials, two laid one above the other."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tham Lod Rockshelter is a 30 metre deep cave [S1]; it is by the Nam Lang stream [S1]; hearths were found [S2]; a tool workshop was found [S2, S4]; at least 1722 stone artifacts were found [S3]; there were four human burials [S6]; two of the bodies were buried one above the other [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tham Lod Rockshelter is a rockshelter / cave (in northern Thailand) [SUPPORTED: https://en.wikipedia.org/wiki/Tham_Lod_Rockshelter]; The cave is 30 metres deep [SUPPORTED: https://en.wikipedia.org/wiki/Tham_Lod_Rockshelter]; The cave is by the Nam Lang stream [SUPPORTED: https://en.wikipedia.org/wiki/Tham_Lod_Rockshelter]; Hearths were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Tham_Lod_Rockshelter]; A tool workshop was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Tham_Lod_Rockshelter]; The workshop held at least 1722 stone artifacts [SUPPORTED: https://en.wikipedia.org/wiki/Tham_Lod_Rockshelter]; The rockshelter contained four human burials [SUPPORTED: https://en.wikipedia.org/wiki/Tham_Lod_Rockshelter]; Two of the burials were laid one above the other [SUPPORTED: https://en.wikipedia.org/wiki/Tham_Lod_Rockshelter]"}]'::jsonb),
    ('2ac1dae4-0ddb-4592-ae5d-1b628466832d'::uuid, 'card_description', 'No ancient author mentioned Kitanaura Antik Kenti, a Lycian city with walls from Hellenistic to Byzantine times. Five churches hint at its later rise, and coins revealed its name in 1998.', '1st-century AD Lycian city whose history is largely unwritten. Kitanaura''s acropolis walls survive 5-6 metres tall in places; two basilicas and cisterns fill a hilltop whose builders remain unknown.', 'teaser-card-s017-rollback:2ac1dae4-0ddb-4592-ae5d-1b628466832d:card_description', 'rollback of teaser-card-s017: card_description "1st-century AD Lycian city whose history is largely unwritten. Kitanaura''s acropolis walls survive 5-6 metres tall in places; two basilicas and cisterns fill a hilltop whose builders remain unknown." restored on Kitanaura Antik Kenti', '747f95f987548149b33c8cf1c12506f0a332c6871135201b262d0894d883eceb|860591f162152a8386a38637ff73d05b0a70035cbbad2b05d5bc6703415075e1|860591f162152a8386a38637ff73d05b0a70035cbbad2b05d5bc6703415075e1', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "No ancient author mentioned Kitanaura Antik Kenti, a Lycian city with walls from Hellenistic to Byzantine times. Five churches hint at its later rise, and coins revealed its name in 1998."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "no ancient author mentioned Kitanaura (its history is largely unknown) [S3]; Kitanaura was a city in Lycia [S1]; its walls date from the Hellenistic period (earliest phase) to the Byzantine period (last phase) [S4]; five churches have been identified [S5]; the churches hint (likely) that the city became more important later, with Christianity in Late Antiquity [S5]; a study of coins led to the identification of the city''s name [S7]; the coin study was in 1998 [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kitanaura Antik Kenti is an ancient city (a settlement), a Lycian one [SUPPORTED: https://en.wikipedia.org/wiki/Kitanaura]; The city lies in Turkey (Kumluca district, Antalya Province) [SUPPORTED: https://en.wikipedia.org/wiki/Kitanaura]; No ancient author mentioned Kitanaura (its history is largely unknown) [SUPPORTED: https://en.wikipedia.org/wiki/Kitanaura]; The earliest phase of the city walls dates to the Hellenistic period [SUPPORTED: https://en.wikipedia.org/wiki/Kitanaura]; The last phase of the city walls dates to the Byzantine period [SUPPORTED: https://en.wikipedia.org/wiki/Kitanaura]; Five churches have been identified at the city [SUPPORTED: https://en.wikipedia.org/wiki/Kitanaura]; The five churches hint that the city rose in importance later (with the spread of Christianity in Late Antiquity) [SUPPORTED: https://en.wikipedia.org/wiki/Kitanaura]; Coins revealed (led to the identification of) the name of the city [SUPPORTED: https://en.wikipedia.org/wiki/Kitanaura]; The coin study that identified the name was made in 1998 [SUPPORTED: https://en.wikipedia.org/wiki/Kitanaura]"}]'::jsonb),
    ('2adae6b7-2156-4080-aaa0-921dd7f8a9c9'::uuid, 'card_description', 'Near the Pembrokeshire Coast Path, a capstone 4.7 metres by 2.7 metres rests on three of six stones: Carreg Samson, a 5000-year-old dolmen whose gaps were once blocked to shelter sheep.', 'The site was excavated in 1968 which revealed four additional stone-holes, one having supported a further chamber stone, the others indicating a possible passage leading off to the northwest.', 'teaser-card-s017-rollback:2adae6b7-2156-4080-aaa0-921dd7f8a9c9:card_description', 'rollback of teaser-card-s017: card_description ''The site was excavated in 1968 which revealed four additional stone-holes, one having supported a further chamber stone, the others indicating a possible passage leading off to the northwest.'' restored on Carreg Samson', '8f2555e0bcd4014b02039f870b9bc3408b5eb95955b63eeb5e8330ee6e80d191|c71d0493e06b565527784dd9677890de096ce3e11b65960d0c3d81362d6e9a2b|c71d0493e06b565527784dd9677890de096ce3e11b65960d0c3d81362d6e9a2b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near the Pembrokeshire Coast Path, a capstone 4.7 metres by 2.7 metres rests on three of six stones: Carreg Samson, a 5000-year-old dolmen whose gaps were once blocked to shelter sheep."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is near the Pembrokeshire Coast Path [S1]; the capstone measures 4.7 metres by 2.7 metres [S2]; the capstone rests on three of six stones [S3]; Carreg Samson is a dolmen [S1]; it is 5000 years old [S1]; stones were once used to block the holes (gaps) in the sides of the tomb [S4]; this was done so the tomb could be used as a shelter for sheep [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Carreg Samson is a dolmen (Neolithic burial chamber) [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Samson]; Carreg Samson lies near the Pembrokeshire Coast Path, in Wales [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Samson]; Carreg Samson is 5000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Samson]; The capstone measures 4.7 metres by 2.7 metres [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Samson]; The capstone rests on three stones [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Samson]; There are six stones in all, of which three carry the capstone [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Samson]; The gaps (holes in the sides of the tomb) were once blocked with stones [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Samson]; The blocking was done so the tomb could be used as a shelter for sheep [SUPPORTED: https://en.wikipedia.org/wiki/Carreg_Samson]"}]'::jsonb),
    ('2b7bb7a9-4759-41bf-a703-8f4da42a1b5c'::uuid, 'card_description', 'In the Toquepala Caves, painted scenes show armed people corralling and killing a group of guanacos, rock art of gatherer-hunters inferred to have lived here about 10,000 years ago.', 'The caves have rock art of gatherer-hunters who are inferred to have lived in the caves about 10,000 years ago.', 'teaser-card-s017-rollback:2b7bb7a9-4759-41bf-a703-8f4da42a1b5c:card_description', 'rollback of teaser-card-s017: card_description ''The caves have rock art of gatherer-hunters who are inferred to have lived in the caves about 10,000 years ago.'' restored on Toquepala Caves', '9246f66f1adf7451ec501911203f87b41f0ddc50ed38317a251b9519ce237414|52c055f6290918531d147874b82c38b053fce3e28533ca1df427889bd7fcbcf3|52c055f6290918531d147874b82c38b053fce3e28533ca1df427889bd7fcbcf3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Toquepala Caves, painted scenes show armed people corralling and killing a group of guanacos, rock art of gatherer-hunters inferred to have lived here about 10,000 years ago."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Toquepala Caves have painted scenes (rock paintings) [S2, S6]; the scenes show armed people [S7]; the scene shows humans corralling and killing a group of guanacos [S8]; the paintings are rock art of gatherer-hunters [S5]; the gatherer-hunters are inferred (not certain) to have lived in the caves [S5]; they lived there about 10,000 years ago [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Toquepala Caves are caves in Peru (near Tacna, southeast Peru) [SUPPORTED: https://en.wikipedia.org/wiki/Toquepala_Caves]; The caves are notable for rock paintings (rock art) [SUPPORTED: https://en.wikipedia.org/wiki/Toquepala_Caves]; The painted scenes show armed people [SUPPORTED: https://en.wikipedia.org/wiki/Toquepala_Caves]; The painted scenes show people corralling a group of guanacos [SUPPORTED: https://en.wikipedia.org/wiki/Toquepala_Caves]; The painted scenes show the people killing the guanacos [SUPPORTED: https://en.wikipedia.org/wiki/Toquepala_Caves]; The rock art is of gatherer-hunters [SUPPORTED: https://en.wikipedia.org/wiki/Toquepala_Caves]; The gatherer-hunters are inferred (not directly known) to have lived in the caves about 10,000 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Toquepala_Caves]"}]'::jsonb),
    ('2bf713bc-9782-4f70-9a9f-4b93fd1d5b15'::uuid, 'card_description', 'A rock collapse sealed the entrance of Tito Bustillo Cave thousands of years ago, preserving tools and wall paintings found in 1968. The oldest shows human figures, around 33,000 years old.', 'A Paleolithic cave sealed by a collapsed entrance before 10,000 BC. The collapse preserved wall paintings, tools, and objects perfectly.', 'teaser-card-s017-rollback:2bf713bc-9782-4f70-9a9f-4b93fd1d5b15:card_description', 'rollback of teaser-card-s017: card_description ''A Paleolithic cave sealed by a collapsed entrance before 10,000 BC. The collapse preserved wall paintings, tools, and objects perfectly.'' restored on Tito Bustillo Cave', 'f2ac7fdd1af7191e99edecab0ad4c7e6d02568e7a97688ab04de30b764908d51|5857e807b3c156a635ac8791955bb4a94994a6ad35717c1aa3fe0f24f90e0323|5857e807b3c156a635ac8791955bb4a94994a6ad35717c1aa3fe0f24f90e0323', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A rock collapse sealed the entrance of Tito Bustillo Cave thousands of years ago, preserving tools and wall paintings found in 1968. The oldest shows human figures, around 33,000 years old."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "a rock collapse sealed the cave''s entrance [S3]; the entrance was sealed thousands of years ago [S3]; the sealing preserved tools and wall paintings [S3]; the tools and wall paintings were discovered in 1968 [S3]; the oldest of the paintings shows human figures [S6]; the oldest painting is around 33,000 years old [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tito Bustillo Cave is a prehistoric cave (rock shelter) with wall paintings in Ribadesella, Asturias, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Tito_Bustillo_Cave]; A rock collapse sealed the entrance of the cave thousands of years ago [SUPPORTED: https://en.wikipedia.org/wiki/Tito_Bustillo_Cave]; The sealing preserved tools and wall paintings in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Tito_Bustillo_Cave]; The tools and wall paintings were found (discovered) in 1968 [SUPPORTED: https://en.wikipedia.org/wiki/Tito_Bustillo_Cave]; The oldest of the cave paintings shows human figures [SUPPORTED: https://en.wikipedia.org/wiki/Tito_Bustillo_Cave]; The oldest painting is around 33,000 years old [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Tito_Bustillo_Cave]"}]'::jsonb),
    ('2c0b2769-f00d-418a-853b-f1bd62f245cb'::uuid, 'card_description', 'At Nemea, an ancient sanctuary of Zeus in the Peloponnese, games were documented from 573 BC, or earlier. Digs since 1973 unearthed a great open-air altar, baths and lodgings for visitors.', 'Home of the Nemean Games, one of the four great Panhellenic athletic festivals. Here, legend says Heracles slew the invulnerable Nemean Lion.', 'teaser-card-s017-rollback:2c0b2769-f00d-418a-853b-f1bd62f245cb:card_description', 'rollback of teaser-card-s017: card_description ''Home of the Nemean Games, one of the four great Panhellenic athletic festivals. Here, legend says Heracles slew the invulnerable Nemean Lion.'' restored on Nemea', 'b6a20f4bedc6b1bf5de73d00b7dd3bc0eb08e2b4548d6adaad4c26bf55d96e7d|426a66ec7e1aaa284e38cfa151d2886b3d5c67c63ad6e789f2d687b0a5e2e471|426a66ec7e1aaa284e38cfa151d2886b3d5c67c63ad6e789f2d687b0a5e2e471', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Nemea, an ancient sanctuary of Zeus in the Peloponnese, games were documented from 573 BC, or earlier. Digs since 1973 unearthed a great open-air altar, baths and lodgings for visitors."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Nemea is an ancient sanctuary [S1]; it is a sanctuary of Zeus [S3]; it is in the Peloponnese [S1]; games were documented there from 573 BC, or earlier [S3]; excavations have been carried out since 1973 [S6]; a great open-air altar was unearthed [S6]; baths were unearthed [S6]; lodgings (ancient accommodation) for visitors were unearthed [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Nemea is an ancient sanctuary (the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Nemea]; The sanctuary is in the Peloponnese (Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Nemea]; The sanctuary at Nemea was a sanctuary of Zeus [SUPPORTED: https://en.wikipedia.org/wiki/Nemea]; Games were held at Nemea (the Nemean Games, one of the four Panhellenic games) [SUPPORTED: https://en.wikipedia.org/wiki/Nemea]; The games are documented from 573 BC [SUPPORTED: https://en.wikipedia.org/wiki/Nemea]; The games may be documented from earlier than 573 BC (''or earlier'') [SUPPORTED: https://en.wikipedia.org/wiki/Nemean_Games]; Excavations (digs) at the site have been carried out since 1973 [SUPPORTED: https://en.wikipedia.org/wiki/Nemea]; The digs unearthed a great open-air altar [SUPPORTED: https://en.wikipedia.org/wiki/Nemea]; The digs unearthed baths [SUPPORTED: https://en.wikipedia.org/wiki/Nemea]; The digs unearthed lodgings (accommodation) for visitors [SUPPORTED: https://en.wikipedia.org/wiki/Nemea]"}]'::jsonb),
    ('2c780872-8603-4ff7-b740-147b3cd5f22f'::uuid, 'card_description', 'In Axum, King Ezana''s Stele stands 21 m tall amid hundreds of smaller stelae, a false door at its base and window-like apertures on all sides. It is likely the last of its kind.', 'A 21-metre 4th-century obelisk in the ancient city of Axum. Decorated with a false door at its base and window-like carvings on all sides.', 'teaser-card-s017-rollback:2c780872-8603-4ff7-b740-147b3cd5f22f:card_description', 'rollback of teaser-card-s017: card_description ''A 21-metre 4th-century obelisk in the ancient city of Axum. Decorated with a false door at its base and window-like carvings on all sides.'' restored on King Ezana''s Stele', '6af04754f4142c294b24927d72efa26008ff3472800213a49486ee47199d2b5a|baa65923796be0e3d2ecc5da1cc3f5fe1a466189d2004f5a64f69c3721ec1520|baa65923796be0e3d2ecc5da1cc3f5fe1a466189d2004f5a64f69c3721ec1520', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Axum, King Ezana''s Stele stands 21 m tall amid hundreds of smaller stelae, a false door at its base and window-like apertures on all sides. It is likely the last of its kind."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the stele is in Axum [S1]; it stands 21 m tall [S4]; it stands amid hundreds of smaller stelae [S2]; it has a false door at its base [S5]; it has window-like apertures on all sides [S5]; it is likely the last of its kind (last erected / last example of the practice; hedged) [S3, S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "King Ezana''s Stele is a stele (obelisk) in Axum, Ethiopia - the central claim: a monument in the ancient city of Axum [SUPPORTED: https://en.wikipedia.org/wiki/King_Ezana%27s_Stele]; The stele stands 21 m tall [SUPPORTED: https://en.wikipedia.org/wiki/King_Ezana%27s_Stele]; It stands amid hundreds of smaller stelae [SUPPORTED: https://en.wikipedia.org/wiki/King_Ezana%27s_Stele]; It has a false door at its base [SUPPORTED: https://en.wikipedia.org/wiki/King_Ezana%27s_Stele]; It has window-like apertures on all sides [SUPPORTED: https://en.wikipedia.org/wiki/King_Ezana%27s_Stele]; It is likely the last of its kind (the last such stele erected) [SUPPORTED: https://en.wikipedia.org/wiki/King_Ezana%27s_Stele]"}]'::jsonb),
    ('2cbc1c11-5750-4b96-973b-7f1f8c847003'::uuid, 'card_description', 'Makers of grooved ware once lived at Skara Brae on the Bay of Skaill, in stone houses laid out alike: a central hearth, beds on either side and a dresser opposite the entrance.', 'The site was occupied from roughly 3180 BC to around 2500 BC and is Europe''s most complete Neolithic village.', 'teaser-card-s017-rollback:2cbc1c11-5750-4b96-973b-7f1f8c847003:card_description', 'rollback of teaser-card-s017: card_description "The site was occupied from roughly 3180 BC to around 2500 BC and is Europe''s most complete Neolithic village." restored on Skara Brae', '21ec893b05f856c60ae1ecffa175f42d4e6cdb3c8639a90f527c71d4c3c7e78d|fa71aaf0fa977e85fa4a4146adad7066ecfd2d622ff8e85d9b54bb2a2a1f8884|fa71aaf0fa977e85fa4a4146adad7066ecfd2d622ff8e85d9b54bb2a2a1f8884', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Makers of grooved ware once lived at Skara Brae on the Bay of Skaill, in stone houses laid out alike: a central hearth, beds on either side and a dresser opposite the entrance."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the inhabitants of Skara Brae made (and used) grooved ware [S5]; people once lived at Skara Brae (it was occupied) [S3]; Skara Brae lies on the Bay of Skaill [S1]; the buildings are of stone [S1]; the buildings follow a similar layout [S6]; each has a central hearth [S6]; beds lie on either side of the hearth [S6]; a dresser stands opposite the entrance [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Skara Brae is a settlement (stone-built Neolithic) - the central claim: a settlement [SUPPORTED: https://en.wikipedia.org/wiki/Skara_Brae]; Skara Brae lies on the Bay of Skaill [SUPPORTED: https://en.wikipedia.org/wiki/Skara_Brae]; Its inhabitants were makers of grooved ware (a style of pottery) [SUPPORTED: https://en.wikipedia.org/wiki/Skara_Brae]; People once lived there (the settlement was occupied and later abandoned) [SUPPORTED: https://en.wikipedia.org/wiki/Skara_Brae]; The dwellings were stone houses [SUPPORTED: https://en.wikipedia.org/wiki/Skara_Brae]; The houses are laid out alike (similar layout) [SUPPORTED: https://en.wikipedia.org/wiki/Skara_Brae]; Each house has a central hearth [SUPPORTED: https://en.wikipedia.org/wiki/Skara_Brae]; Each house has beds on either side of the hearth [SUPPORTED: https://en.wikipedia.org/wiki/Skara_Brae]; Each house has a dresser opposite the entrance [SUPPORTED: https://en.wikipedia.org/wiki/Skara_Brae]"}]'::jsonb),
    ('2cce98a2-9851-42c7-9e9e-47f39b12be9c'::uuid, 'card_description', 'At 279 m, Lewesdon Hill is the highest point in Dorset. An Armada Beacon stood here in 1588, and parts of a possible bank and ditch remain, though its status as a hillfort is disputed.', 'At 279 metres, the hillfort crowns the highest point in Dorset. Its original bank and ditch survive despite centuries of activity on the summit.', 'teaser-card-s017-rollback:2cce98a2-9851-42c7-9e9e-47f39b12be9c:card_description', 'rollback of teaser-card-s017: card_description ''At 279 metres, the hillfort crowns the highest point in Dorset. Its original bank and ditch survive despite centuries of activity on the summit.'' restored on Lewesdon Hill', '0a9a378100c77caa92e7e6a6d92981adc97d92a44b771239ac1cdc0c925716a9|3d4ff3b69bbdb21d7d5e6225dfdc83d08216e93e779c4567ba90188c4c33c98d|3d4ff3b69bbdb21d7d5e6225dfdc83d08216e93e779c4567ba90188c4c33c98d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At 279 m, Lewesdon Hill is the highest point in Dorset. An Armada Beacon stood here in 1588, and parts of a possible bank and ditch remain, though its status as a hillfort is disputed."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Lewesdon Hill has a maximum elevation of 279 m [S2]; it is the highest point in Dorset [S2]; it was the site of an Armada Beacon [S5]; the beacon dates to 1588 [S5]; parts of a possible bank and ditch are still visible [S4]; its status as a hillfort is disputed [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Lewesdon Hill is a hill in west Dorset, England - the central claim: a hill (with a disputed hillfort) in Dorset [SUPPORTED: https://en.wikipedia.org/wiki/Lewesdon_Hill]; Lewesdon Hill is 279 m high [SUPPORTED: https://en.wikipedia.org/wiki/Lewesdon_Hill]; It is the highest point in Dorset [SUPPORTED: https://en.wikipedia.org/wiki/Lewesdon_Hill]; An Armada Beacon stood on Lewesdon in 1588 [SUPPORTED: https://en.wikipedia.org/wiki/Lewesdon_Hill]; Parts of a possible bank and ditch remain [SUPPORTED: https://en.wikipedia.org/wiki/Lewesdon_Hill]; Its status as a hillfort is disputed [SUPPORTED: https://en.wikipedia.org/wiki/Lewesdon_Hill]"}]'::jsonb),
    ('2cd65076-e10c-401f-a997-296f99badf9c'::uuid, 'card_description', 'On the summit of Bredon Hill lie the earthworks of Kemerton Camp, an Iron Age hill fort believed abandoned after a considerable battle, beside the great Banbury Stone.', 'The summit of this hill bears the remains of Kemerton Camp, an Iron Age hillfort. A mutilation burial of 50 men found near the entrance suggests a violent end.', 'teaser-card-s017-rollback:2cd65076-e10c-401f-a997-296f99badf9c:card_description', 'rollback of teaser-card-s017: card_description ''The summit of this hill bears the remains of Kemerton Camp, an Iron Age hillfort. A mutilation burial of 50 men found near the entrance suggests a violent end.'' restored on Bredon Hill', '8112f3259b2eed2ec805959986ff4050703074e0181e1d23aac3ee9b7016be99|f735a90eaf5a46df185ba39344debd3b24df8acf9dd0fdd9fda5405e8cef673e|f735a90eaf5a46df185ba39344debd3b24df8acf9dd0fdd9fda5405e8cef673e', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the summit of Bredon Hill lie the earthworks of Kemerton Camp, an Iron Age hill fort believed abandoned after a considerable battle, beside the great Banbury Stone."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "earthworks of Kemerton Camp lie at the summit of Bredon Hill [S2]; Kemerton Camp is an Iron Age hill fort [S2]; it is believed (not certain) to have been abandoned after a considerable battle [S2]; the Banbury Stone is a large stone at the summit [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Bredon Hill has a hill fort on its summit - the central claim: a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Bredon_Hill]; Earthworks of the camp lie on the summit of Bredon Hill [SUPPORTED: https://en.wikipedia.org/wiki/Bredon_Hill]; The hill fort is called Kemerton Camp and dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Bredon_Hill]; Kemerton Camp is believed to have been abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Bredon_Hill]; It was abandoned after a considerable battle [SUPPORTED: https://en.wikipedia.org/wiki/Bredon_Hill]; A large stone called the Banbury Stone lies at the summit of Bredon Hill, where the camp is [SUPPORTED: https://en.wikipedia.org/wiki/Bredon_Hill]"}]'::jsonb),
    ('2ce50a62-f812-4204-bbb6-892a581fee52'::uuid, 'card_description', 'Archaeologists reckon the Amelungsburg on the Süntel ridge took up to six weeks to build in the pre-Roman Iron Age, its rampart hiding a dry stone wall about 3 metres wide.', 'A Celtic ringfort from 300-100 BC. The circular double-rampart design was typical of La Tène culture fortifications across central Europe.', 'teaser-card-s017-rollback:2ce50a62-f812-4204-bbb6-892a581fee52:card_description', 'rollback of teaser-card-s017: card_description ''A Celtic ringfort from 300-100 BC. The circular double-rampart design was typical of La Tène culture fortifications across central Europe.'' restored on Amelungsburg, Süntel', 'edb76197b09456f9f30882b4aa8a07751dfc7a77298df6b5ef7612b86a578bf9|395f544ef51b8df92bac6bfdf2273cb911ec08c3d4bdded92094c9cb592e91d8|395f544ef51b8df92bac6bfdf2273cb911ec08c3d4bdded92094c9cb592e91d8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Archaeologists reckon the Amelungsburg on the Süntel ridge took up to six weeks to build in the pre-Roman Iron Age, its rampart hiding a dry stone wall about 3 metres wide."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "archaeologists reckon a construction time of up to six weeks [S6]; the Amelungsburg lies on the Süntel ridge [S1]; it was originally built in the pre-Roman Iron Age [S6]; the fortification has a rampart (embankment) [S3, S5]; a dry stone wall lay inside the embankment [S5]; the dry stone wall is about 3 metres wide [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Amelungsburg is a ramparted hillfort (former ringfort) on the Süntel ridge, Germany - the central claim: a fortification [SUPPORTED: https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)]; It was built in the pre-Roman Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)]; Construction time of up to six weeks [SUPPORTED: https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)]; The six-week build time is what archaeologists reckon (an estimate) [SUPPORTED: https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)]; The rampart contains a dry stone wall [SUPPORTED: https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)]; The dry stone wall is about 3 metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)]; The wall was hidden inside the rampart (lay within the embankment) [SUPPORTED: https://en.wikipedia.org/wiki/Amelungsburg_(S%C3%BCntel)]"}]'::jsonb),
    ('2cea8e97-21f2-4d79-95f3-c00ef69985eb'::uuid, 'card_description', 'A curvilinear La Tène style design covers the top half of the Turoe Stone in County Galway, probably from about 100 BC to AD 100. Its religious or ceremonial purposes are lost in time.', 'A decorated granite stone from ~100 BC covered in swirling La Tene-style Celtic patterns. The top half is carved; the bottom half was left rough, meant to be buried in the earth.', 'teaser-card-s017-rollback:2cea8e97-21f2-4d79-95f3-c00ef69985eb:card_description', 'rollback of teaser-card-s017: card_description ''A decorated granite stone from ~100 BC covered in swirling La Tene-style Celtic patterns. The top half is carved; the bottom half was left rough, meant to be buried in the earth.'' restored on Turoe Stone', '2ec0471b2584ea6181e7e7617cd753b1b3d564130b57b0a9b708730ff508bad6|429aaf27bcfb2f05579f0446d5c4d03a651647872ea921abb11e49bf8b9e35c1|429aaf27bcfb2f05579f0446d5c4d03a651647872ea921abb11e49bf8b9e35c1', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A curvilinear La Tène style design covers the top half of the Turoe Stone in County Galway, probably from about 100 BC to AD 100. Its religious or ceremonial purposes are lost in time."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "a curvilinear La Tène style design decorates the stone [S4]; the design covers the top half of the stone [S4]; the Turoe Stone is in County Galway [S1]; it probably dates from about 100 BC to AD 100 [S2]; its religious or ceremonial purposes are lost in time (unknown) [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Turoe Stone is a decorated granite standing stone (the kind of object) [SUPPORTED: https://en.wikipedia.org/wiki/Turoe_Stone]; The Turoe Stone is in County Galway, Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Turoe_Stone]; A design covers the top half of the stone [SUPPORTED: https://en.wikipedia.org/wiki/Turoe_Stone]; The design is curvilinear and in the La Tène style (Wikipedia) [SUPPORTED: https://en.wikipedia.org/wiki/Turoe_Stone]; The stone probably dates from about 100 BC to AD 100 [SUPPORTED: https://en.wikipedia.org/wiki/Turoe_Stone]; The stone''s religious or ceremonial purposes are lost in time (unknown) [SUPPORTED: https://en.wikipedia.org/wiki/Turoe_Stone]; The stone served religious or ceremonial purposes (a ritual stone) [SUPPORTED: https://en.wikipedia.org/wiki/Turoe_Stone]; The stone has La Tène style decoration (Iron Age, carved before 300 AD) [SUPPORTED: https://heritageireland.ie/unguided-sites/turoe-stone/]"}]'::jsonb),
    ('2dab79e8-1ece-4f9b-beb3-a91573d545c3'::uuid, 'card_description', 'On Rapa Nui, Ahu Akivi is a sacred place looking out toward the Pacific Ocean, where seven moai of equal size stand on the flank of Maunga Terevaka, built by the Rapa Nui people.', 'Ahu Akivi is part of the Ahu Akivi-Vai Teka complex which was built up by the Rapa Nui people in two phases.', 'teaser-card-s017-rollback:2dab79e8-1ece-4f9b-beb3-a91573d545c3:card_description', 'rollback of teaser-card-s017: card_description ''Ahu Akivi is part of the Ahu Akivi-Vai Teka complex which was built up by the Rapa Nui people in two phases.'' restored on Ahu Akivi', '6c8e6d0da19e870130d4d45a469f02fc6d0b004a69aa694e88817cbb25d5a217|3ab8fca5ede31c4025b992779bdcb500b250db25565eb454eed807e558f5ad39|3ab8fca5ede31c4025b992779bdcb500b250db25565eb454eed807e558f5ad39', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Rapa Nui, Ahu Akivi is a sacred place looking out toward the Pacific Ocean, where seven moai of equal size stand on the flank of Maunga Terevaka, built by the Rapa Nui people."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ahu Akivi is on Rapa Nui [S1]; it is a sacred place [S1]; it looks out toward the Pacific Ocean [S1]; there are seven moai [S5, S6]; the seven moai are of equal size [S5]; they stand on the flank of Maunga Terevaka [S2]; it was built by the Rapa Nui people [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ahu Akivi is a sacred place (the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Akivi]; Ahu Akivi is on Rapa Nui (Easter Island) [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Akivi]; It looks out toward the Pacific Ocean [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Akivi]; Seven moai stand at Ahu Akivi [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Akivi]; The seven moai are of equal size [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Akivi]; The moai are statues (of ancestors) at the site [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Akivi]; Ahu Akivi is located on the flank of Maunga Terevaka [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Akivi]; Ahu Akivi was built by the Rapa Nui people [SUPPORTED: https://en.wikipedia.org/wiki/Ahu_Akivi]"}]'::jsonb),
    ('2dceb336-e4a4-4a99-9f88-00c83aaa0088'::uuid, 'card_description', 'Rastrojón was built on a geological fault just two kilometres from Copán. When the Maya kingdom of Copán collapsed in 822, the site was abandoned, perhaps no longer worth the effort.', '5th–9th century Maya capital near Copán. Abandoned in 822 AD when the Copán kingdom collapsed — one of dozens of satellite cities that fell silent as the Classic Maya world unraveled.', 'teaser-card-s017-rollback:2dceb336-e4a4-4a99-9f88-00c83aaa0088:card_description', 'rollback of teaser-card-s017: card_description ''5th–9th century Maya capital near Copán. Abandoned in 822 AD when the Copán kingdom collapsed — one of dozens of satellite cities that fell silent as the Classic Maya world unraveled.'' restored on Rastrojón', '9e6d0676fceac5370dd016a7f446f3c02ed98a85515101e8ed3c5c5c29a53327|4aeaf3c0520ed70ad2ce757efc161a5bede22a9b01eccd78a14077a7f4c433c5|4aeaf3c0520ed70ad2ce757efc161a5bede22a9b01eccd78a14077a7f4c433c5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Rastrojón was built on a geological fault just two kilometres from Copán. When the Maya kingdom of Copán collapsed in 822, the site was abandoned, perhaps no longer worth the effort."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Rastrojón was built on a geological fault [S3]; it lies just two kilometres from Copán [S2]; Copán was the capital of a Maya kingdom [S2]; the Copán kingdom collapsed in 822 [S3]; the site was abandoned following that collapse [S3]; perhaps (it may be that) the inhabitants judged the location no longer worth the effort [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Rastrojón is a Maya archaeological site in western Honduras [SUPPORTED: https://en.wikipedia.org/wiki/Rastroj%C3%B3n]; Rastrojón lies just two kilometres from Copán [SUPPORTED: https://en.wikipedia.org/wiki/Rastroj%C3%B3n]; Rastrojón was built on a geological fault [SUPPORTED: https://en.wikipedia.org/wiki/Rastroj%C3%B3n]; Copán was the capital of a Maya kingdom [SUPPORTED: https://en.wikipedia.org/wiki/Rastroj%C3%B3n]; The Copán kingdom collapsed in 822 and Rastrojón was abandoned afterwards [SUPPORTED: https://en.wikipedia.org/wiki/Rastroj%C3%B3n]; The site was perhaps abandoned because the location was not worth the effort (a conjecture, not established) [SUPPORTED: https://en.wikipedia.org/wiki/Rastroj%C3%B3n]"}]'::jsonb),
    ('2e46252e-2205-4aed-92ee-38eeb5758399'::uuid, 'card_description', 'Domica Cave in Slovakia is well known for its complex structure and dense speleothems. Post holes from dwelling objects and fireplaces were discovered in several places of the cave.', 'Pottery from around 6000 BC found in this karst cave places it at the edge of the region''s earliest occupation. Underground, it links to the Baradla cave system across the border into Hungary.', 'teaser-card-s017-rollback:2e46252e-2205-4aed-92ee-38eeb5758399:card_description', 'rollback of teaser-card-s017: card_description "Pottery from around 6000 BC found in this karst cave places it at the edge of the region''s earliest occupation. Underground, it links to the Baradla cave system across the border into Hungary." restored on Domica Cave', 'b7c2d06bbf9118a77109006989e197c45339a0f62c02febb283664eb017a2071|7e85b4b1b291901379c63bc36175726c3bca1d768b9cbe80fbdd64f2efdf0b27|7e85b4b1b291901379c63bc36175726c3bca1d768b9cbe80fbdd64f2efdf0b27', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Domica Cave in Slovakia is well known for its complex structure and dense speleothems. Post holes from dwelling objects and fireplaces were discovered in several places of the cave."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Domica Cave is in Slovakia [S1]; it is well known for its complex structure [S2]; it has a high density of speleothems [S2]; post holes from dwelling objects were discovered in several places of the cave [S5]; fireplaces were discovered in several places of the cave [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Domica Cave is a karst cave [SUPPORTED: https://en.wikipedia.org/wiki/Domica_Cave]; Domica Cave is in Slovakia [SUPPORTED: https://en.wikipedia.org/wiki/Domica_Cave]; The cave is well known for its complex structure [SUPPORTED: https://en.wikipedia.org/wiki/Domica_Cave]; The cave is well known for its dense speleothems [SUPPORTED: https://en.wikipedia.org/wiki/Domica_Cave]; Post holes from dwelling objects were discovered in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Domica_Cave]; Fireplaces were discovered in several places of the cave [SUPPORTED: https://en.wikipedia.org/wiki/Domica_Cave]"}]'::jsonb),
    ('2e648c8e-56af-4349-8064-6372c29b3d25'::uuid, 'card_description', 'The Skorba Temples hold paving slabs with libation holes in an entrance passage and the torba floor of a three-apse temple, insight into the earliest periods of Malta''s Neolithic culture.', 'Megalithic temples from 3600 BC with torba cement floors and libation holes. These are among the oldest freestanding stone structures on Earth—older than the pyramids.', 'teaser-card-s017-rollback:2e648c8e-56af-4349-8064-6372c29b3d25:card_description', 'rollback of teaser-card-s017: card_description ''Megalithic temples from 3600 BC with torba cement floors and libation holes. These are among the oldest freestanding stone structures on Earth—older than the pyramids.'' restored on Skorba Temples', '69e54b17a250fdbbaa87ae6519647119f33df67f5eec184acaf12f5e2202ddec|176c56388328bcb4cb4a9e70a29da641d4d6806d8b704848691e1434fa89ae94|176c56388328bcb4cb4a9e70a29da641d4d6806d8b704848691e1434fa89ae94', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Skorba Temples hold paving slabs with libation holes in an entrance passage and the torba floor of a three-apse temple, insight into the earliest periods of Malta''s Neolithic culture."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site has paving slabs with libation holes in an entrance passage [S4]; the site has the torba floor of a three-apse temple [S4]; the temples have given insight into the earliest periods of Malta''s Neolithic culture [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Skorba Temples are megalithic (Neolithic) temple remains at Żebbiegħ in Malta [SUPPORTED: https://en.wikipedia.org/wiki/Skorba_Temples]; The site holds paving slabs with libation holes in an entrance passage [SUPPORTED: https://en.wikipedia.org/wiki/Skorba_Temples]; The site holds the torba floor of a three-apse temple [SUPPORTED: https://en.wikipedia.org/wiki/Skorba_Temples]; The site gives insight into the earliest periods of Malta''s Neolithic culture [SUPPORTED: https://en.wikipedia.org/wiki/Skorba_Temples]"}]'::jsonb),
    ('2f217cc8-9aad-4f87-93fb-c8732fe85e39'::uuid, 'card_description', 'Portus Lemanis, a Roman Saxon Shore fort, stood on a hill over a reach of sea since drained to form Romney Marsh. Its southern side is wholly missing, its remains moved at various angles.', 'A Roman Saxon Shore fort whose ruins are known locally as Stutfall Castle. The sea it once defended against has retreated, replaced by the drained marshland of Romney Marsh.', 'teaser-card-s017-rollback:2f217cc8-9aad-4f87-93fb-c8732fe85e39:card_description', 'rollback of teaser-card-s017: card_description ''A Roman Saxon Shore fort whose ruins are known locally as Stutfall Castle. The sea it once defended against has retreated, replaced by the drained marshland of Romney Marsh.'' restored on Portus Lemanis', 'baa862bc39b1d2c14a04d647fd50bb845793ce59d455379776ae44212394e4fa|dc086bbfdfc2ca4fd24ad696734dfc65a1d7f6f039c4dd4b589225f578deda9d|dc086bbfdfc2ca4fd24ad696734dfc65a1d7f6f039c4dd4b589225f578deda9d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Portus Lemanis, a Roman Saxon Shore fort, stood on a hill over a reach of sea since drained to form Romney Marsh. Its southern side is wholly missing, its remains moved at various angles."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Portus Lemanis is a Roman fort [S1]; it is a Saxon Shore fort [S1]; the fort stood on a hill [S5]; the hill overlooked a reach of sea [S5]; that reach of sea has since been drained to form Romney Marsh [S5]; the fort''s southern side is wholly missing [S7]; the remains have been moved at various angles [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Portus Lemanis was a Roman fort (with a settlement and port) [SUPPORTED: https://en.wikipedia.org/wiki/Portus_Lemanis]; The fort was a Saxon Shore fort, part of the Saxon Shore defence system [SUPPORTED: https://en.wikipedia.org/wiki/Portus_Lemanis]; The site is in southern Kent, England [SUPPORTED: https://en.wikipedia.org/wiki/Portus_Lemanis]; The fort stood on a hill [SUPPORTED: https://en.wikipedia.org/wiki/Portus_Lemanis]; The hill overlooked a reach of sea [SUPPORTED: https://en.wikipedia.org/wiki/Portus_Lemanis]; That reach of sea has since been drained to form Romney Marsh [SUPPORTED: https://en.wikipedia.org/wiki/Portus_Lemanis]; The southern side of the fort is wholly missing [SUPPORTED: https://en.wikipedia.org/wiki/Portus_Lemanis]; Elsewhere the remains have been moved at various angles [SUPPORTED: https://en.wikipedia.org/wiki/Portus_Lemanis]"}]'::jsonb),
    ('2f44fbd5-7420-4904-8ef9-3bb2c7a15064'::uuid, 'card_description', 'Statues locals call Palindo and Tarae Roe show faces with brow and nose as one and no mouth: the Bada Valley Megaliths, where lidded burial jars 1.5-2 meters in diameter were found.', 'Around 3000 BC, hundreds of mysterious stone megaliths were erected in the Lore Lindu highlands. Purpose and builders remain unknown. First recorded by Western observers in 1908 — still no answers.', 'teaser-card-s017-rollback:2f44fbd5-7420-4904-8ef9-3bb2c7a15064:card_description', 'rollback of teaser-card-s017: card_description ''Around 3000 BC, hundreds of mysterious stone megaliths were erected in the Lore Lindu highlands. Purpose and builders remain unknown. First recorded by Western observers in 1908 — still no answers.'' restored on Bada Valley Megaliths', 'bc0f5408baa337b8e9cf5b77a97f0b04fea408fb3242281fe2b8aa9ebbbd9e1d|a92c63cd1bd61e4e1cca353d0ae6e58bb9b16730528ee0155630d867758a95dc|a92c63cd1bd61e4e1cca353d0ae6e58bb9b16730528ee0155630d867758a95dc', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Statues locals call Palindo and Tarae Roe show faces with brow and nose as one and no mouth: the Bada Valley Megaliths, where lidded burial jars 1.5-2 meters in diameter were found."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "locals call statues in the Bada Valley Palindo [S1]; locals call statues in the Bada Valley Tarae Roe [S1]; the statues show faces with brow and nose depicted as one [S2]; the statues'' faces have no mouth [S2]; the statues are in the Bada Valley [S1, S2]; jars with lids were found in the Bada Valley [S6]; the jars were used for burial [S6]; the jars are 1.5-2 meters in diameter [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Bada Valley Megaliths are a site of megaliths (hundreds of them) in the Bada Valley [SUPPORTED: https://en.wikipedia.org/wiki/Bada_Valley]; The site is in Central Sulawesi, Indonesia [SUPPORTED: https://en.wikipedia.org/wiki/Bada_Valley]; Locals call statues of the Bada Valley Palindo [SUPPORTED: https://en.wikipedia.org/wiki/Bada_Valley]; Locals call statues of the Bada Valley Tarae Roe [SUPPORTED: https://en.wikipedia.org/wiki/Bada_Valley]; The statues show stylized human faces [SUPPORTED: https://en.wikipedia.org/wiki/Bada_Valley]; On the faces the brow (eyebrows) and nose are depicted as one [SUPPORTED: https://en.wikipedia.org/wiki/Bada_Valley]; The faces have no mouth [SUPPORTED: https://en.wikipedia.org/wiki/Bada_Valley]; Large jars with lids (kalamba) used for burial were found in the Bada Valley [SUPPORTED: https://en.wikipedia.org/wiki/Bada_Valley]; The lidded burial jars are 1.5-2 meters in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Bada_Valley]"}]'::jsonb),
    ('2fe3e1da-dcae-4014-a4d9-8b3132952546'::uuid, 'card_description', 'On a hill northeast of Pitumarka, at the southern shore of the river Ch''illkamayu, Machu Pitumarka is a site of ruined walls in Canchis Province, in Peru''s Cusco Region.', 'An archaeological site with wall ruins perched on a hill above a river. Settlements like this across the high Andes demonstrate how pre-Inca peoples fortified natural terrain.', 'teaser-card-s017-rollback:2fe3e1da-dcae-4014-a4d9-8b3132952546:card_description', 'rollback of teaser-card-s017: card_description ''An archaeological site with wall ruins perched on a hill above a river. Settlements like this across the high Andes demonstrate how pre-Inca peoples fortified natural terrain.'' restored on Machu Pitumarka', 'c8d3e84054998d973586891e0296717848c361f088d10b7233bb3c433d426ecc|8fd4e251dc0e8e4c3c7701b8bdf652e9a9e9bbdd999b35cae840a4b1ba643cd7|8fd4e251dc0e8e4c3c7701b8bdf652e9a9e9bbdd999b35cae840a4b1ba643cd7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite2-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a hill northeast of Pitumarka, at the southern shore of the river Ch''illkamayu, Machu Pitumarka is a site of ruined walls in Canchis Province, in Peru''s Cusco Region."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies on a hill [S3]; the hill is northeast of Pitumarka [S3]; it is at the southern shore of the river Ch''illkamayu [S3]; Machu Pitumarka is a site of ruined walls [S1]; it is in Canchis Province [S2]; it is in Peru [S1]; it is in the Cusco Region [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Machu Pitumarka is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Pitumarka]; The site consists of ruins of walls [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Pitumarka]; The site is in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Pitumarka]; It is in Peru''s Cusco Region [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Pitumarka]; It is in Canchis Province [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Pitumarka]; It lies on a hill [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Pitumarka]; The hill is northeast of Pitumarka [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Pitumarka]; It lies at the southern shore of the river Ch''illkamayu [SUPPORTED: https://en.wikipedia.org/wiki/Machu_Pitumarka]"}]'::jsonb),
    ('316b3d27-1295-41ce-a5c0-3b9c8251647e'::uuid, 'card_description', 'In 2002 a Tunghai University student, Chen Sheng-ming, found Huilai Monument Archaeology Park in Taichung. Investigation revealed a site of 1,500,000 m2, now a City Archaeological Area.', 'Covering 1.5 square kilometres in Xitun District, this Neolithic site has settlement layers from the 2nd millennium BC. A Tunghai University student uncovered it during fieldwork in 2002.', 'teaser-card-s017-rollback:316b3d27-1295-41ce-a5c0-3b9c8251647e:card_description', 'rollback of teaser-card-s017: card_description ''Covering 1.5 square kilometres in Xitun District, this Neolithic site has settlement layers from the 2nd millennium BC. A Tunghai University student uncovered it during fieldwork in 2002.'' restored on Huilai Monument Archaeology Park', '6904f2c32524c4b700f04441e405bae1b1036558b7eea4b56b003c9bd2d4007a|3fdbdcb1070eac58edff49577cd9168d5b17263101da3efdc9ec6408092fa63a|3fdbdcb1070eac58edff49577cd9168d5b17263101da3efdc9ec6408092fa63a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 2002 a Tunghai University student, Chen Sheng-ming, found Huilai Monument Archaeology Park in Taichung. Investigation revealed a site of 1,500,000 m2, now a City Archaeological Area."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site was found in 2002 [S2]; it was found by a Tunghai University student [S2]; the student is named Chen Sheng-ming [S2]; the site is in Taichung [S1]; further investigation revealed the site to cover 1,500,000 m2 [S3]; the area is now a City Archaeological Area [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-019 (verify), VERIFIED", "url": "output/remediation/tease