    ('353f7688-f230-41ef-a181-8bd9341448cf'::uuid, 'card_description', 'On the highest point of Bodmin Moor, 1,378 feet up, the summit pile of the Brown Willy Cairns has never been excavated. Folklore suggests an ancient Cornish king may lie entombed underneath.', 'Bronze Age cairns sit atop the highest point of Bodmin Moor at 420 metres. The hill shifts from a conical peak to a multi-peaked crest depending on the vantage point.', 'teaser-card-s017-rollback:353f7688-f230-41ef-a181-8bd9341448cf:card_description', 'rollback of teaser-card-s017: card_description ''Bronze Age cairns sit atop the highest point of Bodmin Moor at 420 metres. The hill shifts from a conical peak to a multi-peaked crest depending on the vantage point.'' restored on Brown Willy Cairns', 'ff46e9b06dadeeb9e6b2b4deaf4a839e872f5c79cb02efa151379f4489d46c90|1f12d838cb8a7a97b9bea26bb324c768c8e8634858c7be39c6f742efecde645d|1f12d838cb8a7a97b9bea26bb324c768c8e8634858c7be39c6f742efecde645d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the highest point of Bodmin Moor, 1,378 feet up, the summit pile of the Brown Willy Cairns has never been excavated. Folklore suggests an ancient Cornish king may lie entombed underneath."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is on the highest point of Bodmin Moor [S1]; the summit is 1,378 feet up [S1]; the summit cairn is a man-made pile of rock [S2]; the summit cairn has never been excavated [S3]; folklore suggests an ancient Cornish king may lie entombed underneath [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Brown Willy Cairns are man-made rock piles (cairns) on the summit of Brown Willy [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Willy]; The summit pile (Brown Willy Summit Cairn) is a man-made rock pile [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Willy]; The summit of Brown Willy is the highest point of Bodmin Moor [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Willy]; The summit is 1,378 feet up [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Willy]; The summit cairn has never been excavated [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Willy]; Folklore suggests an ancient Cornish king may lie entombed underneath [SUPPORTED: https://en.wikipedia.org/wiki/Brown_Willy]"}]'::jsonb),
    ('35fedad2-8a41-4fd4-8327-86fd30853551'::uuid, 'card_description', 'On a hill above the River Severn, the Iron Age hillfort of Cefn Carnedd runs about 437 metres, triple banks and ditches on its north-west side. Aerial photos show traces of an earlier fort.', 'Iron Age hillfort commanding the River Severn confluence at Caersws, orientated northeast-southwest along the hill''s spine at 437 metres long. Its ramparts enclose around 6 hectares.', 'teaser-card-s017-rollback:35fedad2-8a41-4fd4-8327-86fd30853551:card_description', 'rollback of teaser-card-s017: card_description "Iron Age hillfort commanding the River Severn confluence at Caersws, orientated northeast-southwest along the hill''s spine at 437 metres long. Its ramparts enclose around 6 hectares." restored on Cefn Carnedd', '09e84eb4f2af21bbb07bfd7c9238c0864414e99316609aa8a3a4b7c702c38a69|18aaf66ae4f54cf499a40fdaccd27f2c5b7dd9ba016f8739051f07e72dcc4cce|18aaf66ae4f54cf499a40fdaccd27f2c5b7dd9ba016f8739051f07e72dcc4cce', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a hill above the River Severn, the Iron Age hillfort of Cefn Carnedd runs about 437 metres, triple banks and ditches on its north-west side. Aerial photos show traces of an earlier fort."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cefn Carnedd is on a hill above the River Severn [S3]; it is an Iron Age hillfort [S1]; the fort runs about 437 metres [S4]; there are triple banks and ditches on its north-west side [S5]; aerial photographs show traces of an earlier fort [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cefn Carnedd is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Cefn_Carnedd]; It stands on a hill above the River Severn [SUPPORTED: https://en.wikipedia.org/wiki/Cefn_Carnedd]; The fort runs about 437 metres [SUPPORTED: https://en.wikipedia.org/wiki/Cefn_Carnedd]; It has triple banks and ditches on its north-west side [SUPPORTED: https://en.wikipedia.org/wiki/Cefn_Carnedd]; Aerial photos show traces of an earlier fort [SUPPORTED: https://en.wikipedia.org/wiki/Cefn_Carnedd]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s017-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s017-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s017-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('00d1c243-0301-4212-a7dd-27a82bdc3fa0'::uuid, 'card_description', 'Into the lake of Llyn Fawr, in a glacial cirque, went two bronze cauldrons and axeheads, part of a hoard of weapons and tools that appears to have been placed as votive offerings.'), ('019573c7-aff6-4aab-848e-99063cc00b09'::uuid, 'card_description', 'On a hillside promontory above a tributary of the River Yeo, near Bratton Fleming in Devon, Smythapark holds an Iron Age hill fort, in a landscape rich in small enclosures.'), ('0294d74b-0e97-4509-913a-475e3c21e1a7'::uuid, 'card_description', 'In a private garden in Żurrieq stands a 5.6 m-high tower of limestone blocks laid without mortar, crowned by an Egyptian-inspired cornice. The Punic Building''s age and purpose are not known.'), ('0312b756-2f79-4b8e-bcef-d00885080bca'::uuid, 'card_description', 'Begun on 23 August 237 BC on the west bank of the Nile, the Temple of Horus at Edfu still keeps a naos of Nectanebo II in its inner sanctuary, a relic from an earlier building.'), ('035aa343-1776-4667-8162-4f295287f6cc'::uuid, 'card_description', 'Tradition says an Indian monk founded Lingyin Temple, the Temple of the Soul''s Retreat near Hangzhou, in 328 AD. At its peak it boasted 72 halls and more than 3000 monks.'), ('0371ed0a-82f5-4578-b7bf-10dc40faf580'::uuid, 'card_description', 'Baalbek''s colossal Imperial Roman structures became a World Heritage Site in 1984. At the Temple of Jupiter, a deep trench pushed Tell Baalbek''s settlement back to the PPNB Neolithic.'), ('05d60350-c231-4179-851b-380505d30a87'::uuid, 'card_description', 'On the summit of a steep hill in east Penzance, a single rampart encloses 3 acres: Lescudjack Hill Fort, an Iron Age settlement traditionally called a castle, which named the road beside it.'), ('06a73089-340c-40ac-9979-4a5c08f93da5'::uuid, 'card_description', 'Within the Iron Age earthworks of Cissbury Ring lies a Neolithic flint mine: around 270 shafts, up to 12 metres deep, dug with antler picks over around 300 years of use.'), ('07ca1c0c-550e-41ab-ab5d-5563fce29d90'::uuid, 'card_description', 'Older than the pyramids of Egypt, the Ġgantija temples stand at the edge of the Xagħra plateau: two Neolithic temples, the southerly one dating to around 3600 BC, and an incomplete third.'), ('08122cd2-522f-4ebc-b363-aabc7bd60de3'::uuid, 'card_description', 'The Ringlemere gold cup was found at Ringlemere Barrow near Sandwich, a mound now ploughed away that once stood as high as 5m, yet no burials of its own time have been found there.'), ('08508ff0-053d-4b8e-b2a3-6382818c6735'::uuid, 'card_description', 'Known anciently as Ake, and nearby as Usiij Witz, Vulture Hill, the Maya site of Bonampak in Chiapas rose in the Late Classic period as a dependency of the larger Yaxchilan.'), ('0989a7d5-9fa2-447d-a774-5f5b8351fd27'::uuid, 'card_description', 'Around 100 pairs of standing stones once lined Kennet Avenue for 2.5 km between Avebury and The Sanctuary. Today 27 upright stones remain, and concrete pillars mark where others stood.'), ('0a36e25e-4aaa-431f-bcde-843fc01353a1'::uuid, 'card_description', 'On the Vía de la Plata, the Roman Bridge of Salamanca crosses the Tormes River, its stretch toward the city still mostly original Roman work. Its exact date of construction is unknown.'), ('0ac27bb1-9767-4302-bcfc-0480349aaf1b'::uuid, 'card_description', 'In Phoenix Park near Dublin, a water-worn capstone thought to come from the River Liffey crowns Knockmaree Dolmen, a Neolithic cist found in 1838 when workmen removed its mound.'), ('0ae727b3-6355-47ad-9c47-2c5f01a3bc20'::uuid, 'card_description', 'Early in August 2006, an excavation in Praileaitz Cave, the Rock of the Monk cave, found paleolithic paintings of red dots, surmised to be from around 15,500 years ago.'), ('0beaf7bd-7e6d-44f2-8f4f-7c3050b5d2b4'::uuid, 'card_description', 'Two colossi 18 meters high still guard the Mortuary Temple of Amenhotep III, once the largest funerary complex in Thebes, largely ruined by an earthquake around 1200 BC.'), ('0c879c8d-da82-4297-be35-796650ca0765'::uuid, 'card_description', 'Across the plateau of Mynydd Illtud the Roman road Sarn Helen can still be traced, while on the grassy mound of Twyn y Gaer an Iron Age hillfort overlooks the valley of the River Usk.'), ('0e0531f8-6b94-43ab-b6db-81611a30e297'::uuid, 'card_description', 'Boulders set in a double arc, its ends pointing to the cardinal points: the Carisbrook Stone Arrangement in Victoria, an Aboriginal site some consider a male initiation ground.'), ('0e368bbc-87e1-42e4-b521-62b036c9be03'::uuid, 'card_description', 'Atop Conwy Mountain, Castell Caer Seion hides a smaller, more heavily defended fort inside the main one, with no obvious way between the two. Around 50 roundhouses stood in the larger fort.'), ('0e4e4bfd-6702-4adc-b6be-c2e47764cfef'::uuid, 'card_description', 'In Cheddar Gorge, Gough''s Cave held human skulls carefully shaped with stone tools into skull cups, and Cheddar Man, Britain''s oldest complete human skeleton, found here in 1903.'), ('0ed79845-f651-4c52-85cd-7f96bab43d4e'::uuid, 'card_description', 'Four tall slabs, 1.8 to 3 meters high, run east and west: Eightercua Stone Row, thought to date from around 1700 BC and by tradition the burial place of Scéine, wife of Amergin mac Míled.'), ('0ed9dd74-23c1-45e4-9d4e-8b80dfe46b0c'::uuid, 'card_description', 'In Lymington, the Iron Age hill fort of Buckland Rings has been excavated only once, in 1935: at its east entrance lay a long passage and the postholes of a pair of stout gateposts.'), ('10f42fef-61bd-46a1-b2e7-f35e0c84f9b4'::uuid, 'card_description', 'In the sanctuary of Apollo at Delphi, the Sicyonian Treasury stood on porous stone from Corinthia, and beneath it were buried the pieces of two older buildings, deliberately destroyed.'), ('111a0de2-2005-43a9-947f-c5d1bddda27d'::uuid, 'card_description', 'From a lignite mine came the Schöningen Spears: ten wooden weapons of spruce and pine, among the oldest hunting weapons yet found, lying among horse bones marked by butchery.'), ('118c6bd0-cfa1-4376-8f42-34e75bec43d3'::uuid, 'card_description', 'On the slopes of Boat How lie the Burnmoor Stone Circles, approximately 4,000 years old. In the largest, Brat''s Hill, around 42 stones ring five funerary cairns and two further stones.'), ('126756cf-1651-49dd-8075-11e19248b37f'::uuid, 'card_description', 'In the Shilikty Valley of eastern Kazakhstan, Early Saka kurgans held vast quantities of golden jewelry, and in 2003 the remains of a "golden man" were found with 4262 gold finds.'), ('12e0a51b-54c4-4d30-abcb-7ef995ccd49f'::uuid, 'card_description', 'About 3,600 metres up on the slope of the mountain Tawqaray, above the river Watanay, lie the archaeological remains of Wayna Tawqaray, about 5 km southeast of the center of Cusco.'), ('13120650-2e61-45af-976c-b2e0665c49af'::uuid, 'card_description', 'At 1,000 m, at the base of Monte Velino, stood Alba Fucens, an Italic town that sided with Marius, was punished by Sulla, and was completely destroyed by the Saracens in the 10th century.'), ('1328e959-ddab-4dd5-bc24-071540a6ce0d'::uuid, 'card_description', 'Cropmarks gave away the Wicklewood Roman Temple in 1959: the walls of its inner chamber were painted in yellow and black on a red ground, and ornate brooches nearby suggest votive offerings.'), ('139ade22-bf52-47ca-8f98-632fa877adc3'::uuid, 'card_description', 'Near Sidon, a podium 22 metres high once bore the marble Temple of Eshmun, Phoenician god of healing. Canals fed its ritual basins from river and sacred spring, for healing and purification.'), ('13c39c81-106b-4f1d-9975-b729226ab99d'::uuid, 'card_description', 'Among the Dead Cities of northwestern Syria, Baqirha keeps a Roman temple of 161 AD to Zeus Bomos, and an Eastern Church whose west gable, completely preserved, is recognised from afar.'), ('14c0c237-0ece-4124-ada8-8ec56b431b08'::uuid, 'card_description', 'Near Luxor stands the Karnak Temple Complex, main place of worship of the Theban Triad headed by Amun. In its Great Hypostyle Hall, 134 massive columns rise in 16 rows.'), ('14fab6bd-8c5b-4233-816b-a90169bcefea'::uuid, 'card_description', 'In southern Saqqara, a covered causeway ran through the desert from the Nile to the Pyramid of Pepi II, tomb of King Pepi II and the final full pyramid complex built in Ancient Egypt.'), ('152323b2-51d4-4c65-b66c-8d9bd34e5ba8'::uuid, 'card_description', 'On a ridge ringed by deep ravines, Mixco Viejo spreads in fortified groups: over 120 major structures, temples, palaces and ballgame courts of a Postclassic Maya city, a Chajoma capital.'), ('15cf53da-ecf4-4681-a2a7-63984886562f'::uuid, 'card_description', 'Near Sintra, the Roman Bridge of Catribana crosses the Bolelas stream in a single arch of local limestone. Close by lie traces of a Roman-era cemetery and a Neolithic settlement.'), ('15d92d09-d2ec-415d-87ea-88535744e27f'::uuid, 'card_description', 'Oral tradition says the Wotanstein was dug up in the Seven Years'' War for rumoured treasure, but human bones were found instead. In 1407 documents called it the long stone at Madin.'), ('16d71206-b1bd-4575-85b9-14567a8c1c4e'::uuid, 'card_description', 'Early Iron Age, Scythian times: in the village of Khotiv, the Khotiv Hillfort had buildings only near the inner side of its rampart. An archaeological monument since 1965.'), ('17191c2e-9ebc-41e5-865f-1bb6be790eb5'::uuid, 'card_description', 'Above Eynhallow Sound, the Broch of Gurness gathers an Iron Age village around a stone tower that probably once reached around 10 metres, stone-floored galleries between its walls.'), ('17c20887-877e-4427-8728-4c856cc8c0c3'::uuid, 'card_description', 'In Kvemo Kartli lies Sakdrisi, a prehistoric gold mine dated to the early 3rd millennium BC or the second half of the 4th millennium: it might be one of the world''s oldest known gold mines.'), ('18462ce6-cfb7-43ba-83cd-d44c26395227'::uuid, 'card_description', 'On a moor in Cornwall, Zennor Quoit is a ruined dolmen whose chamber of seven upright stones was once covered by a cairn. Digs found flint, Neolithic style pottery and cremated bones.'), ('19ec6c34-0d5d-4a55-9c8d-d0cdda84b9ad'::uuid, 'card_description', 'In the Conwy valley, Pen y Gaer, a Bronze Age and Iron Age hillfort, still shows the remains of its stone walls and a chevaux-de-frise, defences amended over a long history of occupation.'), ('19ed3a0f-09e5-4844-ae5d-9d50bea1371b'::uuid, 'card_description', 'In the Grottos of Juxtlahuaca, painted walls show a large bearded man in a black cloak and a red Feathered Serpent with green plumes. A dozen skeletons were found in the Hall of the Dead.'), ('1a85971c-56a9-411e-bfa9-eda3004219a5'::uuid, 'card_description', 'In the Nam River valley near Jinju, Daepyeong grew into a large central settlement: 144 pit-houses in Eoeun, 115 in Okbang, and many ditches and ditch-enclosures.'), ('1ab97e76-933a-4dc5-a734-42f53c8c7667'::uuid, 'card_description', 'Fir Clump Stone Circle in Burderop Wood was a double oval ring of sarsen megaliths, levelled around the 1860s. Some rediscovered in 1965 were removed in 1969 during construction of the M4.'), ('1bc3b429-ca8e-4bae-93a2-daeefab5e297'::uuid, 'card_description', 'The Roman fort of Aquis Querquennis, built circa 69-79 AD, was flooded by a reservoir in 1949. When its level falls, digs reveal a headquarters, barracks, granaries and a hospital.'), ('1bda8d7d-01e8-4063-b1c1-c2f46c6b9a64'::uuid, 'card_description', 'Once the largest Roman theatre north of the Alps, 116 metres across, the Roman Theatre in Mainz lost its stage foundations in 1884: found, recorded, then demolished for railway tracks.'), ('1c1c8f74-707b-4ad2-a0db-d7518b9138b6'::uuid, 'card_description', 'Oppidum des Castels crowns a hilltop above the Vaunage, where four stages of construction can be detected. The Volques moved in about 300 BCE; Michel Py excavated it between 1958 and 1974.'), ('1cef72f4-b9d4-4180-b93a-10b0cbe1a234'::uuid, 'card_description', 'A spring built the Prison of Solomon: lime settled slowly around its pond into a wall, and when the spring dried, a hollow hill remained, with a pit 80 meters deep at its heart.'), ('1d4dd1f5-e841-4c8c-9761-2d4ad3eec155'::uuid, 'card_description', 'A farmer apparently took Kinniside Stone Circle apart for gate-posts in the 18th century. In 1925 its 11 granite stones were set in concrete, whether in their original holes is unclear.'), ('1da76491-5256-486f-b67e-ff6f762c46b5'::uuid, 'card_description', 'On the English Channel coast, High Peak rises to about 157 metres above sea-level. Geological study suggests the site once extended several tens of metres into what is now eroded away.'), ('1e3e3665-7232-4c54-bceb-9973db4af1e5'::uuid, 'card_description', 'West of Dunster, the oval Iron Age enclosure of Grabbist Hillfort runs 885.8 feet inside a ditch up to 32.8 feet wide. Ploughing has worn away features, a possible inner rampart among them.'), ('1f66729b-c7e8-476a-b9cc-84b23a36074f'::uuid, 'card_description', 'On St Mary''s in the Isles of Scilly, Porth Hellick Down holds at least six entrance graves. Unrecorded digs left the largest, The Great Tomb, empty but for pumice and a few potsherds.'), ('2069e069-c994-46e2-b8b8-f8f8dd01abd0'::uuid, 'card_description', 'In the mountains of Zamora, Peñas de la Cerca controls the middle of the Tera valley: an Iron Age hillfort of about the 7th century BC, several enclosures spread across its north slope.'), ('21ba0be2-3da7-40f7-8f99-aece38b3ea17'::uuid, 'card_description', 'On White Sheet Hill in Wiltshire, a Neolithic causeway camp and barrows share the ground with an Iron Age hill fort, and a Roman road along it was once the main route through Selwood Forest.'), ('21d1b1fc-7be0-456a-9be2-528bf2e7095a'::uuid, 'card_description', 'Above the left bank of the Willkanuta River in the Cusco Region, Machu Q''inti keeps company with the sites of Wayna Q''inti, Willkaraqay and Patallaqta, which is also named Q''inti Marka.'), ('21db0c59-87b1-4d2f-839c-c42543bd56c0'::uuid, 'card_description', 'The Chané, here from about 300 CE, began shaping the great rock of El Fuerte de Samaipata, now almost completely covered in Inca and pre-Inca carvings, among them the spine of the serpent.'), ('2207dced-e1db-4547-bac5-2d90984550a3'::uuid, 'card_description', 'The core of Regensburg''s Old City was once Castra Regina, a Roman fort built in 179 for Legio III Italica under Emperor Marcus Aurelius, at the most northerly point of the Danube.'), ('2297e801-c762-4bb9-9e88-102c65e301a1'::uuid, 'card_description', 'Karatepe-Aslantaş Open-Air Museum holds the ruined walls of Azatiwadaya, an 8th century BC fortress founded by Azatiwada, a local ruler in Cilicia, to defend against invaders from the north.'), ('234bd55f-9444-44e9-8fde-7e66c049561d'::uuid, 'card_description', 'In the Ate District of Lima, Puruchuco was an Inca administrative center, set in Huaquerones, a land of pyramids with ramps that holds one of the largest cemeteries of the Inca culture.'), ('2448ad8b-9e65-4eb8-ac3a-ede7cfcfd8e0'::uuid, 'card_description', 'Inside the fortress Saksaywaman above Cuzco, Muyuq Marka is the base of a round Incan tower: three concentric stone walls, and at the center a web-like pattern of 34 intersecting lines.'), ('24553e33-f5bd-409d-bf2f-04c193eb63cf'::uuid, 'card_description', 'Between Jhatpat and Dera Murad Jamali lie the remains of Judeir-jo-daro, a Harappan-period city in Balochistan once home to around 20,240 people, spread across 62 acres.'), ('24951d4a-ac38-4098-8f55-6e10e5a59c35'::uuid, 'card_description', 'Legend says a local king or chief lies in Kuninkaanhauta, a Bronze Age mound never opened. It was built on the shore of a bay; since then the coastline has moved nearly 20 kilometers west.'), ('257fe33f-735b-46d0-9cb6-83ca0e03937f'::uuid, 'card_description', 'Threestoneburn Stone Circle sets 16 stones of local pink granite in a woodland clearing, four upright. A flint tool was found, and charcoal spreads that may be traces of fire-rituals.'), ('261ab0dd-0674-4864-9162-87b179787403'::uuid, 'card_description', 'On the western side of the Cordillera Negra, at about 4,200 metres, lies Hatun Machay: a rock forest with archaeological remains, its name possibly from the Quechua words for big and cave.'), ('270204ad-72e5-451b-829b-9c04ece99766'::uuid, 'card_description', 'Above Goblin Combe lies Cleeve Toot, a roughly oval Iron Age hillfort ringed by a single stone rampart and a broad, shallow outer ditch. Pits found here point to round houses.'), ('2715f436-40ec-4225-b5b6-8cc9523b2048'::uuid, 'card_description', 'At Dahshur, the Bent Pyramid of Pharaoh Sneferu rises from the desert at 54 degrees, then above 47 metres turns to a shallower 43 degrees. Two entrances lead to two separate chamber systems.'), ('27226cef-1c90-46cc-ac31-6b568c7f6c8a'::uuid, 'card_description', 'Duropolis in Dorset is believed to be Britain''s first planned town. Remains of 16 Iron Age roundhouses were dug up, and animal skeletons may hint at a belief in hybrid-animal monster myths.'), ('277970ce-65f8-403a-8e20-dbcadac0f214'::uuid, 'card_description', 'Eston Nab, a sandstone cliff at 242 metres, bears Bronze Age burial mounds and the boulder walls of an Iron Age hill fort built around 700 BC. Parts of a cremation urn were unearthed.'), ('27f27e7e-4224-4378-b0d2-ef22f88bd725'::uuid, 'card_description', 'Atop Monte Adranone, 900 metres up, lie the imposing ruins of a city, possibly Adranon, that dominated the road from Selinunte to Akragas until it was destroyed in the 3rd century BC.'), ('28579aa8-dab5-444d-9ee0-61c95cd1c073'::uuid, 'card_description', 'Viracochapampa, its name possibly from the Andean divinity Wiracocha, holds a pre-Inca building complex at 3,070 metres: a Wari administrative center, occupied in the 7th and 8th centuries.'), ('2882893b-da7b-4afa-bd4a-e8d4ffb76dcd'::uuid, 'card_description', 'Water kept the land around the Roman Villa of Freiria inhabited for ages: a Palaeolithic site lies 300 metres to the north, traces of a Chalcolithic settlement 200 metres northeast.'), ('28b7b9c1-3901-4762-a71f-353d6ba8b513'::uuid, 'card_description', 'North of Doncaster, the bridleway of Roman Ridge was part of Ermine Street, a Roman road. It runs past Scawsby and Highfields to the Great North Road, then joins the A1 as far as Barnsdale.'), ('29245d49-3e8c-4c31-baf4-a3cdd54a8964'::uuid, 'card_description', 'Patara, for a period the capital of Lycia, was said to be founded by Patarus, a son of Apollo. Its temple and oracle of Apollo were second only in importance to that of Delphi.'), ('29efc463-cdf8-4dd6-849b-ff378c87a2de'::uuid, 'card_description', 'North of Lake Paucarcocha lies Pirca Pirca, a site whose name possibly comes from the Aymara and Quechua word for wall. In 2013 it was declared a National Cultural Heritage of Peru.'), ('2a37333e-17ba-4a27-8084-3759d0b8501f'::uuid, 'card_description', 'In Tham Lod Rockshelter, a 30 metre deep cave by the Nam Lang stream, lay hearths, a tool workshop with at least 1722 stone artifacts, and four human burials, two laid one above the other.'), ('2ac1dae4-0ddb-4592-ae5d-1b628466832d'::uuid, 'card_description', 'No ancient author mentioned Kitanaura Antik Kenti, a Lycian city with walls from Hellenistic to Byzantine times. Five churches hint at its later rise, and coins revealed its name in 1998.'), ('2adae6b7-2156-4080-aaa0-921dd7f8a9c9'::uuid, 'card_description', 'Near the Pembrokeshire Coast Path, a capstone 4.7 metres by 2.7 metres rests on three of six stones: Carreg Samson, a 5000-year-old dolmen whose gaps were once blocked to shelter sheep.'), ('2b7bb7a9-4759-41bf-a703-8f4da42a1b5c'::uuid, 'card_description', 'In the Toquepala Caves, painted scenes show armed people corralling and killing a group of guanacos, rock art of gatherer-hunters inferred to have lived here about 10,000 years ago.'), ('2bf713bc-9782-4f70-9a9f-4b93fd1d5b15'::uuid, 'card_description', 'A rock collapse sealed the entrance of Tito Bustillo Cave thousands of years ago, preserving tools and wall paintings found in 1968. The oldest shows human figures, around 33,000 years old.'), ('2c0b2769-f00d-418a-853b-f1bd62f245cb'::uuid, 'card_description', 'At Nemea, an ancient sanctuary of Zeus in the Peloponnese, games were documented from 573 BC, or earlier. Digs since 1973 unearthed a great open-air altar, baths and lodgings for visitors.'), ('2c780872-8603-4ff7-b740-147b3cd5f22f'::uuid, 'card_description', 'In Axum, King Ezana''s Stele stands 21 m tall amid hundreds of smaller stelae, a false door at its base and window-like apertures on all sides. It is likely the last of its kind.'), ('2cbc1c11-5750-4b96-973b-7f1f8c847003'::uuid, 'card_description', 'Makers of grooved ware once lived at Skara Brae on the Bay of Skaill, in stone houses laid out alike: a central hearth, beds on either side and a dresser opposite the entrance.'), ('2cce98a2-9851-42c7-9e9e-47f39b12be9c'::uuid, 'card_description', 'At 279 m, Lewesdon Hill is the highest point in Dorset. An Armada Beacon stood here in 1588, and parts of a possible bank and ditch remain, though its status as a hillfort is disputed.'), ('2cd65076-e10c-401f-a997-296f99badf9c'::uuid, 'card_description', 'On the summit of Bredon Hill lie the earthworks of Kemerton Camp, an Iron Age hill fort believed abandoned after a considerable battle, beside the great Banbury Stone.'), ('2ce50a62-f812-4204-bbb6-892a581fee52'::uuid, 'card_description', 'Archaeologists reckon the Amelungsburg on the Süntel ridge took up to six weeks to build in the pre-Roman Iron Age, its rampart hiding a dry stone wall about 3 metres wide.'), ('2cea8e97-21f2-4d79-95f3-c00ef69985eb'::uuid, 'card_description', 'A curvilinear La Tène style design covers the top half of the Turoe Stone in County Galway, probably from about 100 BC to AD 100. Its religious or ceremonial purposes are lost in time.'), ('2dab79e8-1ece-4f9b-beb3-a91573d545c3'::uuid, 'card_description', 'On Rapa Nui, Ahu Akivi is a sacred place looking out toward the Pacific Ocean, where seven moai of equal size stand on the flank of Maunga Terevaka, built by the Rapa Nui people.'), ('2dceb336-e4a4-4a99-9f88-00c83aaa0088'::uuid, 'card_description', 'Rastrojón was built on a geological fault just two kilometres from Copán. When the Maya kingdom of Copán collapsed in 822, the site was abandoned, perhaps no longer worth the effort.'), ('2e46252e-2205-4aed-92ee-38eeb5758399'::uuid, 'card_description', 'Domica Cave in Slovakia is well known for its complex structure and dense speleothems. Post holes from dwelling objects and fireplaces were discovered in several places of the cave.'), ('2e648c8e-56af-4349-8064-6372c29b3d25'::uuid, 'card_description', 'The Skorba Temples hold paving slabs with libation holes in an entrance passage and the torba floor of a three-apse temple, insight into the earliest periods of Malta''s Neolithic culture.'), ('2f217cc8-9aad-4f87-93fb-c8732fe85e39'::uuid, 'card_description', 'Portus Lemanis, a Roman Saxon Shore fort, stood on a hill over a reach of sea since drained to form Romney Marsh. Its southern side is wholly missing, its remains moved at various angles.'), ('2f44fbd5-7420-4904-8ef9-3bb2c7a15064'::uuid, 'card_description', 'Statues locals call Palindo and Tarae Roe show faces with brow and nose as one and no mouth: the Bada Valley Megaliths, where lidded burial jars 1.5-2 meters in diameter were found.'), ('2fe3e1da-dcae-4014-a4d9-8b3132952546'::uuid, 'card_description', 'On a hill northeast of Pitumarka, at the southern shore of the river Ch''illkamayu, Machu Pitumarka is a site of ruined walls in Canchis Province, in Peru''s Cusco Region.'), ('316b3d27-1295-41ce-a5c0-3b9c8251647e'::uuid, 'card_description', 'In 2002 a Tunghai University student, Chen Sheng-ming, found Huilai Monument Archaeology Park in Taichung. Investigation revealed a site of 1,500,000 m2, now a City Archaeological Area.'), ('333b1b12-dfb2-4ee3-a3c0-4af360dd498f'::uuid, 'card_description', 'Veterans of the Legio VII Claudia settled Scupi by the Vardar River, to archaeologist Mikulčić the largest known Roman settlement in the region, abandoned in AD 518 after an earthquake.'), ('33e2399e-fd68-4aab-bf79-c5695a6c0bf0'::uuid, 'card_description', 'Its name possibly joins the Tarma, an ethnic group, with the Quechua word tampu, an inn: Tarmatambo, an archaeological site in the Junín Region, declared National Cultural Heritage in 2002.'), ('3415ea00-bddf-4f1d-bed2-7ce85b6c5871'::uuid, 'card_description', 'Above Worbarrow Bay, the southern part of Flower''s Barrow, an Iron Age hillfort, is falling into the sea. Hut circles lie within; a 1939 dig found sling-stones near the western entrance.'), ('34f1acbd-b1d2-4349-9946-75a36f323d6b'::uuid, 'card_description', 'On the Roman route from Lissus through Naissus to Ratiaria, 60 km northeast of Naissus, stands Timacum Minus, the oldest military fort in the Timok Valley. Its counterpart lies near Svrljig.'), ('353f7688-f230-41ef-a181-8bd9341448cf'::uuid, 'card_description', 'On the highest point of Bodmin Moor, 1,378 feet up, the summit pile of the Brown Willy Cairns has never been excavated. Folklore suggests an ancient Cornish king may lie entombed underneath.'), ('35fedad2-8a41-4fd4-8327-86fd30853551'::uuid, 'card_description', 'On a hill above the River Severn, the Iron Age hillfort of Cefn Carnedd runs about 437 metres, triple banks and ditches on its north-west side. Aerial photos show traces of an earlier fort.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s017-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
